window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-cirurgia-med-cir-04"]={"block":"med:med-cirurgia-med-cir-04","label":"MED · MED CIR 04","count":399,"questions":[{"id":"med-cirurgia-med-cir-04-345494","number":"345494","sourceNumber":"345494","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Escolar de 8 anos, feminino, é levada à emergência Pediátrica com história de febre\nintermitente há 21 dias, além de astenia, anorexia, perda de peso (não sabe dizer quantos quilos).\nDados positivos no exame físico: palidez 2+/4+, fígado palpável a 4cm do rebordo costal direito e\nbaço palpável a 4 cm do rebordo costal esquerdo. Sobre isso, assinale a afirmativa CORRETA:","options":{"A":"Se o hemograma evidenciar pancitopenia, o exame complementar mais urgente a ser realizado\nem seguida é a dosagem do FAN (fator antinúcleo\nou anticorpos antinucleares).","B":"Se o hemograma evidenciar anemia e plaquetose, deve ser solicitado FR (fator reumatoide) para\nfechar o diagnóstico de Artrite Idiopática Juvenil.","C":"Devido à febre prolongada, deve ser iniciada antibioticoterapia empírica de amplo espectro, com\nceftriaxona 100mg/kg/dia.","D":"Se houver evolução com diarreia e enterorragia, a realização de mielocultura está indicada para\ninvestigação de febre tifóide."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-345517","number":"345517","sourceNumber":"345517","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Assinale a alternativa que apresenta as indicações formais para a exploração cirúrgica:","options":{"A":"Febre, dor abdominal e hérnia.","B":"Instabilidade hemodinâmica, peritonite, evisceração e empalamento.","C":"Choque, vômito e diarreia.","D":"Hematoma de parede, arritmia cardíaca e insuficiência respiratória."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-291772","number":"291772","sourceNumber":"291772","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente, sexo feminino, 69 anos de idade, é trazida por familiares ao Pronto Socorro\ncom queixa de dor abdominal, de forte\nintensidade, há uma hora. A paciente relata início súbito da\ndor, associada à náuseas, vômitos e hiporexia. A filha refere que a paciente é portadora de\nfibrilação atrial, hipertensão arterial e diabetes mellitus, fazendo uso regular das medicações. Ao\nexame, bom estado geral, FC: 108bpm, PA: 128x86mmHg, FR: 22ipm; ausculta respiratória:\nmurmúrios vesiculares bem distribuídos e sem ruídos adventícios; ausculta cardíaca: bulhas\narrítmicas, normofonéticas e com sopro sistólico em foco aórtico; FC: abdome um pouco distendido,\ncom ruídos hidroaéreos diminuídos, dor à palpação difusa, com descompressão brusca negativa.\n\nDe acordo com o caso descrito, Indique a principal suspeita diagnóstica que justifique o quadro\nclínico da paciente.","options":{"A":"Apendicite aguda.","B":"Pancreatite aguda.","C":"Isquemia mesentérica aguda.","D":"Diverticulite aguda no sigmoide."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-291773","number":"291773","sourceNumber":"291773","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente, sexo feminino, 69 anos de idade, é trazida por familiares ao Pronto Socorro\ncom queixa de dor abdominal, de forte\nintensidade, há uma hora. A paciente relata início súbito da\ndor, associada à náuseas, vômitos e hiporexia. A filha refere que a paciente é portadora de\nfibrilação atrial, hipertensão arterial e diabetes mellitus, fazendo uso regular das medicações. Ao\nexame, bom estado geral, FC: 108bpm, PA: 128x86mmHg, FR: 22ipm; ausculta respiratória:\nmurmúrios vesiculares bem distribuídos e sem ruídos adventícios; ausculta cardíaca: bulhas\narrítmicas, normofonéticas e com sopro sistólico em foco aórtico; FC: abdome um pouco distendido,\ncom ruídos hidroaéreos diminuídos, dor à palpação difusa, com descompressão brusca negativa.\n\nDe acordo com o caso descrito, Determine o exame complementar mais indicado para confirmar o\ndiagnóstico.","options":{"A":"Radiografia de abdome em decúbito dorsal e em ortostase.","B":"Ressonância nuclear magnética do abdome.","C":"Angiotomografia computadorizada do abdome.","D":"Videolaparoscopia."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-283311","number":"283311","sourceNumber":"283311","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente sexo feminino, 28 anos, multípara, apresentou quadro de dor em andar\nsuperior do abdome, em barra, início súbito,\nde forte intensidade e vômitos incoercíveis. Evolução\nde 2 dias. Refere plenitude pós-prandial de longa data. Ao exame físico apresenta-se ictérica +/+4,\ndesidratada e taquicárdica. O abdome é difusamente doloroso à palpação, mais intensamente em\nepigástrica. Considerando a hipótese de pancreatite biliar, qual a resposta correta?","options":{"A":"Estabilizar hemodinamicamente e indicar papilotomia endoscópica.","B":"Estabilizar hemodinamicamente e indicar videocolecistectomia.","C":"Após normalização das enzimas pancreáticas e voltar a alimentação sem dor, indicar\nvideocolecistectomia.","D":"Após normalização das enzimas pancreáticas e voltar a alimentação sem dor, indicar\npapilotomia endoscópica."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-281147","number":"281147","sourceNumber":"281147","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente de 8 anos, sexo feminino, com história de dor abdominal recorrente a cada 2\nsemanas, há 3 anos. A dor abdominal é difusa, de forte intensidade, associada a náuseas, recusa\nalimentar, vômitos, cefaleia, fraqueza e parestesias em membros inferiores. Perdeu 5 kg nesse\nperíodo. Nega febre, alteração do hábito intestinal ou história de sangramento. Tem história\npregressa de ter recebido 2 transfusões sanguíneas em 2 dos internamentos por dor abdominal.\nHistória familiar positiva para consanguinidade. Ao exame abdominal: abdome plano, flácido,\nindolor à palpação, com presença de fígado palpável a 3 cm do rebordo costal direito, na linha\nhemiclavicular, e baço no rebordo costal esquerdo. O diagnóstico provável é de:","options":{"A":"febre familiar do mediterrâneo.","B":"porfiria aguda intermitente.","C":"dor abdominal funcional.","D":"enxaqueca abdominal.","E":"doença inflamatória intestinal, provavelmente retocolite ulcerativa."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-281170","number":"281170","sourceNumber":"281170","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente feminina, 50 anos, apresenta quadro de pancreatite aguda biliar. Qual dos\nseguintes achados representa o melhor fator preditivo da persistência de cálculos na via biliar\nprincipal?","options":{"A":"Lipase sérica à admissão superior a 1.000 u/l.","B":"Persistência de níveis séricos de amilase aumentados.","C":"Elevação persistente da bilirrubina.","D":"Presença de colédoco dilatado à admissão.","E":"Persistência de dor abdominal."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-251864","number":"251864","sourceNumber":"251864","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente masculino de 50 anos, com história de etilismo, chega a UPA com quadro de\ndor abdominal em faixa de forte intensidade e vômitos. Tem dor à palpação epigástrica e está\nafebril. Estável hemodinamicamente. Os exames demonstram um hemograma com 15.000\nleucócitos, amilase de 1.200 mg/dl e glicemia de 145 mg/dl. Qual a conduta mais correta?","options":{"A":"Encaminhar para internação hospitalar, antibioticoterapia e alta se houver melhora em 24h.","B":"Encaminhar para internação hospitalar, antibioticoterapia, hidratação parenteral, analgesia e\nalta\npós melhora do quadro.","C":"Encaminhar para internação hospitalar, analgesia, hidratação parenteral, jejum e alta após\nmelhora clínica.","D":"Observação na UPA por 24h, analgesia e alta após melhora clínica."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-247217","number":"247217","sourceNumber":"247217","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Assinale a alternativa que responde CORRETAMENTE à pergunta abaixo. Qual a\nmelhor conduta no caso de apendalgite\n(epiploite) diagnosticada pré-operatoriamente por exame de\ntomografia computadorizada?","options":{"A":"Laparotomia exploradora.","B":"Tratamento conservador.","C":"Exérese Cirúrgica.","D":"Colectomia direita.","E":"Ressecção do ceco."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-251939","number":"251939","sourceNumber":"251939","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Nos casos de diverticulite aguda tipo Hinchey III, a conduta correta é:","options":{"A":"Colostomia em alça.","B":"Cirurgia de Hartmann.","C":"Ressecção do seguimento afetado e anastomose primária.","D":"Sutura do divertículo com drenagem."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-247222","number":"247222","sourceNumber":"247222","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Assinale a alternativa que responde CORRETAMENTE à pergunta abaixo. Em casos\nnão clássicos de apendicite aguda, qual o estudo\nde imagem de escolha?","options":{"A":"Ultrassonografia abdominal.","B":"Enema opaco.","C":"Raio X de abdome em decúbito lateral direito.","D":"Cintilografia com radionuclídeos.","E":"Tomografia computadorizada."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-251956","number":"251956","sourceNumber":"251956","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Sobre o quadro clínico da apendicite, qual a opção CORRETA?","options":{"A":"EAS com piúria afasta o diagnóstico.","B":"A dor é sempre localizada em fossa ilíaca direita.","C":"Pode cursar com diarréia em sua fase inicial.","D":"A USG sempre determina o diagnóstico."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-251957","number":"251957","sourceNumber":"251957","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"As principais causas de pancreatites são a biliar e alcoólica, porém causas mais raras\nnão devem ser negligenciadas, o \"pancreas\ndivisum\" é uma delas e deve-se a:","options":{"A":"Trauma abdominal contuso contra a coluna.","B":"Lesão iatrogênica durante laparotomia interessando vias biliares.","C":"Lesão criptogenética.","D":"Defeito de fusão dos ductos cefálicos e dorsal."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-217685","number":"217685","sourceNumber":"217685","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente, sexo masculino, 49 anos, etilista durante 30 anos, 500 ml/dia de bebida\ndestilada. Há 1 ano apresenta dor em andar superior do abdome, em barra, de forte intensidade\nmesmo estando em abstinência há 6 meses. O RX de abdome revela múltiplas calcificações em\ntopografia do pâncreas. Considerando-se o diagnóstico de pancreatite crônica, qual a indicação\ncirúrgica nesse paciente?","options":{"A":"Formação de pseudocisto de pâncreas.","B":"Associação com esteatorreia.","C":"Diabetes mellitus de difícil controle.","D":"Dor intratável."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-183226","number":"183226","sourceNumber":"183226","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação à isquemia mesentérica aguda, assinale a alternativa INCORRETA.","options":{"A":"Digitálicos e diuréticos podem ser fatores predisponentes para a isquemia arterial não-oclusiva.","B":"A isquemia segmentar focal ocorre em, aproximadamente, 30% dos casos de isquemia\nmesentérica e tem melhor prognóstico que a Trombose Mesentérica.","C":"A dor abdominal é de início súbito, de forte intensidade e está presente em 75% a 98% dos\ncasos de isquemia mesentérica aguda.","D":"A taxa de mortalidade é de 70% a 90%.","E":"As angiografias, especialmente a aortografia e a arteriografia seletiva das artérias mesentéricas\nsuperior e inferior, representam os\nmétodos propedêuticos de escolha."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-182645","number":"182645","sourceNumber":"182645","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente masculino, 67 anos, refere dor em FIE e febre baixa com evolução de 8 dias.\nAo exame físico: dor à palpação superficial e profunda em FIE com descompressão brusca\ndolorosa. Qual a hipótese diagnóstica?","options":{"A":"Diverticulite colônica.","B":"Infarto entero-mesentérico.","C":"Doença inflamatória pélvica.","D":"Doença inflamatória intestinal."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-182625","number":"182625","sourceNumber":"182625","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente masculino, 17 anos, refere dor em FE com evolução de 7 dias, associado à\nfebre de 39ªC e há 2 dias apresenta flexão antálgica de MIE. Qual a melhor hipótese diagnóstica?","options":{"A":"Piomiosite de músculo psoas esquerdo.","B":"Pionefrose esquerda.","C":"Diverticulite colônica.","D":"Apendagite epiplóica."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-159054","number":"159054","sourceNumber":"159054","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente sexo masculino, 68 anos. Há 4 dias refere dor abdominal intensa, que\naumentou progressivamente. Ao exame físico apresenta\nRCI em 2 tempos, abdome difusamente\ndoloroso com descompressão brusca dolorosa, ruídos hidro-aéreos diminuídos. Qual a melhor\nhipótese diagnóstica?","options":{"A":"Obstrução intestinal.","B":"Apendicite aguda.","C":"Diverticulite.","D":"Infarto entero-mesentérico."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-135892","number":"135892","sourceNumber":"135892","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Na avaliação tomográfica da pancreatite aguda, qual o significado da classificação de\nBALTHAZAR C?","options":{"A":"Pâncreas normal;","B":"Perda dos contornos pancreáticos;","C":"Edema do pâncreas;","D":"Opacidade peri-pancreática;"},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-135963","number":"135963","sourceNumber":"135963","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Assinale o Sinal semiológico e sua apresentação correta:","options":{"A":"Sinal de Courvoisier terrier: Icterícia e uma vesícula biliar distendida sem dor;","B":"Sinal de Joubert: Percussão Timpânica em hipocôndrio esquerdo;","C":"Sinal de Lennander: Dor a punho percussão de região lombar;","D":"Sinal de Chvostek: espasmo carpal, manifestado como flexão do punho;"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-135941","number":"135941","sourceNumber":"135941","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Umas das complicações da pancreatite aguda é o pseudo-cisto de pâncreas. O que o\ndiferencia de um cisto verdadeiro?","options":{"A":"O cisto verdadeiro é sempre congênito, ao contrário do pseudocisto;","B":"O epitélio do pseudocisto é colunar e do cisto estratificado;","C":"O pseudocisto não tem epitélio, ao contrário do cisto verdadeiro.","D":"O epitélio do cisto verdadeiro é colunar e o do pseudocisto estratificado;"},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-108671","number":"108671","sourceNumber":"108671","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Sobre o quadro clínico da apendicite, qual a opção CORRETA?","options":{"A":"EAS com piúria afasta o diagnóstico.","B":"A dor é sempre localizada em fossa ilíaca direita.","C":"Pode cursar com diarreia em sua fase inicial.","D":"A USG sempre determina o diagnóstico."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-108733","number":"108733","sourceNumber":"108733","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"<p>Paciente masculino, 56 anos, etilista durante 30 anos, 500 ml de destilado ao dia.\nHá 1 ano apresenta crises de dor em andar superior do abdome, em barra, de forte intensidade,\nassociada a vômitos. O RX de abdome revela múltiplas calcificações em topografia do pâncreas.\nConsiderando-se um diagnóstico de pancreatite crônica, quando esse paciente tem indicação de\ntratamento cirúrgico? </p>","options":{"A":"Em casos em que se associa o Diabetes Mellitus.","B":"Se apresentar hemorragia digestiva alta.","C":"Quando a dor se torna intratável.","D":"Se evoluir com pseudocisto."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-108736","number":"108736","sourceNumber":"108736","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Nos casos de diverticulite aguda tipo Hinchey III, a conduta CORRETA é:","options":{"A":"Colostomia em alça;","B":"Cirurgia de Hartmann;","C":"Ressecção do seguimento afetado e anastomose primária;","D":"Sutura do divertículo com drenagem."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-84463","number":"84463","sourceNumber":"84463","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação à doença de crohn, é incorreto afirmar: I - perfuração livre ou hemorragia\nmaciça são indicações de cirurgia de urgência. II- megacólon tóxico sem resposta inicial ao\ntratamento clínico deverá ser tratado com colectomia subtotal. III- as fístulas enterovesicais são\ncirúrgicas na maioria das vezes.","options":{"A":"apenas I.","B":"apenas III.","C":"I e III.","D":"I, II e III.","E":"apenas III."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-84464","number":"84464","sourceNumber":"84464","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A indicação cirúrgica mais comum nos casos de doença de Crohn decorre de:","options":{"A":"Perfuração livre.","B":"Hemorragia maciça.","C":"Degeneração maligna.","D":"Obstrução intestinal.","E":"Diarreia frequente."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-84484","number":"84484","sourceNumber":"84484","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Causa de megacólon tóxico:","options":{"A":"Fecaloma.","B":"Retocolite ulcerativa.","C":"Diverticulite.","D":"Megacólon Chagásico.","E":"Trombose hemorroidária complicada."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-84510","number":"84510","sourceNumber":"84510","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"São sinais clínicos e laboratoriais da trombose mesentérica, EXCETO:","options":{"A":"Dor abdominal localizada no compartimento central do abdome, de forte intensidade e que\napresenta remissão com o uso de opiáceos.","B":"A distensão abdominal é de aparecimento tardio, seguindo-se ao quadro álgico.","C":"Choque e peritonite indicam evolução tardia, com possibilidade de cura remota.","D":"Grandes oclusões venosas podem levar a quadro precoce de choque.","E":"A amilase sérica encontra-se elevada em 50% dos pacientes."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-84471","number":"84471","sourceNumber":"84471","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Sobre pancreatite aguda, todas são verdadeiras, EXCETO:","options":{"A":"A classificação quanto à gravidade é MODERADA: quando não há falência de órgãos ou há\nfalência de órgãos com duração menor do que 48 horas com ou sem complicações locais.","B":"A presença de enzimas pancreáticas elevadas ou coleções líquidas não são contraindicações\npara o início da alimentação oral ou enteral.","C":"Em pacientes com pancreatite leve por causa biliar devem ser colecistectomizados com\nsegurança após 7 dias de recuperação e ainda na mesma hospitalização.","D":"Os níveis da elevação de enzimas pancreáticas no sangue é diretamente proporcional à\ngravidade do quadro.","E":"Antibioticoprofilaxia não é recomendada."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-37104","number":"37104","sourceNumber":"37104","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Não constitui sinal de alerta na dor abdominal funcional:","options":{"A":"Interrompe as atividades normais.","B":"Alteração ritmo intestinal.","C":"Vômitos.","D":"Anorexia.","E":"Dor que o desperta à noite."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-29357","number":"29357","sourceNumber":"29357","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente, 38 anos, com antecedente de dislipidemia, apresentou subitamente em andar\nsuperior do abdome, dor em faixa com irradiação para região dorsal, náuseas, vômitos. Ao exame\nfísico nota-se, icterícia, manchas equimóticas periumbilical, além de ascite. Qual parâmetro não é\nsinal prognóstico à internação?","options":{"A":"AST >250U/L","B":"DHL>350 U/L","C":"Glicemia > 200 mg/dl","D":"Idade > 55 anos","E":"Queda do hematócrito >10%"},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-369536","number":"369536","sourceNumber":"369536","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Diante do caso clínico e dos exames complementares, indique a principal suspeita\ndiagnóstica para este paciente:","options":{"A":"Gastroenterocolite aguda.","B":"Diverticulite aguda de Meckel.","C":"Apendicite aguda.","D":"Diverticulite aguda cecal."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-369537","number":"369537","sourceNumber":"369537","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente, sexo masculino, 12 anos de idade, é levado ao Pronto-Socorro pela genitora,\ncom queixa de dor abdominal difusa há dois\ndias. O paciente refere, também, hiporexia, alguns\nepisódios de náuseas, vômitos e diarreia. Ao exame físico, bom estado geral, temperatura axilar:\n38.2°C, FC: 82 bpm, PA: 110x74mmHg; ausculta cardíaca e respiratória sem alterações; abdome\num pouco distendido, ruídos hidroaéreos presentes, flácido, dor à palpação profunda de\nmesogástrio e fossa ilíaca direita, com sinais de irritação peritoneal. Os exames laboratoriais\niniciais\napresentaram Hb: 13g/dL, Ht: 36%, Leucócitostotais: 12500células/mm³ (Bastões: 5%). Indique a\nconduta mais adequada neste momento:","options":{"A":"Iniciar antibioticoterapia e observação em leito de enfermaria.","B":"Solicitar tomografia computadorizada de abdome com contraste.","C":"Coletar hemoculturas, iniciar antibioticoterapia e internar em Unidade de Terapia Intensiva.","D":"Realizar laparotomia por incisão oblíqua em fossa ilíaca direita."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-343200","number":"343200","sourceNumber":"343200","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Jovem, masculino, há 3 dias com hiporexia, náuseas, desconforto epigástrico,\nqueixando-se hoje de piora da dor, mais\nlocalizada em fossa ilíaca direita associada a 2 picos de\nfebre aferida. Ao exame físico: bom estado geral, corado, hidratado, eupneico, anictérico. Exame\nfísico cardiopulmonar normal, exceto leve taquicardia. Ruídos abdominais presentes, sem\nalterações na inspeção, porém com dor a palpação de fossa ilíaca direita. Sinal de Blumberg\npresente. Foi submetido a exames laboratoriais que resultaram em um escore de Alvarado de 10\npontos. Não há exames de imagem disponível no serviço. A conduta mais adequada é:","options":{"A":"Transferência para realizar tomografia de abdome.","B":"Cirurgia.","C":"Alta com sintomáticos.","D":"Anti-inflamatório não hormonal e reavaliação em 48h."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-343201","number":"343201","sourceNumber":"343201","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente feminina, 80 anos, internada com diverticulite aguda, submeteu-se à\ntomografia de abdome com contraste endovenoso\nque evidenciou processo inflamatório colônico\ncom divertículos e a presença de coleção pélvica bloqueada. Trata-se de diverticulite aguda,\nclassificada por Hinchey (clássica) em grau:","options":{"A":"II","B":"III","C":"IV","D":"IV"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-343202","number":"343202","sourceNumber":"343202","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Jovem, masculino, 32 anos, é internado por episódios de vômitos de início há 24 horas,\nassociado a dor abdominal refratária à analgésicos simples. Nega febre. Nega trauma recente.\n\nNega sintomas urinários. Refere anorexia. Ao exame físico: regular estado geral, desidratado\n\n+++/4, corado, anictérico, afebril, taquicárdico. Ausculta pulmonar normal. Abdome com cicatriz\nprévia de laparotomia mediana por trauma (há\n3 anos), distendido, ruídos abdominais muito\nreduzidos, doloroso em epigástrio e todo andar superior, mas sem sinais de peritonite. Realizou\nradiografia (abaixo) e foi submetido a ultrassonografia que visualizou vesícula biliar com parede de\n3 mm, com cálculos em seu interior, múltiplos, todos com tamanho menor que 5 mm, e ducto\ncolédoco com 4 mm. O pâncreas não foi visualizado por interposição gasosa. A principal hipótese\ndiagnóstica e o tratamento mais adequado é:","options":{"A":"Pancreatite aguda biliar - jejum, analgesia e hidratação, e posteriormente colecistectomia.","B":"Colecistite aguda - colecistectomia.","C":"Colecistite aguda - colangiopancreatografia retrógrada endoscópica.","D":"Bridas - cirurgia de Hartmann."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-315162","number":"315162","sourceNumber":"315162","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente com diagnostico de pancreatite crônica internado por massa palpável em\nepigástrio com aparecimento após episódio de agudização da pancreatite. Qual das seguintes\ncomplicações é a mais provável?","options":{"A":"Ascite pancreática.","B":"Neoplasia pancreática.","C":"Pseudocisto pancreático.","D":"Trombose de veia esplênica.","E":"Pseudoaneurisma roto."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-315163","number":"315163","sourceNumber":"315163","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Dentre os achados abaixo, o mais típico da isquemia intestinal aguda é:","options":{"A":"O vômito.","B":"A taquicardia.","C":"A diarréia sanguinolenta.","D":"A dor desproporcional ao exame físico.","E":"A febre."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-314216","number":"314216","sourceNumber":"314216","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"É causa mais comum de fístula entre o cólon e a bexiga:","options":{"A":"Câncer.","B":"Retocolite ulcerativa.","C":"Diverticulite aguda do cólon.","D":"Doença de Crohn."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-314217","number":"314217","sourceNumber":"314217","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente em investigação de diverticulite aguda é submetida à tomografia de abdome\nabaixo. Além de podermos classificar a gravidade da doença, nota-se também uma complicação\nlocal. Trata-se da:","options":{"A":"Fístula cutânea.","B":"Pneumoperitônio.","C":"Fístula vesical.","D":"Fístula vaginal."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-275975","number":"275975","sourceNumber":"275975","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A pancreatite aguda é caracterizada como uma resposta inflamatória do pâncreas a um\nconjunto possível de situações. Dentre os fatores etiológicos listados abaixo, qual alternativa\n\nrefere-se aos de maior prevalência?","options":{"A":"Fibrose cística e causas genéticas.","B":"Hipertrigliceridemia e causa medicamentosa.","C":"Litíase biliar e alcoólica.","D":"Neoplasia e traumática.","E":"Infecciosa e vascular."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-279041","number":"279041","sourceNumber":"279041","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Podemos classificar o abdome agudo, do ponto de vista sindrômico, em 4 grandes\ntipos. Das alternativas abaixo assinale\naquela que não representa uma classificação sindrômica do\nabdome agudo.","options":{"A":"Hemorrágico.","B":"Inflamatório.","C":"Perfurativo.","D":"Parasitário."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-283727","number":"283727","sourceNumber":"283727","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente, sexo feminino, 69 anos de idade, é trazida por familiares ao pronto-socorro\ncom queixa de dor abdominal, de forte\nintensidade, há uma hora. A paciente relata inicio súbito da\ndor, associada à náuseas, vômitos e hiporexia. A filha refere que a paciente é portadora de\nfibrilação atrial, hipertensão arterial e diabetes mellitus, fazendo uso regular das medicações. Ao\nexame, bom estado geral, FC: 108 bp, PA: 128 x 86 mmHg, FR: 22 ipm; ausculta respiratória:\nmurmúrios vesiculares bem distribuídos e sem ruídos adventícios, ausculta cardíaca: bulhas\narrítmicas, normofonéticas e com sopro sistólico em foco aórtico; FC: abdome um pouco distendido,\ncom ruídos hidroaéreos diminuídos, dor a palpitação difusa, com descompressão brusca negativa.\nDe acordo com o caso descrito. Indique a principal suspeita diagnóstica que justifique o quadro\nclínico da paciente.","options":{"A":"Apendicite aguda.","B":"Pancreatite aguda.","C":"Isquemia mesentérica aguda.","D":"Diverticulite aguda no sigmoide."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-283728","number":"283728","sourceNumber":"283728","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente, sexo feminino, 69 anos de idade, é trazida por familiares ao pronto-socorro\ncom queixa de dor abdominal, de forte\nintensidade, há uma hora. A paciente relata inicio súbito da\ndor, associada à náuseas, vômitos e hiporexia. A filha refere que a paciente é portadora de\nfibrilação atrial, hipertensão arterial e diabetes mellitus, fazendo uso regular das medicações. Ao\nexame, bom estado geral, FC: 108 bp, PA: 128 x 86 mmHg, FR: 22 ipm; ausculta respiratória:\nmurmúrios vesiculares bem distribuídos e sem ruídos adventícios, ausculta cardíaca: bulhas\narrítmicas, normofonéticas e com sopro sistólico em foco aórtico; FC: abdome um pouco distendido,\ncom ruídos hidroaéreos diminuídos, dor a palpitação difusa, com descompressão brusca negativa.\nDe acordo com o caso descrito. Determine o exame complementar mais indicado para confirmar o\ndiagnóstico.","options":{"A":"Radiografia de abdome em decúbito dorsal e em ortostase.","B":"Ressonância nuclear magnética do abdome.","C":"Angiotomografia computadorizada do abdome.","D":"Videolaparoscopia."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-283729","number":"283729","sourceNumber":"283729","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente, sexo feminino, 69 anos de idade, é trazida por familiares ao pronto-socorro\ncom queixa de dor abdominal, de forte\nintensidade, há uma hora. A paciente relata inicio súbito da\ndor, associada à náuseas, vômitos e hiporexia. A filha refere que a paciente é portadora de\nfibrilação atrial, hipertensão arterial e diabetes mellitus, fazendo uso regular das medicações. Ao\nexame, bom estado geral, FC: 108 bp, PA: 128 x 86 mmHg, FR: 22 ipm; ausculta respiratória:\nmurmúrios vesiculares bem distribuídos e sem ruídos adventícios, ausculta cardíaca: bulhas\narrítmicas, normofonéticas e com sopro sistólico em foco aórtico; FC: abdome um pouco distendido,\ncom ruídos hidroaéreos diminuídos, dor a palpitação difusa, com descompressão brusca negativa.\nDe acordo com o caso descrito. Indique o tratamento mais adequado que deve ser instituído.","options":{"A":"Internação em unidade de terapia intensiva e suporte clínico.","B":"Embolectomia arterial com cateter de Fogarty.","C":"Apendicectomia por videolaparoscopia.","D":"Retossigmoidectomia por laparotomia."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-278625","number":"278625","sourceNumber":"278625","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente de 6 anos de idade submetido à laparotomia de urgência devido a abdome\nagudo. Foi constatada, no intraoperatório,\napendicite grau IV; realizada apendicectomia, e o\npaciente foi encaminhado para UTI Pediátrica. Qual seria a complicação mais comum esperada\nnesse paciente?","options":{"A":"Abscesso.","B":"Infecção em ferida operatória.","C":"Íleo paralitico.","D":"Obstrução intestinal."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-279059","number":"279059","sourceNumber":"279059","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente de 72 anos, masculino, dá entrada em pronto-socorro com queixa de dor\nepigástrica súbita há 2 horas, de forte\nintensidade, com irradiação para o dorso e tórax, associada a\nvômitos e sudorese fria. Nega febre. Relata piora progressiva neste intervalo de tempo e nega\nmelhora com analgesia simples. É portador de hipertensão arterial, sistêmica, fibrilação atrial\ncrônica, diabetes melitus tipo II, artrite reumatoide e é tabagista. Em uso contínuo de losartana\n(100mg/dia), hidroclorotiazida (25mg/dia), varfarina (5mg/dia), metoprolol (50mg/dia), metformina\n(1000mg/dia), e diclofenaco (75mg/dia). Ao exame físico encontra-se em regular estado geral,\nsudoreico, taquicárdico, descorado, desidratado, anictérico, acianótico, afebril. Bulhas cardíacas\narrítmicas, sem sopros audíveis, pulsos periféricos cheios e amplos. Murmúrio vesicular reduzido\nbilateralmente, sem ruídos adventícios. Abdome com ruídos, flácido, doloroso difusamente, sem\nsinais de irritação peritoneal. Sinal de Murphy negativo. Sinal de Jobert negativo. Sinais vitais da\nadmissão: pressão arterial: 170/110 mmHg (membro superior direito) e 180/110 mmHg (membro\nsuperior esquerdo), frequência respiratória: 22 irpm, frequência cardíaca: oscilando entre 100 e 120\nbpm, saturação periférica de oxigênio: 93%, temperatura axilar: 37.3ºC. Foi submetido à radiografia\nde tórax e eletrocardiograma abaixo. A principal hipótese diagnóstica é:","options":{"A":"Síndrome coronariana aguda.","B":"Dissecção aguda de aorta.","C":"Abdome agudo perfurativo.","D":"Tromboembolismo venoso"},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-279066","number":"279066","sourceNumber":"279066","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente de 23 anos, há 3 dias com dor abdominal já localizada em fossa ilíaca direita,\nassociada a hiporexia, sem melhora com uso de dipirona. Nega náusea. Nega febre. Relata piora\nprogressiva da dor, que se intensificou na data de hoje. Conta que já apresentou 2 episódios\nsemelhantes ao quadro clínico atual, porém apresentaram resolução espontânea. Nega sintomas\nurinários. Ao exame físico: bom estado geral, corado, hidratado, eupneico, anictérico, acianótico,\nafebril. Aparelho cardiopulmonar sem alterações. Abdome com ruídos presentes, flácido,\ndepressível, doloroso em fossa ilíaca direita, sem sinais de irritação peritoneal. Sinal de\nBlumberg,\nRovsing, Dunphy: todos negativos. Apresenta discreta leucocitose em hemograma, exame de urina\nnormal. Foi submetido a tomografia de abdome e pelve com contraste (figura abaixo). Assinale a\ncorreta.","options":{"A":"A principal hipótese diagnóstica é de diverticulite aguda de cólon direito, com coleção adjacente\nao cólon apontada pela seta branca.","B":"A principal hipótese diagnóstica é abscesso de músculo psoas direito, com coleção adjacente ao\nmúsculo apontada pela seta branca.","C":"A principal hipótese diagnóstica é apendicite aguda complicada, com coleção e pequena\nperfuração representada pela letra C na tomografia.","D":"A principal hipótese diagnóstica é apendicite aguda, com presença de fecalito apontado pela\nseta branca."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-279067","number":"279067","sourceNumber":"279067","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A ilustração abaixo mostra a secção da artéria apendicular, passo fundamental no\nprocesso de apendicectomia. A artéria apendicular, mais frequentemente é ramo indireto da(o):","options":{"A":"Tronco celíaco.","B":"Artéria mesentérica inferior.","C":"Artéria mesentérica superior.","D":"Artéria ilíaca interna."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-252888","number":"252888","sourceNumber":"252888","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente, sexo masculino, 65 anos de idade, é levado ao Pronto Socorro por familiares\ncom queixa de dor abdominal e lombar direita,\nhá três dias. Refere febre, náuseas e hiporexia. O\npaciente relata também irradiação da dor para região inguinal e membro inferior direito. Familiares\ninformam que o paciente tratou erisipela em membro inferior esquerdo, há sete dias. Paciente\nportador de diabetes Mellitus, em uso regular de hipoglicemiantes orais. Ao exame físico, bom\nestado geral, corado, hidratado, Temperatura axilar: 38,3ºC, FC: 88bpm, PA: 116x74mmHG, FR:\n18imp; ausculta cardíaca e respiratória sem alterações; abdome plano, flácido, ruídos hidroaéreos\npresentes, dor leve e difusa à palpação profunda e dor à punho percussão da região lombar direita;\ndor à extensão e rotação interna da articulação coxofemoral direita. Diante dos dados clínicos,\nindique a principal suspeita diagnóstica.","options":{"A":"Apendicite aguda.","B":"Diverticulite aguda.","C":"Abscesso de músculo psoas direito.","D":"Pielonefrite aguda direita."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-252889","number":"252889","sourceNumber":"252889","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente, sexo masculino, 65 anos de idade, é levado ao Pronto Socorro por familiares\ncom queixa de dor abdominal e lombar direita,\nhá três dias. Refere febre, náuseas e hiporexia. O\npaciente relata também irradiação da dor para região inguinal e membro inferior direito. Familiares\ninformam que o paciente tratou erisipela em membro inferior esquerdo, há sete dias. Paciente\nportador de diabetes Mellitus, em uso regular de hipoglicemiantes orais. Ao exame físico, bom\nestado geral, corado, hidratado, Temperatura axilar: 38,3ºC, FC: 88bpm, PA: 116x74mmHG, FR:\n18imp; ausculta cardíaca e respiratória sem alterações; abdome plano, flácido, ruídos hidroaéreos\npresentes, dor leve e difusa à palpação profunda e dor à punho percussão da região lombar direita;\ndor à extensão e rotação interna da articulação coxofemoral direita. Identifique o exame\ncomplementar mais importante para a elucidação diagnóstica.","options":{"A":"Análise urinária.","B":"Ultrassonografia de abdome.","C":"Videolaparoscopia.","D":"Tomografia computadorizada de abdome."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-252890","number":"252890","sourceNumber":"252890","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente, sexo masculino, 65 anos de idade, é levado ao Pronto Socorro por familiares\ncom queixa de dor abdominal e lombar direita,\nhá três dias. Refere febre, náuseas e hiporexia. O\npaciente relata também irradiação da dor para região inguinal e membro inferior direito. Familiares\ninformam que o paciente tratou erisipela em membro inferior esquerdo, há sete dias. Paciente\nportador de diabetes Mellitus, em uso regular de hipoglicemiantes orais. Ao exame físico, bom\nestado geral, corado, hidratado, Temperatura axilar: 38,3ºC, FC: 88bpm, PA: 116x74mmHG, FR:\n18imp; ausculta cardíaca e respiratória sem alterações; abdome plano, flácido, ruídos hidroaéreos\npresentes, dor leve e difusa à palpação profunda e dor à punho percussão da região lombar direita;\ndor à extensão e rotação interna da articulação coxofemoral direita. Após a confirmação do\ndiagnóstico, indique a conduta terapêutica mais adequada nesse caso.","options":{"A":"Laparotomia exploradora.","B":"Terapia antibiótica e observação.","C":"Drenagem percutânea guiada por imagem e terapia antibiótica.","D":"Videolaparoscopia."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-231375","number":"231375","sourceNumber":"231375","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente de 65 anos com diverticulite perfurada de sigmoide com peritonite difusa. Qual\no procedimento cirúrgico mais adequado:","options":{"A":"Laparostomia com colorrafia","B":"Laparotomia com colorrafia","C":"Operação de Hartman","D":"Operação de Duhamel","E":"Colostomia do transverso"},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-249217","number":"249217","sourceNumber":"249217","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Dividimos o abdome em 9 regiões, delimitadas por linhas imaginárias. Assinale a\nalternativa que corresponde corretamente o número à região indicada.","options":{"A":"1 ? flanco direito","B":"2 ? mesogástrio","C":"8 ? hipocôndrio medial","D":"7 ? fossa ilíaca direita"},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-249425","number":"249425","sourceNumber":"249425","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A causa mais comum de fístula colo-vesical é:","options":{"A":"Doença de Crohn.","B":"Câncer Colorretal.","C":"Retocolite ulcerativa.","D":"Diverticulite aguda."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-219847","number":"219847","sourceNumber":"219847","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"KRH, 32 anos, sexo feminino, do lar, que está na 28ª semana de gestação, inciou dor\nabdominal periumbilical e náuseas há 12 horas. A dor permaneceu difusa e surgiu febre de 37,8°C.\nAo exame físico, encontra-se corada, hidratada, anictérica e febril (37,7°C). Útero acima da\ncicatriz\numbilical, palpação pouco dolorosa sem reação peritoneal à descompressão. Exames laboratoriais\nmostraram anemia discreta (11,8 g/dl) com 16.500 leucócitos/mm³ com 70% de bastões. PCR de\n17 mg/dl. Em relação a este caso, assinale a alternativa CORRETA:","options":{"A":"A ausência de reação peritoneal se deve em parte à elevação do útero que alterna a posição do\napêndice.","B":"A extensão da propedêutica com Ressonância Magnética está contraindicada pelo risco de\nmalformação fetal e abortamento.","C":"Contagem de leucócitos superior a 14.000 céls/mm³ confirma quadro de peritonite difusa.","D":"Em caso de indicação cirúrgica está contraindicada a vida laparoscópica."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-212188","number":"212188","sourceNumber":"212188","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente de 44 anos, sexo feminino, bancária, previamente hígida, sem ingestão de\nálcool, admitida em pronto atendimento com\nquadro de dor abdominal em andar superior, em barra,\ncom irradiação para dorso há cerca de 6 horas, refratária a analgesia oral e associada a vômitos.\n\nAo exame, estado geral regular, corada, desidratada (2 em 4+), ictérica (1 em 4+), taquipneica e\ntaquicárdica. Ausculta cardíaca normal e ausculta pulmonar com murmúrio vesicular diminuído em\nbases. Abdome globoso, pouco distendido e pouco doloroso à palpação, sem descompressão\ndolorosa. Exames séricos evidenciam leucograma de 15.000/mm³, sem desvio, hemoglobina de 10\ne hematócrito de 26%, amilase de 3.500 mg/dl, creatinina de 1,8, cálcio de 9, LDH de 300, ALT de\n170, bilirrubina total de 4,6 e direta de 3,1, glicemia de 200, PCR 10. Radiografia de abdome aguda\nevidencia distensão difusa de alças de delgado, sem pneumoperitônio. Assinale a alternativa\nCORRETA a respeito do caso.","options":{"A":"A dosagem de proteína C-reativa tem valor prognóstico para essa doença.","B":"Antibioticoterapia com carbapenêmicos está indicada nas primeiras 24 horas.","C":"Pelos parâmetros clínicos e laboratoriais, podemos classificar essa doença como grave.","D":"Tomografia de abdome com contraste está indicada dentro das primeiras 12 horas da admissão.","E":"A instalação de nutrição parenteral é imprescindível para diminuir os efeitos deletérios\ndecorrentes do catabolismo da doença."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-219869","number":"219869","sourceNumber":"219869","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação à Pancreatite Aguda (PA), assinale a alternativa CORRETA:","options":{"A":"A adequação da reposição hídrica é um dos aspectos isolados mais importantes da terapia\nclínica.","B":"O tratamento cirúrgico do pseudocisto deve ser idealmente mais precoce.","C":"Os níveis de lipase tendem a ser mais elevados na PA biliar, enquanto os da amilase se elevam\nmais na PA alcoólica.","D":"Os níveis séricos de amilase guardam estreita relação com a gravidade do quadro."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-219881","number":"219881","sourceNumber":"219881","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"TDP, 27 anos, sexo masculino, pintor, refere dor em fossa ilíaca direita com vários dias\nde evolução, que não melhora com a\nadministração de analgésicos comuns. Nega febre. Apresenta\nnáuseas sem vômitos. Exames laboratoriais sem alterações. Realizou tomografia computadorizada\nque mostrou alteração no apêndice, que pode ser vista abaixo. Em relação a este caso, a MELHOR\nCONDUTA entre as abaixo deve ser:","options":{"A":"Apendicectomia aberta com retirada em monobloco do mesoapêndice.","B":"Conduta expectante com exames de imagem seriados.","C":"Punção guiada por ultrassonografia para estudo histopatológico.","D":"Realizar ileocolectomia direita."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-212160","number":"212160","sourceNumber":"212160","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente 22 anos, masculino, apresentando quadro de dor abdominal em região\nperiumbilical há 2 dias, de moderada\nintensidade com alívio discreto com uso de analgésicos\ncomuns, sem irradiação, associada à anorexia, náuseas e vômito. Nas últimas horas, evoluiu com\npiora da dor e migração dessa dor para a fossa ilíaca direita. Dados Vitais: temperatura 38 °C,\nfrequência cardíaca 106 bpm, frequência respiratória 21 irpm, normotenso. Exame físico do\nabdome: flácido, doloroso à palpação superficial e profunda da fossa ilíaca direita. Sinais de\nBlumberg e Rovsing positivos. Hemograma: Hemoglobina: 13 mg/dL (VR: 12-16) Leucócitos: 16460\n(bastões: 5%). Ultrassom do abdome revela apenas as alterações apresentadas nas figuras. Sobre\no caso, assinale a alternativa correta.","options":{"A":"Trata-se de um caso de apendicite aguda não complicada e está indicado o tratamento\nexclusivamente clínico com uso de antibioticoterapia.","B":"O escore de Alvarado do caso em questão indica baixa probabilidade de apendicite aguda e o\npaciente deverá ser acompanhado apenas com exame físico seriado.","C":"Trata-se de um caso de apendicite aguda não complicada e o tratamento cirúrgico,\napendicectomia videolaparoscópica,\n\nassociada ou não a antibioticoterapia, está indicado.","D":"Trata-se de um caso de apendicite aguda complicada com abscesso, sendo indicada a\ndrenagem percutânea do abscesso e antibioticoterapia, seguido de apendicectomia em\nmomento oportuno.","E":"Trata-se de apendicite aguda e o tratamento cirúrgico convencional tem maior vantagem em\nrelação ao tratamento cirúrgico por videolaparoscopia devido ao retorno precoce às\n\natividades, menor incidência de infecção de ferida operatória e menos dor no pós-operatório."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-181399","number":"181399","sourceNumber":"181399","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação à apendicite aguda, assinale a alternativa correta.","options":{"A":"A presença de peritonite difusa é contraindicação à abordagem laparoscópica.","B":"A ultrassonografia tem maior acurácia em relação à tomografia para diagnóstico da doença.","C":"É mais frequente na primeira década de vida, principalmente pela obstrução da luz do órgão por\ncorpo estranho ou tumor.","D":"É uma doença de diagnóstico eminentemente clínico, inclusive os critérios de Alvarado de\nprobabilidade levam em conta apenas sinais e sintomas.","E":"A apendicectomia de intervalo é uma opção terapêutica factível e realizada nos casos onde\nhouve impossibilidade de abordagem durante um evento\nagudo."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-187835","number":"187835","sourceNumber":"187835","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação ao abdome agudo, assinale alternativa ERRADA:","options":{"A":"Ausência de leucocitose não exclui apendicite aguda","B":"Ausência de pneumoperitônio inviabiliza o diagnóstico de úlcera perfurada","C":"Níveis normais de amilase e lipase séricos não excluem pancreatite aguda","D":"Os níveis de lactato e as determinações da gasometria arterial auxiliam no diagnóstico de\nisquemia ou infarto intestinal"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-183602","number":"183602","sourceNumber":"183602","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A dor abdominal em crianças com idade inferior a 2 anos é de difícil diagnóstico; na\nmaioria dos casos, o paciente apresenta irritabilidade e choro excessivos. Em situações de causas\nagudas que cursam com obstrução, massas e peritonite, podemos considerar as seguintes,\nEXCETO","options":{"A":"volvo intestinal.","B":"hérnia encarcerada.","C":"gastroenterites.","D":"apendicite."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-183607","number":"183607","sourceNumber":"183607","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"São aspectos clínicos da dor abdominal que sugerem a necessidade de tratamento\ncirúrgico todos os abaixo, EXCETO","options":{"A":"febre alta e diarreia.","B":"vômitos biliosos ou fecaloides.","C":"rigidez abdominal involuntária (abdome em tábua).","D":"sinal de descompressão brusca positiva (sinal de Blumberg)."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-183612","number":"183612","sourceNumber":"183612","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A faixa etária infantil que apresenta maior dificuldade para a obtenção do diagnóstico\nde dor abdominal aguda corresponde a","options":{"A":"entre 2 e 5 anos.","B":"menores de 2 anos.","C":"entre 5 e 12 anos.","D":"entre 12 e 15 anos."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-181391","number":"181391","sourceNumber":"181391","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Qual é o reservatório mais comum de Salmonella typhi, agente etiológico da febre\ntifoide, numa pessoa portadora?","options":{"A":"Apêndice.","B":"Vesícula biliar.","C":"Cólon sigmoide.","D":"Intestino grosso.","E":"Intestino delgado."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-161344","number":"161344","sourceNumber":"161344","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A respeito da doença diverticular dos cólons e diverticulite, aponte a alternativa\nINCORRETA.","options":{"A":"O Cólon sigmoide é o local mais cometido, e a segunda área mais envolvida é o cólon\ndescendente.","B":"São divertículos verdadeiros, pois são formados por todas as camadas da parede do intestino.","C":"Segundo a classificação de Hinchey para diverticulite, estádio II, corresponde ao abscesso\npélvico bloqueado, e o tratamento de escolha é drenagem percutânea via tomografia\ncomputadorizada ou ultrassom.","D":"Nas peritonites generalizadas causadas pela diverticulite e associadas à sepse, não é seguro\nrestabelecer continuidade intestinal, pela elevada probabilidade de cicatrização inadequada. Neste\ncaso a operação apropriada é a cirurgia de Hartmann."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-158765","number":"158765","sourceNumber":"158765","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Dadas as afirmativas sobre a apendicite aguda, I. Pacientes com escore de Alvarado\nigual ou superior a 7 têm alto risco de\napendicite.; II. Atualmente, a cirurgia aberta é a via de\nescolha para o tratamento da doença.; III. É a urgência cirúrgica abdominal mais frequente.; IV. Há\npredomínio no sexo feminino e em negros. Verifica-se que está(ão) correta(s):","options":{"A":"I, apenas.","B":"II, apenas.","C":"I e III, apenas.","D":"II e IV, apenas.","E":"I, II, III e IV."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-158772","number":"158772","sourceNumber":"158772","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente alcoólatra crônico, masculino, 60 anos, é admitido no hospital com pancreatite\naguda. Tiveram episódios semelhantes no\npassado que foram resolvidos sem complicações. Foi\nverificado nos exames laboratoriais nível de amilase elevado e encontrado na tomografia\ncomputadorizada um pseudocisto pancreático. Qual o melhor tratamento para esse paciente?","options":{"A":"Aspiração simples.","B":"Tratamento cirúrgico.","C":"Drenagem percutânea.","D":"Tratamento endoscópico.","E":"Observação e tomografias seriadas de controle."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-161138","number":"161138","sourceNumber":"161138","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"São bactérias comumente isoladas em apendicite perfurada, com EXCEÇÃO de uma\ndelas. Indique-a.","options":{"A":"Bacterioides fragilis.","B":"Streptococcus viridans.","C":"Clostridium difficile.","D":"Pseudomonas aeroginosa."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-161304","number":"161304","sourceNumber":"161304","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Assinale a alternativa INCORRETA quanto à diverticulite:","options":{"A":"É efeito da perfuração de um divertículo colônico resultado em uma infecção pericólica\nextraluminal.","B":"O cólon sigmoide é o segmento do intestino grosso com a maior incidência de divertículos e é o\nlocal mais frequente para envolvimento com a diverticulite.","C":"Muitos pacientes com diverticulite queixam-se de dor em quadrante inferior esquerdo do\nabdome, que pode irradiar-se para a área suprapúbica, virilha esquerda ou para as costas.","D":"A presença de abscesso pericólico ou mesentérico é classificado como estádio II de Hinchey."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-161331","number":"161331","sourceNumber":"161331","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Cerca de 8% das pessoas nos países ocidentais têm apendicite em algum momento de\nsuas vidas, com uma incidência máxima entre\n10 e 30 anos de idade. Sobre aspectos diversos do\napêndice, indique a opção CORRETA.","options":{"A":"A localização mais comum do apêndice cecal é pélvica.","B":"Piúria mínima, frequentemente observada em mulheres idosas, exclui apendicite aguda.","C":"Em crianças pré-escolares, o diagnóstico diferencial inclui diverticulite de Meckel,\ngastroenterite\naguda.","D":"Em crianças em idade escolar, o mais comum simulador de apendicite são os neoplasmas de\napêndice."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-161223","number":"161223","sourceNumber":"161223","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Assinale a alternativa INCORRETA a respeito dos fatores de risco da pancreatite\naguda.","options":{"A":"A pancreatite por cálculos biliares é mais observada em mulheres entre 50-70 anos de idade.","B":"O consumo excessivo de álcool é a segunda causa mais comum de pancreatite aguda no\nmundo e é mais prevalente em jovens do sexo\nmasculino (30-45 anos de idade).","C":"A lesão pancreática direta pode ser induzida por metabólitos triglicerídeos e deve ser suspeitada\nem pacientes com nível de triglicerídeo mais alto\ndo que 1.000 mg/dL.","D":"A hipotensão intraoperatória prolongada não tem relação com a pancreatite aguda."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-134893","number":"134893","sourceNumber":"134893","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Homem de 43 anos, na sala de urgência, com dor abdominal intensa e dor torácica\nsubesternal há 12 horas (após ingestão de\ngrande quantidade de álcool em uma festa). Antes do\ninício da dor teve vários episódios de vômito. História prévia não é digna de nota e não usa\nmedicamentos. Ao exame clínico, encontra-se desconfortável e ansioso, temperatura de 38,8°C,\nfrequência cardíaca de 120/min, pressão arterial de 120 x 80 mmHg e frequência respiratória de\n32/min. Pulmões limpos bilateralmente, porém com diminuição dos murmúrios à esquerda. Exame\ncardíaco revela taquicardia sem outros comemorativos. Abdome sensível à palpação epigástrica.\nTem leucocitose de 26 mil/mm³, ECG de 12 derivações normais, RX de tórax com derrame pleural\nmoderado à esquerda, pneumotórax e pneumomediastino à esquerda. Em se tratando de uma\nruptura esofágica espontânea (Síndrome de Boerhaave), seu próximo passo é","options":{"A":"Manejo das vias aéreas, respiração e circulação (ABC).","B":"Drenagem torácica à esquerda.","C":"Administração de fluidos e antibiótico de amplo espectro.","D":"Todas as alternativas acima."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-134117","number":"134117","sourceNumber":"134117","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Úlcera duodenal perfurada ou ruptura de baço podem ter dores referidas para qual\nregião anatômica?","options":{"A":"Dorsal supraclavicular.","B":"Membros inferiores.","C":"Hipogastro.","D":"Sacral."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-134862","number":"134862","sourceNumber":"134862","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"No tratamento cirúrgico de Úlcera Péptica Duodenal, um procedimento é considerado\nMAIS fisiológico. Aponte-o.","options":{"A":"Vagotomia com antrectomia.","B":"Vagotomia seletiva com piloroplastia.","C":"Vagotomia troncular com piloroplastia.","D":"Vagotomia gástrica proximal."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-131332","number":"131332","sourceNumber":"131332","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Na apendicite aguda, o primeiro sintoma é:","options":{"A":"Anorexia.","B":"Dor epigástrica.","C":"Dor na fossa ilíaca direita.","D":"Dor abdominal difusa.","E":"Vômitos."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-131378","number":"131378","sourceNumber":"131378","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A causa mais frequente de pancreatite aguda é:","options":{"A":"Traumatismo abdominal.","B":"Dislipidemia.","C":"Alcoolismo.","D":"Biliar.","E":"Iatrogenia."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-109730","number":"109730","sourceNumber":"109730","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Homem de 62 anos com dor na fossa ilíaca esquerda há 1 semana, acompanhada de\ndiarreia. Dor evolutiva, náuseas, vômitos e febre. Já teve dois episódios similares. Um com\nremissão espontânea e outro à custa de antibiótico via oral. Não possui fator de risco\ncardiopulmonar. Ao exame clínico está febril (39ºC), taquicárdico (115/min) e normotenso. Abdome\nflácido e ligeiramente distendido, com dor à palpação do quadrante inferior esquerdo e\ndescompressão brusca positiva na fossa ilíaca esquerda. Leucocitose de 20.000/mm³. Qual é a\nhipótese diagnóstica e o próximo passo investigatório, RESPECTIVAMENTE?","options":{"A":"Abdome agudo e RX do abdome.","B":"Abdome agudo e ultrassonografia de abdome.","C":"Diverticulite aguda e ultrassonografia de abdome.","D":"Diverticulite aguda e tomografia computadorizada do abdome."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-86858","number":"86858","sourceNumber":"86858","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Segundo Ranson, na pancreatite aguda, um dos critérios de mau prognóstico é:","options":{"A":"Glicemia > 200mg %;","B":"Íleo paralítico no momento da admissão;","C":"Cálcio sérico < 8mg% no momento da admissão;","D":"Queda do hematócrito maior que 5% em 48 horas;","E":"Sinais de irritação ao peritoneal ao exame físico, após 48 horas."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-86665","number":"86665","sourceNumber":"86665","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Qual dos agentes seguintes tem demonstrado melhora no índice de fechamento de\nfístulas enterocutâneas em doença de Crohn?","options":{"A":"Metotrexate.","B":"5-ASA.","C":"Infliximab.","D":"Corticoide.","E":"Azatioprina."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-86636","number":"86636","sourceNumber":"86636","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Sobre a pancreatite aguda pode-se afirmar que: I. Caracteriza-se por dor abdominal e\naumento da concentração sérica de amilase e lipase. II. Cerca de 80% são causadas por litíase\nbiliar e álcool. III. O evento inicial é a ativação prematura de enzimas digestivas na célula acinar\npancreática.","options":{"A":"A alternativa I está correta, somente.","B":"A alternativa III está correta, somente.","C":"As alternativas I e II estão corretas, somente.","D":"As alternativas II e III estão corretas, somente.","E":"As alternativas I, II e III estão corretas."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-158400","number":"158400","sourceNumber":"158400","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"São doenças que entram no diagnóstico diferencial de abdome agudo inflamatório,\nEXCETO:","options":{"A":"Apendicite aguda.","B":"Abscesso hepático.","C":"Herpes zoster.","D":"Pielonefrite.","E":"Ferimento por arma de fogo no abdome."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-158430","number":"158430","sourceNumber":"158430","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Dentre as citadas, as causas mais comuns de dor abdominal aguda em\nescolares/adolescentes, pré-escolares e lactentes são representadas, respectivamentes, por:","options":{"A":"Anemia falciforme, constipação intestinal e infecção urinária.","B":"Hematocolpos, infecção urinária e psoíte.","C":"Apendicite, adenite mesentérica e doença diarréica aguda.","D":"Cetoacidose diabética, infecção urinária e doença diarreica aguda.","E":"Úlcera péptica, pneumonia e invaginação intestinal."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-108571","number":"108571","sourceNumber":"108571","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Assinale a INCORRETA:","options":{"A":"As principais causas de erro na condução do abdome agudo são a história e o exame físico\nincompletos.","B":"A combinação de uma história clínica e um exame físico corretos permite identificar as doenças\nem 75 a 90% dos pacientes.","C":"Em pacientes com dor abdominal de etiologia não-esclarecida, a avaliação seriada contribui para\no acerto do diagnóstico, com sensibilidade\nequivalente a alguns exames de imagem.","D":"A dor referida ao toque retal é comum e patognomônica de várias patologias.","E":"A maioria dos pacientes idosos com colecistite e apendicite aguda apresenta-se afebril."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-108572","number":"108572","sourceNumber":"108572","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente de 30 anos, no quarto mês de gestação, com quadro clínico sugestivo de\napendicite aguda. Assinale a alternativa INCORRETA:","options":{"A":"A apendicite é a causa mais frequente de abdome agudo na gestação.","B":"Apendicite ocorre em mulheres grávidas e não grávidas da mesma faixa etária na mesma\nproporção.","C":"Esse caso requer cirurgia imediata.","D":"Apendicites complicadas resultam em mortalidade\n\nfetal de 20% e desencadeamento de parto prematuro em cerca de 10% dos casos.","E":"A conduta conservadora seria indicada para esse caso somente se a mãe estivesse em sepse,\npara preservar as condições do feto."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-108573","number":"108573","sourceNumber":"108573","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente deu entrada no atendimento de urgência com quadro de dor abdominal em\nquadrante inferior esquerdo, astenia, febre moderada e dificuldade para evacuar. Ao exame físico\napresenta abaulamento doloroso à palpação nessa região. Qual o exame ideal para estabelecer o\ndiagnóstico e a conduta desse caso?","options":{"A":"Ultrassonografia do abdome.","B":"Enema opaco.","C":"Colonoscopia.","D":"Tomografia do abdome.","E":"Enteroscopia."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-108574","number":"108574","sourceNumber":"108574","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"<p>Assinale a INCORRETA sobre pancreatite:</p>","options":{"A":"A etiologia mais frequente de pancreatite aguda é a biliar.","B":"A dosagem de PCR (Proteína C-Reativa) tem bom valor prognóstico.","C":"A tomografia do abdome tem valor diagnóstico e prognóstico.","D":"A diminuição das enzimas amilase e lipase representa uma boa evolução.","E":"O uso de antibióticos deve ser criterioso e indicado para casos mais graves."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-49572","number":"49572","sourceNumber":"49572","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação ao abdome agudo, assinale a alternativa INCORRETA:","options":{"A":"Sinal do obturador é a dor suprapúbica desencadeada pela rotação interna da coxa semifletida\ncom o doente em decúbito dorsal.","B":"A hiperamilasemia pode ocorrer em úlceras perfuradas e isquemia mesentérica.","C":"A tomografia computadorizada é o exame de imagem com maior especificidade para o\ndiagnóstico de pancreatite aguda.","D":"A dor mal localizada, que ocorre no início do quadro de abdome agudo inflamatório, como no\ncaso de apendicite aguda, deve-se à\nirritação do peritônio visceral. Só há dor localizada quando o\nprocesso evolui causando irritação do peritônio parietal.","E":"O sinal de Cullen (equimose periumbilical) é patognomônico de pancreatite necro-hemorrágica."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-298194","number":"298194","sourceNumber":"298194","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A dor abdominal é a manifestação mais comum e marcante da pancreatite crônica.\nEntre as características citadas, qual delas\nNÃO é comumente encontrada?","options":{"A":"Crises dolorosas recorrentes.","B":"Alívio com alimentação.","C":"Duração de 1 a 7 dias.","D":"Precipitada pelo abuso de álcool."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-362469","number":"362469","sourceNumber":"362469","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo masculino, 32 anos, sobrepeso, comparece ao pronto atendimento\napresentando quadro de dor tipo cólica,\nmesogástrica, que migrou para FID e aumentou de\nintensidade, há cerca de 24hs. Apresentou também vários episódios de vômito. Nega febre, diarreia\ne sintomas urinários. Encontra-se em BEG, eupneico, afebril, estável. Sem abdome é plano, flácido,\ndoloroso à palpação profunda na FID, com descompressão súbita levemente positiva. Foi solicitada\navaliação laboratorial que evidenciou leucograma 11.000, com 90% de segmentados e Proteína C\nReativa 36g/l. Optou-se por avaliação ultrassonográfica que evidenciou apêndice cecal espessado\ne discretamente aumentado de volume, com hipervascularização da sua parede ao doppler, sem\nfecalito ou líquido livre na cavidade. Sobre o caso descrito acima, assinale a alternativa CORRETA:","options":{"A":"Havia indicação precisa de laparotomia imediata logo após o exame físico, caso contrário o\npaciente provavelmente evoluiria com complicações como abscesso intracavitário.","B":"A conduta definitiva para o caso só pode ser tomada após a exclusão de apendicolito por\ntomografia computadorizada.","C":"O achado laboratorial de leucocitose e elevação da proteína C reativa nos permite afirmar que\nantibioticoterapia por 3 a 5 dias fará parte do tratamento deste paciente.","D":"Está indicada internação hospitalar para tratamento inicial não cirúrgico, com antibióticos e\nreavaliação clínica após 8 horas."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-362491","number":"362491","sourceNumber":"362491","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, 48 anos, deu entrada no pronto socorro queixando dor\nintensa, de início súbito, em região\nepigástrica e que irradiava para o dorso, associada a vômitos,\ncom evolução de 8 horas. Se apresentava normocorada, anictérica, levemente dispneica e\nnormotensa, com abdome bastante doloroso à palpação em todo o andar superior, sem sinais de\nirritação peritoneal. A paciente foi internada para investigação e seus exames laboratoriais\nevidenciaram 12.000 leucócitos com desvio à esquerda, hematócrito e hemoglobina normais,\nfosfatase alcalina 250U/l, amilase 2.300mg/dl e ultrassonografia com colelitíase. Foi prescrita\nhidratação venosa, analgesia potente e antieméticos, mas não foram iniciados antibióticos. A\npaciente evoluiu com estabilidade hemodinâmica, bom débito urinário e regularização da frequência\nrespiratória, porém manteve quadro de importante desconforto abdominal. No 5° dia de internação,\nfoi submetida a tomografia que evidenciou vesícula biliar tópica, normodistendida, com cálculos e\naumento do volume e heterogeneidade pancreática com formação de coleção de cerca de 9,0 x\n4,0cm ao longo do corpo do pâncreas e densificação da gordura adjacente, sem sinais de\ncompressão gástrica. Sobre o caso descrito, assinale a alternativa CORRETA:","options":{"A":"A ausência da antibioticoterapia no tratamento inicial foi responsável pela complicação descrita\nacima.","B":"Por tratar-se de abscesso peripancreático, o próximo passo na conduta do caso é a drenagem\ncirúrgica da loja pancreática.","C":"A evolução insatisfatória do caso e a formação da coleção pancreática, classificam o caso como\npancreatite grave e indica início imediato de antibioticoterapia de largo espectro.","D":"Já que não há compressão gástrica e a paciente se encontra hemodinamicamente estável, o\ntratamento da coleção neste momento é expectante e sem uso de antibióticos."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-362511","number":"362511","sourceNumber":"362511","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo masculino, 57 anos, vem ao atendimento médico queixando dor tipo\ncólica em FIE com piora progressiva, associada a vômitos e constipação há 48 horas. Refere hábito\nintestinal inadequado, com eliminação de fezes endurecidas e ressecadas, sob esforço, cerca de\numa vez por semana, há muitos anos. Nega febre e episódios anteriores de dor semelhante. Nega\ncomorbidades. Ao exame físico apresenta-se em BEG, eupneico, afebril hemodinamicamente\nestável. Seu abdome é globoso, flácido, doloroso à palpação profunda, sem irritação peritoneal ou\nplastrão palpável. Leucograma: 12.000 e Proteína C reativa: 63mg/l. Foi solicitada tomografia de\nabdome que evidenciou presença de divertículos em sigmoide de parede espessada, contendo\ndivertículos, com borramento da gordura adjacente, sem coleções ou líquido livre na cavidade\nabdominal. Sobre o caso descrito, assinale a alternativa CORRETA:","options":{"A":"Por tratar-se de paciente imunocompetente, sem comorbidades e com bom estado geral, o\ntratamento clínico inicial pode ser realizado sem antibióticos.","B":"Considerando que a grande maioria dos casos descritos acima evoluem com complicações\ncomo perfuração de cólon, formação de abscessos e\nperitonite, há clara indicação para\nhospitalização.","C":"A história, o exame físico e a avaliação laboratorial eram suficientes para fechamos o\ndiagnóstico clínico e início do tratamento, sem a necessidade da realização da tomografia.","D":"A conduta definitiva para o caso é a sigmoidectomia eletiva laparoscópica realizada 6 a 8\nsemanas após a remissão dos sintomas com tratamento clínico."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-327241","number":"327241","sourceNumber":"327241","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, 13 anos, refere quando de dor tipo cólica, em epigástrio,\nque migrou para FID, com aumento progressivo\nde intensidade, associada a náuseas e vômitos.\nEvolução de 48 horas. Nega febre e diarreia. Refere menarca há cerca de 6 meses, com ciclos\nregulares. Nega leucorréia. Seu abdome é plano, flácido, doloroso à palpação profunda em FID,\ncom sinais de Blumberg e Rovsing positivos. Sobre o caso acima, assinale a alternativa CORRETA:","options":{"A":"Dados como a idade da paciente, o ciclo menstrual regular e o tempo de evolução do quadro\nagudo nos permitem afirmar que o tratamento\nnão-cirúrgico com antibioticoterapia pode ser efetivo\npara o quadro acima.","B":"A presença do sinal de Rovsing indica laparotomia exploradora imediata.","C":"A abordagem laparoscópica pode ser tanto diagnóstica quanto terapêutica para o caso acima.","D":"A ausência de febre exclui o diagnóstico de abdome agudo inflamatório, estando indicada\ninvestigação com tomografia computadorizada de abdome."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-327245","number":"327245","sourceNumber":"327245","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, 22 anos de idade, dá entrada no pronto atendimento com\nquadro de dor abdominal iniciada em FID e\nirradiada para toda a pelve, de leve a moderada\nintensidade, há cerca de 8 horas, acompanhada de tontura, mal-estar e sensação de síncope. Não\nsabe referir adequadamente o caráter da dor. Nega vômitos, diarreia e sintomas urinários. Refere\nleucorréia esbranquiçada há 3 meses, ciclo menstrual irregular, com data da última menstruação há\ncerca de 2 meses. Vida sexual ativa com uso irregular de preservativos ou outros métodos\ncontraceptivos. Ao exame físico encontra-se hipocorada +++/4, FR: 25irpm, FC: 100bpm, P.A.: 90 x\n60mmHg. Abdome plano, flácido, simétrico, doloroso à palpação profunda em toda a pelve, com\nirritação peritoneal duvidosa. Refere dor ao toque vaginal. Toque retal sem alterações. Sobre o\ncaso acima, assinale a alternativa INCORRETA:","options":{"A":"O hemograma será útil para o diagnóstico sindrômico do caso acima, mas pode ser dispensável\npara a decisão de abordagem cirúrgica para o\ncaso.","B":"Caso o Beta-HCG desta paciente resulte negativo, o tratamento preferencial do caso será\nclínico, com analgesia e antibioticoterapia.","C":"A ressuscitação volêmica com Ringer Lactato e a avaliação da necessidade de transfusão de\nconcentrado de hemácias faz parte da conduta inicial do caso.","D":"O FAST, apesar de ser propedêutica idealizada para pacientes politraumatizados, pode ser\nextremamente valioso na avaliação inicial desta paciente."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-327250","number":"327250","sourceNumber":"327250","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, 34 anos, dá entrada no pronto atendimento com quadro de\ndor em HD associada a vômitos, que migrou\npara o dorso e todo o abdome superior após algumas\nhoras, evoluindo com piora expressiva de intensidade. Refere episódios prévios de dor em HD, mas\nnunca tão intensos. Ao exame físico, a paciente se encontrava bastante desidratada, taquicárdica,\nlevemente dispneica, normotensa e oligúrica. Seu abdome era plano, bastante doloroso à palpação\nprofunda em todo andar superior do abdome, sem irritação peritoneal. Sua investigação\npropedêutica revelou colelitíase, leucocitose discreta e hiperamilasemia. A paciente foi internada\nem dieta zero, sendo prescrita hidratação venosa, analgesia com derivados da morfina e\nantieméticos. Após 48h, evoluiu com estabilização hemodinâmica, normalização da frequência\nrespiratória e do débito urinário, porém mantinha quadro doloroso abdominal, agora com distensão,\nsendo mantida a internação. No 8º dia de internação, evoluiu com sinais de choque e febre, sendo\nsubmetido a tomografia de abdome que revelou coleção peripancreática contendo gás no seu\ninterior. Sobre o caso acima, assinale a alternativa CORRETA:","options":{"A":"Podemos afirmar que o paciente evoluiu de forma insatisfatória porque não foi iniciada\nantibioticoterapia ao ser definido o diagnóstico de pancreatite aguda moderadamente grave.","B":"A conduta adequada é a coleta de hemocultura ou coleta de secreção guiada por tomografia\npara cultura, início de antibioticoterapia de largo\nespectro e tratamento de suporte do estado de\nchoque, não estando indicada a abordagem cirúrgica neste momento.","C":"A nutrição parenteral, quando iniciada após as 48h de internação, é considerada profilática para\na complicação descrita acima.","D":"Os dados fornecidos nos permitem afirmar que havia indicação de colecistectomia de urgência\napós 48 horas do início do quadro e a perda\ndo timing do tratamento cirúrgico ocasionou a\ncomplicação descrita."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-327251","number":"327251","sourceNumber":"327251","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo masculino, 65 anos, com história de constipação crônica e baixa\ningesta alimentar de fibras, vem ao pronto\nsocorro queixando dor tipo cólica, aguda, em FIE, de\nmoderada intensidade, há cerca de 48 horas, associada a náuseas, vômitos e parada de\neliminação de fezes. Refere, ainda, 1 episódio de febre baixa. Nega comorbidades como\nhipertensão e diabetes. Ao exame físico, encontra-se em BEG, eupneico, afebril,\nhemodinamicamente estável. Seu abdome é plano, flácido, bastante doloroso à palpação profunda\nem FIE, com discreta irritação peritoneal. Leucograma: 16.000, Proteína C reativa: 80mg/l. Foi\nsubmetido a Tomografia Computadorizada de abdome que evidenciou presença de múltiplos\ndivertículos em cólon sigmoide, com borramento da gordura pericólica e presença de coleção\nlíquida bloqueada de cerca de 6cm. Sobre o caso acima, assinale a alternativa CORRETA:","options":{"A":"Por tratar-se de paciente classificado como Hinchey IB, a drenagem percutânea da coleção\npericólica pode prevenir a necessidade de sigmoidectomia de urgência.","B":"O próximo passo na investigação diagnóstica deste paciente é a realização de colonoscopia\npara avaliar a presença de complicações como edema,\nhiperemia, presença de pus e erosões,\nalém de estabelecer adequadamente a classificação DICA para o caso.","C":"Por tratar-se de paciente com baixo risco para complicações cirúrgicas, o paciente pode ser\ntratado inicialmente em domicílio, com dieta líquida sem resíduos e repouso, sem uso de\nantibióticos.","D":"A presença de febre, leucocitose e proteína C reativa elevada, revela alto risco de complicações\ngraves que, quando associado aos achados\ntomográficos descritos acima, compõem indicação\nformal para colectomia esquerda e colostomia terminal à Hartmann."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-327258","number":"327258","sourceNumber":"327258","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo masculino, 55 anos, hipertenso e com história recente de angina\ninstável, dá entrada no pronto socorro\napresentando quadro de dor epigástrica em queimação,\nintensa, que migrou para todo o abdome, acompanhada de sinais claros de peritonite difusa, com\nevolução de 6 horas. Associado ao quadro abdominal, apresenta dor torácica e dispneia.\n\nSubmetido a eletrocardiograma, este evidencia alterações isquêmicas nas derivações anteriores. A\nradiografia de tórax evidencia pneumoperitoneo. Quais das condutas a seguir é a mais adequada\npara o caso?","options":{"A":"Encaminhar paciente para cateterismo coronariano imediato, previamente a laparotomia.","B":"Antibióticos, monitorização invasiva intra-operatória, laparotomia imediata e pós-operatório em\nUTI.","C":"Antibióticos, tratamento intensivo da sua condição cardíaca e cirurgia após 48 horas de\nestabilização do quadro de angina.","D":"Antibióticos e tratamento não cirúrgico do quadro abdominal."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-298195","number":"298195","sourceNumber":"298195","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente 28 anos com histórico de viagem recente para a África do Sul. Refere ter se\nalimentado em lugares com baixas condições sanitárias de higiene. Procura o atendimento médico\nreferindo na 2a semana de doença, febre alta, prostração, diarreia com evacuação de fezes\nlíquidas várias vezes ao dia. Ao exame físico, nota-se icterícia, palidez cutaneomucosa, máculas\nrosadas não sensíveis em tórax, abdome e dorso. Dor abdominal com aumento de baço e fígado.\nBradicardia é notada a palpação do pulso radial apesar da febre. Laboratório - Leucopenia com\nneutropenia e linfocitose relativa, PCR elevada e aumento de transaminases. O diagnóstico de\nsuspeição é de?","options":{"A":"Febre tifóide","B":"Malária","C":"Dengue","D":"Meningite bacteriana aguda"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-298209","number":"298209","sourceNumber":"298209","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo masculino, 60 anos de idade, diabético, apresenta quadro de dor\nmesogástrica que migrou para fossa ilíaca esquerda há 2 dias, com piora progressiva, associada a\nvômitos. Refere história de constipação crônica. Não defecou no período, porém eliminava flatos.\nAo exame físico, encontrava-se em BEG, eupneico, taquicárdico, desidratado e normotenso, com\nabdome globoso, flácido, doloroso à palpação profunda em fossa ilíaca esquerda e discreta\nirritação peritoneal. Leucograma: 14.000. Foi internado para observação clínica, sendo iniciada\nantibioticoterapia, analgesia e mantido em dieta zero. Após 72 horas de internação, apresentou\npiora do quadro geral, com migração da dor para toda a pelve, piora da sua intensidade e início de\npicos febris. Está toxemiado, taquicárdico, levemente eupneico e hipotenso, e seu abdome agora\napresenta plastrão palpável em fossa ilíaca esquerda e irritação peritoneal em andar inferior. Sobre\no quadro descrito, assinale a alternativa CORRETA:","options":{"A":"Os dados acima nos permitem classificar a patologia do paciente como Hinchey 2, estando\nindicado o escalonamento da antibioticoterapia e manutenção da observação clínica.","B":"A sigmoidectomia com anastomose primária término-terminal é conduta provavelmente\ninadequada para o caso.","C":"A evolução insatisfatória do caso indica investigação colonoscópica para definição da conduta\nterapêutica adequada.","D":"A ultrassonografia teria definido conduta cirúrgica no momento da internação deste paciente."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-298211","number":"298211","sourceNumber":"298211","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, 28 anos, grávida de 32 semanas, inicia quadro de dor tipo\ncólica em mesogástrio que migra para o flanco direito, de moderada intensidade, associada a\nnáuseas e vômitos, há cerca de 36 horas. Nega febre, sintomas urinários, leucorréia e alterações\nno hábito intestinal. Ao exame físico, encontra-se em BEG, eupneica, afebril, hemodinamicamente\nestável. Seu abdome é gravídico, com útero palpável acima da cicatriz umbilical. Movimentos fetais\npalpáveis. Ausculta do foco cardíaco fetal: 140bpm. Dor à palpação profunda em flanco direito, com\ndescompressão brusca bastante dolorosa. Toque vaginal: colo uterino fechado. O hemograma\nrevela 12.000 leucócitos com desvio à esquerda, hemoglobina e hematócrito normais para o estado\ngravídico. EAS sem alterações. Sobre o caso acima, assinale a alternativa CORRETA:","options":{"A":"A postergação do tratamento cirúrgico urgente para esta paciente aumenta as chances de parto\nprematuro e sofrimento fetal.","B":"A ausência de febre e o estado gravídico sugerem que a antibioticoterapia de largo espectro é o\ntratamento de escolha para o caso acima.","C":"Os dados clínicos são insuficientes para determinação de diagnóstico e conduta, estando\nindicada a investigação com tomografia computadorizada.","D":"O estado gravídico contraindica tratamento laparoscópico para o caso."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-298223","number":"298223","sourceNumber":"298223","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, 42 anos, com histórico de colelitíase, apresentou quadro de\ndor em hipocôndrio direito, tipo cólica, que rapidamente se tornou constante e intensa, migrando\npara todo o andar superior do abdome, há cerca de 6 horas, associada a vômitos, sendo internada\nno serviço de pronto atendimento. Seu abdome era globoso, doloroso à palpação profunda do\nandar superior, sem irritação peritoneal. Na investigação laboratorial, observou-se hiperamilasemia\nde 2.350mg/dl. Foi mantida em dieta zero com hidratação venosa e analgesia potente e evoluiu\napós 48 horas com manutenção da dor e dos vômitos, distensão abdominal, sinais clínicos de\ndesidratação moderada e hipotensão, taquipnéia, acidose metabólica à gasometria arterial e\nelevação da contagem de leucócitos e das titulações de uréia e creatinina séricas. Bilirrubinas,\ngama GT e fosfatase alcalina normais. Sobre o caso descrito, assinale a alternativa CORRETA:","options":{"A":"A nutrição parenteral é mais efetiva no tratamento desta paciente que a nutrição enteral,\nprincipalmente no que se refere a profilaxia da translocação bacteriana e diminuição da\nmortalidade.","B":"Há clara evolução para choque séptico, estando indicado o início de Imipenem e laparotomia\npara desbridamento do foco infeccioso.","C":"O paciente provavelmente preencherá critérios no score de Marshall para disfunção persistente\nde órgãos, evidenciando evolução grave, estando\nindicada terapia intensiva com tratamento de\nsuporte.","D":"Devido a provável evolução com abscesso retroperitoneal, a tomografia está indicada neste\nmomento, confirmando a indicação de laparotomia urgente para esta paciente."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-286725","number":"286725","sourceNumber":"286725","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo masculino, 16 anos, é atendido no pronto-socorro apresentando\nquadro de dor tipo cólica em epigástrio que\nmigrou para fossa ilíaca direita há 2 dias, associada a\nvômitos e 1 episódio de febre baixa. Seu estado geral é bom e o paciente se encontra\nhemodinamicamente estável. O hemograma evidenciou 18.000 leucócitos com desvio à esquerda e\na Proteína C Reativa era 35 mg/dl. Para a tomada da decisão terapêutica deste paciente, foi\nrealizada tomografia de abdome com contraste venoso que evidenciou apêndice aumentado de\nvolume, paredes espessadas, contendo fecalito no seu interior, sem sinais de perfuração ou\nabscesso. Sobre a conduta do caso, assinale a alternativa CORRETA:","options":{"A":"Por tratar-se de apendicite aguda não complicada, este paciente seria bom candidato para\nmanejo não cirúrgico, com antibioticoterapia exclusiva.","B":"Caso a tomografia evidenciasse abscesso intracavitário, a abordagem laparoscópica estaria\ncontraindicada.","C":"Se a abordagem cirúrgica confirmar os achados tomográficos, a dose única de cefoxitina durante\na indução anestésica deve ser suficiente no\ntratamento deste paciente.","D":"Os dados nos permitem afirmar que a melhor conduta para o caso é apendicectomia\nconvencional urgente, com pós-operatório em unidade de tratamento semi-intensiva."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-286726","number":"286726","sourceNumber":"286726","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo masculino, 65 anos, vem ao seu consultório trazendo consigo uma\ntomografia que o deixou bastante preocupado. O exame foi realizado na vigência de uma queda no\ndomicílio em que teve uma contusão abdominal há 2 meses atrás. O laudo desta tomografia não\nevidenciou quaisquer lesões abdominais traumáticas, porém foram observados vários divertículos\nem cólon descendente e sigmoide. O paciente nega história de dor abdominal na Fossa Ilíaca\nEsquerda, referindo apenas constipação crônica. Qual das seguintes orientações ao paciente é\nINADEQUADA?","options":{"A":"Pacientes com diagnóstico de divertículos no cólon esquerdo devem ser encaminhados para\nressecção cirúrgica dos mesmos devido ao alto risco de evolução para doença maligna.","B":"A doença diverticular dos cólons é uma condição bastante comum após os 60 anos de idade,\nprincipalmente quando o paciente apresenta constipação crônica?.","C":"A presença dos divertículos no intestino grosso não causa sintomas, porém há chances que eles\ncompliquem com episódios de sangramento ou inflamação e dor, necessitando avaliação médica\nimediata.","D":"Quadros inflamatórios leves podem ser tratados em casa, com antibióticos e dieta, no entanto\ncasos mais graves demandam internação\nhospitalar e apresentam risco de tratamento cirúrgico\nurgente, inclusive com realização de colostomia."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-286729","number":"286729","sourceNumber":"286729","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, 55 anos, obesa, diabética, refere quadro de dor tipo cólica\nem hipocôndrio direito que irradiou para todo o\nandar superior do abdome e dorso, tornando-se\ncontínua e intensa, há cerca de 12 horas, associada a náuseas e vômitos. Nega febre, diarreia e\nsintomas urinários. Ao exame físico, apresenta-se com fácies de dor, em bom estado geral, LOTE,\nafebril, FC: 72 bpm, FR: 24 irpm, anictérica e P.A.: 120 x 80 mmHg. Débito urinário satisfatório.\nSeu\nabdome é algo distendido, bastante doloroso à palpação do andar superior, sem sinais de irritação\nperitoneal. Hematócrito: 40%. Leucograma: 12.000. Amilase sérica: 1.800 g/dl.\n\nAssinale a alternativa CORRETA:","options":{"A":"Devemos ser cautelosos quanto à hidratação desta paciente, pois volumes superiores a 2.000 ml\nde Ringer Lactato nas primeiras 24 horas estão associados a evolução desfavorável do quadro.","B":"À admissão, a ultrassonografia seria dispensável por não evidenciar de forma precisa o grau de\nacometimento local pancreático, estando indicada a tomografia computadorizada.","C":"Os dados acima não nos permitem avaliar e classificar adequadamente a gravidade do caso,\nsendo necessária a observação clínica de falência de órgãos e sistemas por 48h.","D":"Uma vez que esta paciente apresenta fatores de risco para evolução desfavorável do quadro,\nestá indicada a antibioticoterapia com\nCiprofloxacino e Metronidazol."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-256590","number":"256590","sourceNumber":"256590","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Enunciado está relacionado para as questões 18 e 09. Criança, estudante, masculino,\npardo, procurou o pronto atendimento médico com\nqueixa de dor abdominal iniciada há cerca de 10\ndias, acompanhado de diarréia, náuseas e vômitos. Ao exame físico apresentava dor, sinais de\ndesidratação e febre (38°C). O exame abdominal tinha peristalse débil, tenso, doloroso à palpação\nsuperficial e profunda com sinais de peritonite difusa e presença de massa palpável em fossa ilíaca\ndireita. Demais aparelhos e sistemas sem alterações. Suspeitando de um abdome agudo\ninflamatória qual seria sua hipótese?","options":{"A":"Trombose Mesentérica","B":"Apendicite Aguda Perfurada","C":"Doença Inflamatória Pélvica","D":"Diverticulite"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-256591","number":"256591","sourceNumber":"256591","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Enunciado está relacionado para as questões 18 e 09. Criança, estudante, masculino,\npardo, procurou o pronto atendimento médico com\nqueixa de dor abdominal iniciada há cerca de 10\ndias, acompanhado de diarréia, náuseas e vômitos. Ao exame físico apresentava dor, sinais de\ndesidratação e febre (38°C). O exame abdominal tinha peristalse débil, tenso, doloroso à palpação\nsuperficial e profunda com sinais de peritonite difusa e presença de massa palpável em fossa ilíaca\ndireita. Demais aparelhos e sistemas sem alterações. Quais exames laboratoriais devemos\nsolicitar?","options":{"A":"Hemograma Completo, Coagulograma, TAP, sódio, cloro, potássio e EAS","B":"Hemograma Completo, Bilirrubinas, Proteínas e Amilase","C":"Coagulograma, EAS, Proteínas e TAP","D":"Hemograma Completo, TGO, TGP, Gama GT, FAL, Proteínas e VHS"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-252233","number":"252233","sourceNumber":"252233","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Menor de 12 anos, estudante, masculino, pardo, procurou atendimento médico por\nqueixa de dor abdominal iniciada há cerca de\n12 dias. Relatava durante o período episódios de\ndiarreia, náuseas e vômitos. O exame físico demonstrava dor, sinais de desidratação e febre\n(38°C). O exame abdominal tinha peristalse débil, tenso, doloroso à palpação superficial e profunda\ncom sinais de peritonite difusa e presença de massa palpável em fossa ilíaca direita. Demais\naparelhos e sistemas sem alterações. Qual seria a melhor conduta nesse paciente?","options":{"A":"Lavado peritoneal o mais precoce possível.","B":"Aguardar e esgotar todos os exames por imagem para darmos início a um tratamento clínico a\nnível domiciliar.","C":"Indicar laparotomia exploradora baseado nos achados de história e exame físico.","D":"Antibioticoterapia para esfriar o processo."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-252240","number":"252240","sourceNumber":"252240","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Qual a principal causa de abdome agudo na gestante?","options":{"A":"Diverticulite aguda.","B":"Colecistite aguda.","C":"Ileite aguda.","D":"Apendicite aguda."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-208326","number":"208326","sourceNumber":"208326","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A classificação de Hinchey é utilizada:","options":{"A":"No Cisto de Colédoco","B":"Na Hérnia Inguinal","C":"Na Pancreatite","D":"Na Diverticulite"},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-208395","number":"208395","sourceNumber":"208395","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, 44 anos, diabética, deu entrada no pronto-socorro com\nquadro de dor intensa, de início súbito, em\ntodo o andar superior do abdome associada à discreta\nicterícia e vômitos. À admissão, observou-se hiperamilasemia de 2.500 g/dl. A paciente evoluiu\ndesfavoravelmente e após 48h da admissão encontra-se taquicárdica, taquipneica, hipotensa,\nhipocorada, oligúrica, queixando piora da dor, distensão abdominal e manutenção dos vômitos,\nsendo encaminhada à UTI. Após 10 dias, a paciente mantém quadro arrastado sem melhora\nsatisfatória, queixando-se de dor em epigástrio. Realizou tomografia computadorizada de abdome\nque revelou necrose de 50% do pâncreas e volumosa coleção peripancreática. Há 24h apresenta\nnova piora de estado geral, com início de febre e leucocitose (20.000 neutrófilos com 8% de\nbastões), além de taquicardia, taquipneia e hipotensão. Assinale a alternativa CORRETA:","options":{"A":"Os elevados níveis da amilasemia já nos permitiram verificar a gravidade do caso, indicando\ntransferência para a UTI desde a admissão.","B":"O próximo passo na conduta desta paciente é a punção da coleção guiada por TC para coleta\nde material e confirmação do processo\ninfeccioso.","C":"Os dados acima nos permitem concluir que a paciente evoluiu com infecção da coleção\nnecrótica, devendo ser submetida a desbridamento cirúrgico urgente.","D":"O tratamento de escolha para esta paciente é a antibioticoterapia de largo espectro, devendo ser\niniciada empiricamente e reavaliada após 72h de acordo com a melhora clínica."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-208405","number":"208405","sourceNumber":"208405","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo masculino, 16 anos, dá entrada no pronto atendimento com quadro\nde dor tipo cólica em epigástrio, que migrou\npara a FID (Fossa ilíaca direita), associada a vômitos.\nEvolução de 3 dias. Refere 1 episódio de febre baixa hoje. Nega diarreia e sintomas urinários. O\nPaciente está em bom estado geral, eupneico, afebril, normotenso. Seu abdome é plano, flácido,\ndoloroso à palpação profunda em FID, com discreto plastrão palpável. Sinal de Blumberg positivo.\nLeucograma: 14.000 mil/mm³. USG prejudicada por excesso de gases, evidenciando apenas\npequena quantidade de líquido livre em FID e pelve. Assinale a alternativa CORRETA:","options":{"A":"A abordagem cirúrgica laparoscópica é factível para o caso acima mesmo em situação de\nperitonite purulenta.","B":"Por tratar-se de paciente jovem, imunocompetente, hemodinamicamente estável, afebril e com\ndoença em fase inicial de evolução, o\ntratamento exclusivo com antibióticos pode ser tentado,\ndevendo ser instituído tratamento cirúrgico se não houver melhora após 48h.","C":"Já que a USG não foi adequada para o diagnóstico e estadiamento da doença, o próximo passo\nna conduta deste paciente é a realização de\ntomografia.","D":"A observação de níveis hidroaéreos à radiografia de abdome confirmaria a necessidade de\ntratamento cirúrgico."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-176019","number":"176019","sourceNumber":"176019","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Para definição de prognóstico da pancreatite aguda, utilizamos os critérios de Ranson.\nSão critérios avaliados nas primeiras 24h,\nEXCETO:","options":{"A":"PaO2 > 55 mmHg.","B":"Idade > 55 anos.","C":"Glicose > 200 mg/dl.","D":"DHL > 350 UI/L."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-176052","number":"176052","sourceNumber":"176052","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo masculino, 38 anos, dá entrada no pronto atendimento com quadro\nde dor intensa em hipocôndrio direito,\nrapidamente progressiva, que migrou para todo o abdome\nsuperior e irradia para o dorso, associada a náuseas e vômitos. Refere crises anteriores de cólicas\nem hipocôndrio direito após alimentação rica em gordura, porém de menor intensidade. Evolução\nde 12 horas. Ao exame físico, encontra-se em REG, lúcido e orientado, com fácies de dor,\nanictérico, taquicárdico, taquipneico, hipotenso e oligúrico. Leucograma = 16.000; amilase = 1.450\nmg/dl. Seu abdome é tenso, bastante doloroso à palpação em andar superior, sem irritação\nperitoneal. Assinale a alternativa INCORRETA:","options":{"A":"Já que a paciente apresenta possível disfunção de órgãos à sua admissão, provavelmente será\nclassificada como quadro moderadamente grave, dependendo da sua resposta à terapia nas\npróximas 48h.","B":"A hidratação com solução salina isotônica é parte importante do tratamento inicial deste paciente\ne o volume total de infusão pode chegar até\na 12 litros em 24 horas.","C":"Já que a ultrassonografia não é método adequado para avaliação do retroperitôneo, há\nindicação de tomografia computadorizada para confirmação diagnóstica e etiológica.","D":"Não é recomendado o uso de antibióticos para este paciente neste momento, reservando-os\npara o caso de evolução desfavorável com\nevidência de necrose retroperitoneal infectada."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-151988","number":"151988","sourceNumber":"151988","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, diabética, obesa, 40 anos, deu entrada no pronto socorro\napresentando quadro de dor contínua, de\ninício súbito e rapidamente progressiva, intensa, em\nandar superior do abdome, irradiada para o dorso, associada a náuseas e vômitos, com evolução\nde 12h. Encontrava-se em REG, com fascies de dor, normocorada, anictérica, taquicárdica, algo\ndispneica e normotensa. Seu abdome é tenso, bastante doloroso à palpação em andar superior,\nsem irritação peritoneal. Em seus exames iniciais, apresentou leucograma 14.000, glicemia:\n288mg/dl, amilase: 2.300mg/dl, radiografia de tórax e ultrassom de abdome sem alterações. A\npaciente foi internada e mantida sob tratamento clínico. Após 48h, evoluiu com piora da dor\nabdominal, sinais de choque hipovolêmico, acidose metabólica, aumento das escórias nitrogenadas\ne taquidispneia importante, sendo transferida para a UTI. Após cerca de 10 dias de evolução,\npalpava-se massa de limites imprecisos em epigástrio, dolorosa à palpação. Assinale a alternativa\nCORRETA:","options":{"A":"Os dados acima nos permitem afirmar que a paciente deveria ter sido internada na UTI desde a\nadmissão já que a hiperamilasemia denotava quadro grave.","B":"Investigação de história de consumo de álcool e dosagem dos níveis de triglicerídeos séricos\npoderiam ter sido considerados na investigação etiológica do caso.","C":"Dosagens de fosfatase alcalina, desidrogenase lática e TGO estariam indicados na admissão\ndesta paciente para avaliação de sua potencial\nevolução para quadro grave.","D":"A classificação de Baltazar não pode ser empregada na avaliação desta paciente por tratar-se\nde patologia de evolução grave."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-129802","number":"129802","sourceNumber":"129802","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Na pancreatite aguda, alguns critérios para a avaliação da gravidade e prognósticos\nsão utilizados na prática clínica estão corretos,\nEXCETO:","options":{"A":"Critérios de Ranson.","B":"Proteína C reativa.","C":"APACHE-II.","D":"Sinal de Cullyen e Gray Tomer."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-129744","number":"129744","sourceNumber":"129744","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A diverticulite colônica da fase aguda pode complicar com fístulas entre o cólon e os\nórgãos adjacentes. A mais frequente complicação desta natureza é manifestada pelas:","options":{"A":"Fístulas colovaginais.","B":"Fístulas coloentéricas.","C":"Fístulas colocutâneas.","D":"Fístulas colovesicais."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-129783","number":"129783","sourceNumber":"129783","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A apendicite aguda teve sua maior contribuição em 1889, quando Charles McBurney\npublicou no New York State Medical Journal seu trabalho, recomendando a laparotomia com mais\nprecocidade. Em sua homenagem até o momento, figura o ponto McBurney, importante dado\nsemiológico no diagnóstico da doença, que tem como fator etiológico dominante:","options":{"A":"Fecalito.","B":"Parasitas intestinais.","C":"Sementes de legumes e frutas.","D":"Corpo estranho (fragmentos de ossos de aves)."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-103843","number":"103843","sourceNumber":"103843","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Fistula do trato digestivo em que na dosagem de eletrólitos é evidenciado altas taxas de\nbicarbonato, relaciona-se:","options":{"A":"fístula gástrica.","B":"fístula esofágica.","C":"fístula ileal.","D":"fístula pancreática."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-107631","number":"107631","sourceNumber":"107631","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo masculino, 34 anos, procedente do Interior do Estado, apresentando\nquadro de dor tipo cólica difusa no abdome\nque localizou na fossa ilíaca direita há cerca de 5 dias,\nsendo tratado pela infecção urinária com sulfametoxazol e trimetropim oral e sintomáticos pelo\nmédico do Posto de Saúde local. Evoluiu de forma insatisfatória com piora do quadro doloroso,\nqueda do estado geral, distensão abdominal, febre alta e vômitos, sendo transferido para Manaus.\nÀ admissão apresentava-se em regular estado geral, torporoso, pálido ++/4, taquicárdico,\ntaquipneico, anictérico e hipotenso. Refere não urinar há cerca de 12 horas. Seu abdome é\ndistendido, difusamente doloroso à palpação, mais intensamente em fossa ilíaca direita com\nirritação peritoneal difusa. Sobre a abordagem deste paciente, assinale a alternativa INCORRETA:","options":{"A":"Leucocitose expressiva, níveis hidroaéreos difusos e acidose metabólica são alterações\nprováveis na avaliação inicial.","B":"A avaliação da pressão venosa central deste paciente, que deve estar baixa, é parâmetro útil\npara a reposição hídrica e possível indicação de aminas vasoativas.","C":"Devido ao grave choque séptico instalado, há indicação de intervenção cirúrgica imediata no\nmomento da admissão deste paciente.","D":"Há indicação clara de antibioticoterapia de largo espectro com cobertura principalmente para\nbactérias gram-negativas e anaeróbias, porém sem\nindicação para o uso de antifúngicos sistêmicos\nno momento."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-103809","number":"103809","sourceNumber":"103809","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Qual opção representa fator de mau prognóstico na pancreatite aguda?","options":{"A":"Creatinina maior que 2,5","B":"Relação da hemoglobina com hematócrito na proporção de 2:3","C":"Proteína C reativa menor que 10,0","D":"Causa biliar"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-107863","number":"107863","sourceNumber":"107863","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, 18 anos, deu entrada no pronto atendimento queixando dor\ntipo cólica que iniciou no epigástrio e migrou para a fossa ilíaca direita e hipogástrio há cerca\nde 24\nhoras, associada a astenia e náuseas. Nega febre, vômitos, diarreia, leucorréia e sintomas\nurinários. Última menstruação há 2 semanas. Seu abdome é plano, simétrico, doloroso à palpação\nprofunda em fossa ilíaca direita com sinais de Rovsing e Blumberg positivos, sem plastrão palpável.\nLeucograma: 6.500, hematócrito 38% e hemoglobina 12mg/dl. EAS com 6 hemácias e 8 piócitos\npor campo. Radiografias de tórax e abdome sem alterações. A ultrassonografia evidenciou discreta\nquantidade de líquido livre na fossa ilíaca direita, sem demais alterações. Assinale a alternativa\nCORRETA:","options":{"A":"Já que a ultrassonografia não fechou o diagnóstico do paciente, há indicação de tomografia para\no caso.","B":"Já que não há febre e leucocitose, há indicação de alta hospitalar com prescrição de antibiótico\noral para tratamento de infecção urinária.","C":"Não havia indicação de nenhum dos exames complementares realizados para a indicação de\ntratamento cirúrgico.","D":"Os dados acima nos permitem afirmar que trata-se de apendicite aguda retrocecal em fase\nperfurativa, com indicação de apendicectomia e antibioticoterapia por, no mínimo, 7 dias."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-103817","number":"103817","sourceNumber":"103817","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"O teste da D-xilose tem indicação para pacientes com suspeita de:","options":{"A":"Intolerância à glicose.","B":"Pancreatite crônica.","C":"Retocolite ulcerativa.","D":"Diarreia devido a diabetes mellitus."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-103813","number":"103813","sourceNumber":"103813","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"O padrão-ouro na realização de imagens para avaliação de crianças com dor abdominal\ne suspeita de apendicite é:","options":{"A":"Radiografia simples.","B":"Ultrassonografia.","C":"Ressonância magnética.","D":"Tomografia computadorizada."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-81974","number":"81974","sourceNumber":"81974","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Na pancreatite crônica, é CORRETO afirmar que:","options":{"A":"O teste da D-xilose urinária é normal e a pesquisa de gordura fecal é positiva.","B":"O trânsito e morfologia de delgado mostra apagamento das pregas circulares no duodeno e\nquantificação da gordura fecal menor que sete gramas.","C":"D-xilose urinária baixa e pesquisa de sangue oculto positiva.","D":"Plaquetopenia e teste da secretina positiva.","E":"Anti-transglutaminase tecidual IgA positiva e pesquisa de gordura fecal positiva."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-80938","number":"80938","sourceNumber":"80938","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Homem, 51 anos, alcoolista, interna com quadro clínico-laboratorial de pancreatite\naguda. É submetido a tratamento adequado e\nreavaliado após as primeiras 48 horas. Qual dos\nseguintes achados, se detectado neste período, é indicativo de mau prognóstico?","options":{"A":"Glicemia de 180 mg/dL.","B":"Leucôcitos de15500/mm3.","C":"Aumento do nitrogênio ureico em 7 mg/dL.","D":"PO2 arterial de 65 mmHg.","E":"Estimativa de sequestro de fluídos em 5 litros."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-87468","number":"87468","sourceNumber":"87468","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Qual das alternativas a seguir é considerada patognomônica de apendicite aguda?","options":{"A":"Nível hidroaéreo em fossa ilíaca direita à radiografia de abdome em ortostase.","B":"Dor em fossa ilíaca direita, sem história de diarreia, associada à leucocitose.","C":"Fecalito em fossa ilíaca direita à radiografia de abdome em decúbito.","D":"Achado de apêndice retrocecal à ultrassonografia.","E":"NDA."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-81050","number":"81050","sourceNumber":"81050","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, 48 anos, procedente de Autazes, refere quadro de dor\nepigástrica e mesogástrica, tipo\nqueimação, de início súbito e bastante intensa, que migrou para\ntodo o abdome em poucas horas. Refere quadro crônico de epigastralgia em queimação de menor\nintesidade, com evolução de 2 anos, que controlava com chás caseiros. Foi avaliada pelo médico\nlocal que supeitou de apendicite e a encaminhou para atendimento de urgência em Manaus. Ao ser\natendida no Pronto-Socorro João Lúcio, após 10 horas do início do quadro, apresentava-se imóvel\nna maca, com respiração rápida e superficial, referindo bastante dor abdominal. Seu abdome é\nplano, difusamente doloroso à palpação superficial, com descompressão brusca dolorosa nos\nquatro quadrantes. Assinale a alternativa correta:","options":{"A":"A radiografia de tórax fecha o diagnóstico sindrômico e confirma tratamento cirúrgico sem\ndiagnóstico etiológico exato no caso acima.","B":"Por tratar-se de apendicite perfurada, o esquema antibiótico de escolha para o caso é\nCeftriaxona e Metronidazol.","C":"O hemograma e a ultrassonografia de abdome são essenciais para a conduta do caso acima.","D":"A ausência de febre e vômitos sugere tratar-se de abdome agudo inflamatório de tratamento\nclínico.","E":"Por tratar-se de dor intensa de início súbito, o diagnóstico mais provável é a trombose\nmesentérica, estando indicada arteriografia de urgência."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-81057","number":"81057","sourceNumber":"81057","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente de sexo feminino, 25 anos, refere dor abdominal tipo cólica, iniciada em\nmesogástrio, que migrou para fossa ilíaca\ndireita, associada a náuseas e 1 episódio de febre baixa,\nhá 24 horas. Seu abdome é plano, flácido, doloroso à palpação profunda em ponto de McBurney.\n\nSinal de Blumberg positivo. Qual o próximo passo na conduta desta paciente?","options":{"A":"Hemograma, exame de urina e radiografias de abdome.","B":"Ultrassonografia.","C":"Laparoscopia.","D":"Tomografia de abdome.","E":"Internação, antibióticos e observação por 24 horas."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-81065","number":"81065","sourceNumber":"81065","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, 62 anos, apresenta quadro de dor abdominal tipo cólica, de\nmoderada intesidade, em fossa ilíaca esquerda, associada a náuseas e febre baixa, há 24 horas.\nRefere constipação crônica e episódios anteriores de menor intensidade. Nega história de\nsangramento à defecação. Seu abdome é plano, flácido, doloroso à palpação profunda em fossa\nilíaca esquerda. Descompressão brusca positiva em fossa ilíaca esquerda. Não há massas ou\nplastrão palpável. Assinale a alternativa correta:","options":{"A":"A colonoscopia é o exame padrão-ouro para diagnosticar o caso acima.","B":"Já que há sinal de irritação peritoneal, a única modalidade de tratamento é cirúrgica.","C":"Já que não há história de hemorragia digestiva baixa, podemos afirmar que a constipação não\nfaz parte da gênese da patologia da paciente acima.","D":"Por tratar-se de quadro meramente inflamatório, não há indicação de antibioticoterapia no caso\nacima.","E":"A tomografia de abdome pode dar o diagnóstico e direcionar a escolha entre tratamento clínico\nou cirúrgico."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-81972","number":"81972","sourceNumber":"81972","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Que dado da história clínica não favorece o diagnóstico de apendicite?","options":{"A":"Início da dor antes dos vômitos e da diarreia.","B":"Inapetência.","C":"Migração da dor da área periumbilical para o quadrante inferior direito.","D":"Piora da dor durante a viagem para o consultório ou hospital.","E":"História de constipação."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-60845","number":"60845","sourceNumber":"60845","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação à apendicite aguda, é INCORRETO afirmar que:","options":{"A":"Complicações pós-operatórias não são raras","B":"É a causa mais frequente de cirurgia, no escolar","C":"A dor abdominal, inicialmente, é periumbilical","D":"Febre acima de 38 graus, caracteriza o quadro desde o início","E":"Vômitos, ainda que não intensos, são manifestações frequentes"},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-60850","number":"60850","sourceNumber":"60850","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A positividade do Sinal de Bassler traduz:","options":{"A":"Apendicite crônica.","B":"Úlcera gástrica perfurada.","C":"Colangite supurativa aguda.","D":"Obstrução do intestino delgado.","E":"Hemorragia intra-abdominal maciça."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-61552","number":"61552","sourceNumber":"61552","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente de 20 anos, sexo feminino vai a um pronto atendimento com queixa de dor\nabdominal, que no início era na região epigástrica, depois na região umbilical e agora no quadrante\ninferior direito. Associada à anorexia, náuseas e, vômitos e febre (37ºC). Nega atraso menstrual e\nleucorreia. Ao exame físico: abdome com RHA diminuídos, doloroso à palpação superficial e\nprofunda, espasmo muscular e descompressão brusca dolorosa no quadrante inferior direito. O\nhemograma com leucocitose (15.5000 células/mm³) com desvio para a esquerda, sem outras\nalterações laboratoriais. Diante deste quadro, qual a hipótese diagnóstica principal, conduta\npropedêutica e terapêutica? (VER IMAGEM)","options":{"A":"DIPA, toque vaginal, antibioticoterapia.","B":"Intussuscepção, toque retal e ressecção intestinal.","C":"Diverticulite de Meckel, estudo radiológico e diverticulectomia.","D":"Apendicite aguda, ultrassonografia e apendicectomia.","E":"Doença de Crohn, estudo radiológico contrastado e sulfassalazina."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-61503","number":"61503","sourceNumber":"61503","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Mulher, 63 anos de idade, deu entrada no serviço de urgência com dor em\nhemiabdome direito após episódio de tosse.\nApresentava diagnóstico de bronquite crônica há dois\nanos e três cirurgias abdominais prévias (histerectomia, drenagem de abscesso, colecistectomia).\nAo exame, cicatriz xifopubiana atrófica, massa dolorosa palpável no quadrante superior direito, com\ndescompressão dolorosa, sinal de Cullen e Grey-Turner presentes. Foram realizados exames\nlaboratoriais (incluindo perfil de coagulação) e tomografica de abdome. Qual é a hipótese\ndiagnóstica mais provável e conduta terapêutica?","options":{"A":"Pancreatite e necrosectomia.","B":"Apendicite e apendicectomia.","C":"Diverticulite de Meckel e antibioticoterapia.","D":"Hérnia incisional encarcerada e hernioplastia incisional.","E":"Hematoma de reto abdominal e conduta conservadora."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-49811","number":"49811","sourceNumber":"49811","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em um paciente com apendicite aguda, a palpação da fossa ilíaca esquerda pode\ncausar dor na fossa ilíaca direita. Este é o\nsinal de:","options":{"A":"Rovsing.","B":"Douglas.","C":"McBurney.","D":"Blumberg.","E":"Lennander."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-46663","number":"46663","sourceNumber":"46663","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação à apendicite aguda, assinale a alternativa CORRETA:","options":{"A":"Vômitos frequentes que se iniciam antes da dor estão presentes na grande maioria dos casos.","B":"Febre alta e calafrios nas primeiras 24 horas estão presentes na grande maioria dos casos.","C":"Anorexia está presente na grande maioria dos casos.","D":"Blumberg (+) no quadrante inferior direito do abdome está ausente na grande maioria dos casos.","E":"O sinal de Lenander presente torna este diagnóstico bastante improvável."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-34170","number":"34170","sourceNumber":"34170","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"G.J., 30 anos, sexo masculino, vem ao pronto-socorro onde você trabalha com dor no\nandar superior do abdome há 12 horas, iniciada durante churrasco na casa de um amigo. Teve\naumento na intensidade e começou a irradiar para o dorso. Sem melhora com dipirona. Você\nsolicita: ALT: = 200 (40), AST = 180 (35), amilase = 100 (60), lípase = 120 (50). Nesse caso o\npaciente necessita:","options":{"A":"Repouso apenas, pois a pancreatite é de leve intensidade, já que a hiperamilasemia é pouco\nexpressiva.","B":"De dieta zero e analgesia potente, pois apresenta pancreatite aguda.","C":"De tomografia de abdome para confirmar o diagnóstico.","D":"De diagnósticos diferenciais, já que a lípase maior que a amilase obriga maior investigação.","E":"De cuidados intensivos, pois tem 03 pontos nos critérios de gravidade de Ranson."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-26461","number":"26461","sourceNumber":"26461","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente masculino, 59 anos de idade, com história de dor no quadrante inferior\nesquerdo do abdômen, associada a febre e\nsinais de irritação peritoneal. O leucograma apresenta\nleucocitose com desvio a esquerda. O exame radiológico do abdome evidencia gás extra-luminal. A\ntomografia computadorizado do abdome mostra espessamento da parede abdominal e divertículos.\nO próximo passo na abordagem desse paciente deve ser?","options":{"A":"laparotomia exploradora","B":"colonoscopia","C":"ressonância nuclear magnética","D":"ultrassonografia abdominal","E":"ceftriaxona + metronidazol"},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-26439","number":"26439","sourceNumber":"26439","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Qual das opções abaixo NÃO é indicação para laparotomia em paciente com abdome\nagudo:","options":{"A":"pneumoperitônio visto em radiografia de tórax","B":"pneumoperitônio visto em radiografia de abdome","C":"gás em intestino delgado em radiografia de abdome (alça sentinela)","D":"gás em retroperitônio em radiografia de abdome","E":"todas as opções são indicadas para laparotomia"},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-26483","number":"26483","sourceNumber":"26483","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Qual dos itens abaixo representam o melhor exame para diverticulite e doença\ndiverticular respectivamente:","options":{"A":"Colonoscopia e enema opaco","B":"Tomografia e toque retal","C":"Tomografia e enema opaco","D":"Enema opaco e tomografia","E":"Colonoscopia e USG"},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-26656","number":"26656","sourceNumber":"26656","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente de 70 anos com história de cardiopatia deu entrada no pronto-socorro\nreferindo dor intensa e prolongada do abdômen\ncom leucocitose de 20 mil e discreto aumento da\namilase, com poucos achados clínicos ao exame do abdômen, qual a principal hipótese\ndiagnóstica?","options":{"A":"Pancreatite leve.","B":"Câncer de cólon","C":"Ruptura de aneurisma de aorta-abdominal","D":"Colecistite enfisematosa","E":"Isquemia mesentérica aguda"},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-26642","number":"26642","sourceNumber":"26642","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"O diagnóstico diferencial mais importante da doença diverticular dos cólons complicada\ndeve ser feito com:","options":{"A":"Retocolite ulcerativa","B":"Doença de Crohn","C":"Adenocarcinoma de sigmoide","D":"Colite isquêmica","E":"Estenose actínica"},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-7437","number":"7437","sourceNumber":"7437","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em caso de criança com suspeita clínica de hepatite viral, os marcadores virais séricos\na serem solicitados para definição do agente\netiológico são:","options":{"A":"Anti-HVA IgM + AgHBs + Anti-HVC.","B":"Anti-HVA IgM + AgHBs + Anti-HBcIgG.","C":"Anti-HVA IgG + AntiHBs + Anti-HVC.","D":"Anti-HVA IgG + Anti-HVA IgM + AgHBs.","E":"Nenhuma delas."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-9960","number":"9960","sourceNumber":"9960","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Assinale a alternartiva incorreta:","options":{"A":"A úlcera péptica de parede posterior tem maior potencial de perfuração.","B":"A úlcera duodenal de parede anterior apresenta maior potencial de perfuração.","C":"A causa mais comum da pancreatite aguda é de origem biliar.","D":"O abdômen agudo isquêmico tem como fator desencadeante mais frequente as arritmias\ncardíacas.","E":"A complicação precoce mais frequente pós-apendicectomia é o abscesso da parede."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-7470","number":"7470","sourceNumber":"7470","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"É considerado Shunt portossistêmico seletivo, empregado para o tratamento da\nhipertensão porta:","options":{"A":"derivação portocava calibrada.","B":"Shunt esplenorrenal convencional.","C":"Shunt esplenorrenal distal.","D":"Shunt mesocava.","E":"Shunt portocava laterolateral."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-284589","number":"284589","sourceNumber":"284589","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente, sexo feminino, 30 anos de idade, é levada ao pronto-socorro do Hospital\nRegional com história de dor em abdome\ninferior, de moderada intensidade, há 12 horas, sem\nmelhora com analgésico comum. A paciente refere também hiporexia, alguns episódios de náuseas\ne vômitos, disúria e polaciúria há dois dias. Nega outros sintomas e comorbidades. Ao exame físico,\nbom estado geral, corada, desidratada +1/+4, FC: 94 bpm, PA: 110 x 74 mmHg, FR: 18 imp, T:\n37,9ºC; auscultas cardíaca e respiratória sem alterações; abdome um pouco distendido, ruídos\nhidroaéreos um pouco aumentados difusamente, flácido, dor à palpação profunda de hipogástrio,\nsinal de Giordano negativo. Realizados exames laboratoriais que apresentaram Hb: 12 g/dl, Ht =\n36%, Leucócitos totais: 14.000 células/mm³ (Bastões 4%), Ureia: 35 mg/dl, Creatinina: 1,0 mg/dl,\nNa: 142 mEq/L. Exame de urina: leucócitos 1.000.000 céls/ml, hemácias 1.000.000 céls/ml. Foi\nrealizada tomografia computadorizada de abdome. Indique a principal suspeita diagnóstica que\nmotivou a paciente a procurar o pronto-socorro.","options":{"A":"Cistite aguda.","B":"Doença inflamatória pélvica aguda.","C":"Apendicite aguda.","D":"Gravidez ectópica."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-284590","number":"284590","sourceNumber":"284590","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente, sexo feminino, 30 anos de idade, é levada ao pronto-socorro do Hospital\nRegional com história de dor em abdome\ninferior, de moderada intensidade, há 12 horas, sem\nmelhora com analgésico comum. A paciente refere também hiporexia, alguns episódios de náuseas\ne vômitos, disúria e polaciúria há dois dias. Nega outros sintomas e comorbidades. Ao exame físico,\nbom estado geral, corada, desidratada +1/+4, FC: 94 bpm, PA: 110 x 74 mmHg, FR: 18 imp, T:\n37,9ºC; auscultas cardíaca e respiratória sem alterações; abdome um pouco distendido, ruídos\nhidroaéreos um pouco aumentados difusamente, flácido, dor à palpação profunda de hipogástrio,\nsinal de Giordano negativo. Realizados exames laboratoriais que apresentaram Hb: 12 g/dl, Ht =\n36%, Leucócitos totais: 14.000 células/mm³ (Bastões 4%), Ureia: 35 mg/dl, Creatinina: 1,0 mg/dl,\nNa: 142 mEq/L. Exame de urina: leucócitos 1.000.000 céls/ml, hemácias 1.000.000 céls/ml. Foi\nrealizada tomografia computadorizada de abdome. Identifique outro exame complementar que\npoderia ajudar na confirmação do diagnóstico dessa paciente.","options":{"A":"Ultrassonografia de rins e vias urinárias.","B":"Dosagem de beta HCG sérico.","C":"Videolaparoscopia.","D":"Radiografia de abdome agudo."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-284591","number":"284591","sourceNumber":"284591","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente, sexo feminino, 30 anos de idade, é levada ao pronto-socorro do Hospital\nRegional com história de dor em abdome\ninferior, de moderada intensidade, há 12 horas, sem\nmelhora com analgésico comum. A paciente refere também hiporexia, alguns episódios de náuseas\ne vômitos, disúria e polaciúria há dois dias. Nega outros sintomas e comorbidades. Ao exame físico,\nbom estado geral, corada, desidratada +1/+4, FC: 94 bpm, PA: 110 x 74 mmHg, FR: 18 imp, T:\n37,9ºC; auscultas cardíaca e respiratória sem alterações; abdome um pouco distendido, ruídos\nhidroaéreos um pouco aumentados difusamente, flácido, dor à palpação profunda de hipogástrio,\nsinal de Giordano negativo. Realizados exames laboratoriais que apresentaram Hb: 12 g/dl, Ht =\n36%, Leucócitos totais: 14.000 células/mm³ (Bastões 4%), Ureia: 35 mg/dl, Creatinina: 1,0 mg/dl,\nNa: 142 mEq/L. Exame de urina: leucócitos 1.000.000 céls/ml, hemácias 1.000.000 céls/ml. Foi\nrealizada tomografia computadorizada de abdome. Indique o tratamento mais adequado que deve\nser instituído.","options":{"A":"Prescrever antibiótico e internar.","B":"Prescrever antibiótico oral para casa.","C":"Internar e prescrever metotrexato.","D":"Realizar laparotomia exploradora."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-49320","number":"49320","sourceNumber":"49320","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Homem, 47 anos de idade, etilista crônico, com dor em abdome superior em faixa, após\nlibações alcoólicas, associadas a vômitos há três anos, vem com dor persistente nos últimos seis\nmeses, associada à perda ponderal de 4 kg. Nega icterícia. É grande tabagista. Tem ritmo intestinal\nde três dejeções ao dia, fezes formadas. Exame físico mostra perda evidente da massa muscular,\nsem sinais periféricos de hepatopatia. Abdome sem visceromegalias. Tomografia de abdome\nmostra calcificações pancreáticas. A reposição de enzimáticas pancreáticas, nesse paciente,","options":{"A":"está indicada já, para controle da dor.","B":"não deve ser feita, pois não há esteatorreia.","C":"sem abstinência alcoólica, piora os sintomas.","D":"só deve ser feita após teste de função pancreática.","E":"está indicada apenas nas agudizações."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-49435","number":"49435","sourceNumber":"49435","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente, 18 anos de idade, sexo masculino, cursa com dor mesoepigástrica que\nmigrou para fossa ilíaca direita há mais ou menos 12 horas, de forte intensidade, associada a\nnáuseas e a vômitos. Ao exame físico, notavam-se os sinais de Rovsing e Blumberg positivos.\nAfebril. Leucograma: 12300, 2% principal bastões. A principal suspeita diagnóstica é:","options":{"A":"apendicite aguda.","B":"colecistite aguda.","C":"diverticulite aguda.","D":"prostatife.","E":"orquiepididimite."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-49442","number":"49442","sourceNumber":"49442","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente, 18 anos de idade, sexo masculino, cursa com dor mesoepigástrica que\nmigrou para fossa ilíaca direita há mais ou\nmenos 12 horas, de forte intensidade, associada a\nnáuseas e a vômitos. Ao exame físico, notavam-se os sinais de Rovsing e Blumberg positivos.\nAfebril. Leucograma: 12300, 2% principal bastões. São diágnósticos diferenciais plausíveis do caso\nem questão, exceto:","options":{"A":"linfadenite mesentérica.","B":"intussuscepção ileocecal.","C":"diverticulite de Meckel.","D":"doença de Crohn.","E":"laceração de Maillory-Weiss."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-34982","number":"34982","sourceNumber":"34982","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Mulher, 45 anos de idade, previamente sadia, tem atendimento médico, apresentando\nurina escura, febre, dor abdominal que se\nirradia para as costas, náuseas e vômitos, distensão\nabdominal, reação em defesa da parede abdominal. A avaliação laboratorial mostra leucograma\ncom 20000 cel/mm³, seg: 78%, bt: 8%, linf: 6%, eo: 1%, mo: 5%; plaquetas: 110000; glicemia· 220\nmg%; TGO: 500 UI; TGP: 200 UI; ureia: 80 mg%; creatinina: 1,8 mg%; bilirrubinas: 2,5 mg%; BD:\n1,5 mg% e BI = 1,0 mg%. Amilase sérica: 450 UI, LDH: 380 UI/L. Diante do quadro, o diagnóstico\nclínico mais provável é:","options":{"A":"Perfuração de víscera oca, cursando com peritonite fecal e disfunção de órgãos.","B":"infarto mesentérico, por trombose mesentérica, evoluindo com grave repercussão para os\nórgãos intraperitoneais e Disfunção de\n\nMúltiplos Órgãos e Sistemas (DMOS).","C":"hepatite aguda, evoluindo com Disfunção de\nMúltiplos Órgãos e Sistemas (DMOS).","D":"pancreatite aguda grave, apresentando quatro critérios de Ranson na admissão.","E":"colecistite e colangite, evoluindo com Disfunção de Múltiplos Órgãos e Sistemas (DMOS)."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-27429","number":"27429","sourceNumber":"27429","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A artéria mesentérica inferior é ramo direto da artéria:","options":{"A":"hepática.","B":"renal esquerda.","C":"mesentérica superior.","D":"celíaca.","E":"aorta."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-11125","number":"11125","sourceNumber":"11125","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente, sexo feminino, 71 anos de idade, hipertensa, relata icterícia, colúria e acolia\nfecal há 35 dias. Ao exame físico, notava-se sinal de Curvoisier. Rotina laboratorial revelou\nhiperbilinirrubinemia à custa de bilirrubina direta e discreto aumento das transaminases hepáticas.\nFosfatase alcalina e gamaglutamiltransferase muito aumentadas. CA 19-9:205 U/ml. CEA:0,56.\n\nRealizou ultrassonografia do abdome superior, que demonstrou dilatação importante das vias\nbiliares intra e extra-hepáticas e massa\nhipoecoica e sólida na cabeça do pâncreas, medindo 1,8\ncentímetros. O melhor passo propedêutico a seguir para esse caso clínico, é:","options":{"A":"colangiopancreatografia retrógrada endoscópica, CPRE","B":"colangiorressonância magnética nuclear, CPRM","C":"tomografia axial computadorizada helicoidal do abdome","D":"laparotomia exploradora","E":"videolaparoscopia diagnóstica"},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-358777","number":"358777","sourceNumber":"358777","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A dor abdominal aguda é uma queixa frequente na APS, e não é raro ver pacientes\ncom esta queixa apresentarem quadros que\nnecessitem de intervenções mais urgentes. Analise as\nalternativas a seguir sobre a abordagem da dor abdominal aguda na APS e assinale a correta.","options":{"A":"A obstrução intestinal se caracteriza por dor em cólicas de localização dependente do local da\nobstrução e embora normalmente curse com parada da eliminação de fezes, casos de\n\nsemi-oclusão podem cursar com diarreia paradoxal.","B":"A presença do sinal de Murphy confirma o diagnóstico de colecistite aguda e os pacientes\ndevem receber uma dose de antibiótico enquanto aguardam encaminhamento ao serviço de\ncirurgia de urgência.","C":"Pacientes com dor em faixa em abdome superior têm suspeita aumentada de pancreatite, que\nexige intervenção cirúrgica imediata.","D":"Dor periumbilical com irradiação para fossa ilíaca direita com defesa voluntária à palpação local\ntem sido descritas como sinal sugestivo de apendicite aguda, porém menos da metade das\npessoas com quadro semelhante tem confirmação deste diagnóstico após cirurgia.","E":"Dor em flanco com irradiação para as costas e para a região genital levanta a suspeita de\nurolitíase, e a melhor opção de manejo da dor é a administração de antiespasmódicos por via\nvenosa."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-343362","number":"343362","sourceNumber":"343362","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Jovem, masculino, há 3 dias com hiporexia, náuseas, desconforto epigástrico,\nqueixando-se hoje de piora da dor, mais\nlocalizada em fossa ilíaca direita associada a 2 picos de\nfebre aferida. Ao exame físico: bom estado geral, corado, hidratado, eupneico, anictérico. Exame\nfísico cardiopulmonar normal, exceto leve taquicardia. Ruídos abdominais presentes, sem\nalterações na inspeção, porém com dor a palpação de fossa ilíaca direita. Sinal de Blumberg\npresente. Foi submetido a exames laboratoriais que resultaram em um escore de Alvarado de 10\npontos. Não há exames de imagem disponível no serviço. A conduta mais adequada é:","options":{"A":"Transferência para realizar tomografia de abdome.","B":"Cirurgia.","C":"Alta com sintomáticos.","D":"Anti-inflamatório não hormonal e reavaliação em 48h."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-343363","number":"343363","sourceNumber":"343363","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente feminina, 80 anos, internada com diverticulite aguda, submeteu-se à\ntomografia de abdome com contraste endovenoso\nque evidenciou processo inflamatório colônico\ncom divertículos e a presença de coleção pélvica bloqueada. Trata-se de diverticulite aguda,\nclassificada por Hinchey (clássica) em grau:","options":{"A":"II","B":"III","C":"IV","D":"IV"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-343364","number":"343364","sourceNumber":"343364","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Jovem, masculino, 32 anos, é internado por episódios de vômitos de início há 24 horas,\nassociado a dor abdominal refratária à analgésicos simples. Nega febre. Nega trauma recente.\n\nNega sintomas urinários. Refere anorexia. Ao exame físico: regular estado geral, desidratado\n\n+++/4, corado, anictérico, afebril, taquicárdico. Ausculta pulmonar normal. Abdome com cicatriz\nprévia de laparotomia mediana por trauma (há\n3 anos), distendido, ruídos abdominais muito\nreduzidos, doloroso em epigástrio e todo andar superior, mas sem sinais de peritonite. Realizou\nradiografia (abaixo) e foi submetido a ultrassonografia que visualizou vesícula biliar com parede de\n3 mm, com cálculos em seu interior, múltiplos, todos com tamanho menor que 5 mm, e ducto\ncolédoco com 4 mm. O pâncreas não foi visualizado por interposição gasosa. A principal hipótese\ndiagnóstica e o tratamento mais adequado é:","options":{"A":"Pancreatite aguda biliar - jejum, analgesia e hidratação, e posteriormente colecistectomia.","B":"Colecistite aguda - colecistectomia.","C":"Colecistite aguda - colangiopancreatografia retrógrada endoscópica.","D":"Bridas - cirurgia de Hartmann."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-281874","number":"281874","sourceNumber":"281874","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Nos quadros de diverticulite aguda, pela classificação tomográfica de Hinchey, o\nachado de abscesso pélvico, é classificado em:","options":{"A":"Hinchey I","B":"Hinchey II","C":"Hinchey III","D":"Hinchey IV"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-249992","number":"249992","sourceNumber":"249992","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente masculino, 18 anos, sem comorbidades, há 2 dias com hiporexia, náuseas,\nassociado a desconforto epigástrico,\nprocurou pronto-socorro hoje, pois a dor havia piorado, mais\nintensa, mais localizada em fossa ilíaca direita junto com 2 picos de febre aferida. Nega vômitos.\nAo\nexame, bom estado geral, corado, hidratado, eupneico, anictérico. Exame físico cardiopulmonar\nnormal, exceto por frequência cardíaca de 112 bpm. Ao exame abdominal: ruídos presentes, sem\nalterações na inspeção, porém com dor a palpação de fossa ilíaca direita. Sinal de Blumberg\npresente. Foi submetido a exames laboratoriais que, somado aos dados acima resultaram em um\nescore de Alvarado de 09 pontos. Não há exames de imagem disponível no serviço. A conduta\nmais adequada é:","options":{"A":"Transferência imediata para realizar ecografia de abdome.","B":"Jejum, hidratação, analgesia e transferência para exames de imagem.","C":"Apendicectomia.","D":"Alta com sintomáticos."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-249995","number":"249995","sourceNumber":"249995","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Idoso, 68 anos, queixando-se de dor abdominal há 4 dias, mais localizada em fossa\nilíaca esquerda, associada à febre, diarreia e\nqueda do estado geral. Queixa-se também de disúria.\nNega vômitos. Foi internado para investigação e realizado tomografia abdominal com contraste\nendovenoso (imagem abaixo). Ao exame físico: regular estado geral, corada, hidratada. Aparelho\ncardiopulmonar sem alterações. Abdome com ruídos presentes, flácido, doloroso em fossa ilíaca\nesquerda e hipogástrio, sem sinais de peritonite. Hemograma com leucocitose, função renal normal,\ne exame de urina com leucocitúria abundante. Assinale a alternativa correta:","options":{"A":"Trata-se de diverticulite aguda simples - Hinchey II.","B":"Trata-se de diverticulite aguda, complicada com fístula colovesical.","C":"Trata-se de doença diverticular do cólon complicada com abscesso em loja renal esquerda.","D":"Trata-se de diverticulite aguda complicada, Hinchey III, com sinais tomográficos de\npneumoperitônio."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-215570","number":"215570","sourceNumber":"215570","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação à avaliação primária da paciente\ngestante vítima de trauma.","options":{"A":"A monitorização fetal contínua com cardiotocografia deve ser feita após 20 a 24 semanas de\ngestação.","B":"O útero deve ser deslocado manualmente para direita a fim de aliviar a pressão sobre a veia\ncava inferior.","C":"Em virtude do aumento de seu volume intravascular, a gestante pode perder uma quantidade\nsignificativa de seu volume circulante\nantes que ocorram taquicardia, hipotensão e outros sinais de\nhipovolemia.","D":"O feto pode estar em sofrimento e a placenta privada de perfusão vital, enquanto as condições\nda mãe e os sinais vitais parecem estar\nestáveis."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-218122","number":"218122","sourceNumber":"218122","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Considerando a classificação do abdome agudo, segundo a natureza do processo\ndeterminante, numere a segunda coluna de acordo\ncom a primeira. (1) Perfurante; (2) Obstrutivo;\n\n(3) Inflamatório; ( ) Apendicite; ( ) Cálculo biliar; ( ) Úlcera péptica; ( ) Hérnia estrangulada. A\nalternativa que contém a sequência CORRETA, de cima para baixo, é:","options":{"A":"1, 2, 3, 3.","B":"2, 2, 3, 1.","C":"2, 3, 1, 3.","D":"3, 2, 1, 2.","E":"3, 1, 2, 1."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-215583","number":"215583","sourceNumber":"215583","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A apendicite aguda é a causa mais comum de urgência abdominal aguda\n\nnão-traumática na criança entre os 4 e os 15 anos de idade. Assinale a alternativa INCORRETA.","options":{"A":"O principal fator desencadeante da apendicite aguda é a obstrução intrínseca da luz apendicular,\ncom proliferação bacteriana, que é seguida de\nprocesso inflamatório inicial.","B":"O diagnóstico da apendicite aguda é eminentemente clínico e evidenciado pela palpação do\nabdome, onde se observa dor localizada na fossa ilíaca direita.","C":"Devem ser consideradas no diagnóstico diferencial: gastroenterocolite, diverticulite de Meckel,\ninfecções urinárias, adenite mesentérica, peritonite primária, pneumonia, entre outros.","D":"A complicação mais frequente no pós-operatório da apendicectomia é a formação de abscessos\nintraperitoneais."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-181160","number":"181160","sourceNumber":"181160","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um exame físico bem conduzido é fundamental para o desenvolvimento de um\ndiagnóstico diferencial acurado de abdome agudo. Com relação aos sinais do exame físico\nabdominal, assinale a alternativa com associação INCORRETA:","options":{"A":"Sinal de Rovsing ? Elevação e extensão da perna contra resistência cria dor.","B":"Sinal de Courvoisier ? vesícula biliar palpável na presença de icterícia.","C":"Sinal do Candelabro ? dor extrema abdominal e pélvica inferior com o movimento do colo do\nútero.","D":"Sinal de Aaron ? dor no epigástrio com persistente pressão aplicada no ponto de McBurney."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-157755","number":"157755","sourceNumber":"157755","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Assinale a alternativa CORRETA em relação à pancreatite aguda em crianças.","options":{"A":"Em crianças, a principal causa são as doenças hereditárias.","B":"As causas de pancreatite aguda em crianças geralmente são bem definidas, sendo que, na\nmaioria dos casos, a doença é secundária à doença biliar.","C":"De acordo com a maioria dos autores, as cinco principais causas de pancreatite aguda na\ncriança são: doenças biliares, pancreatite\nmedicamentosa, pancreatite aguda idiopática, doenças\nsistêmicas e trauma.","D":"Ao contrário do que ocorre em adultos, a ocorrência de pancreatite aguda secundária a\nmedicamentos em crianças não foi constatada."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-157756","number":"157756","sourceNumber":"157756","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Qual das seguintes medicações está associada à pancreatite aguda, em crianças?","options":{"A":"Clindamicina.","B":"Furosemida.","C":"Insulina simples.","D":"Ácido valproico."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-157737","number":"157737","sourceNumber":"157737","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação ao prognóstico da pancreatite aguda em crianças, marque a opção\nCORRETA.","options":{"A":"A mortalidade é maior do que nos pacientes adultos.","B":"A presença de síndrome da resposta inflamatória sistêmica na primeira semana de evolução e a\nnecrose pancreática são fatores de risco para a pior evolução.","C":"O pseudocisto é a principal complicação imediata.","D":"Todos os pseudocistos são manejados com intervenção cirúrgica."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-157674","number":"157674","sourceNumber":"157674","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Dentre as infecções relacionadas ao diabético, situações cirúrgicas como a colecistite\ngangrenosa (enfisematosa), que é uma infecção grave, levam à formação de gás dentro da\nvesícula biliar. As alternativas abaixo apresentam características dessa infecção, com EXCEÇÃO\nde uma. Aponte-a.","options":{"A":"Os microrganismos mais comumente envolvidos são Clostridium sp. e gram-negativos como E.\ncoli.","B":"Em geral, acomete homens idosos com DM.","C":"Em sua totalidade de casos não se detecta cálculo.","D":"Sua mortalidade é mais elevada que a da colecistite usual."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-134717","number":"134717","sourceNumber":"134717","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"São sinais prognósticos de Ranson na Pancreatite Aguda:","options":{"A":"na admissão: idade acima de 55 anos, glicemia acima de 200 mg%, leucocitose maior que 16\nmil/mm3.","B":"com 48 horas de evolução: queda de 5% do hematócrito, cálcio sérico menor que 8 mg%,\nsequestro de líquido maior que 6 litros.","C":"na admissão: idade acima de 55 anos, glicemia acima de 200 mg%, leucocitose maior que 12\nmil/mm3.","D":"com 48 horas de evolução: queda do hematócrito maior que 10%, cálcio sérico menor que 8\nmg%, sequestro de líquido maior que 3 litros."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-321285","number":"321285","sourceNumber":"321285","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Homem de 56 anos, previamente saudável, comparece à emergência com queixa de\ndor na Fossa Ilíaca Esquerda (FIE) e\nobstipação progressiva há 4 dias. O paciente não defeca há 2\ndias e elimina poucos flatos. Refere ainda 2 episódios de febre 38 graus Celsius. Ao exame: bom\nestado geral, FC 96 bpm, abdome algo distendido, RHA diminuídos, flácido a palpação com defesa\nem FIE, onde se palpa um plastrão. Exames: leucócitos 16.000 mm³ e PCR 15 mg/dl. Tomografia\nmostra distensão colônica moderada, espessamento da parede de sigmoide com borramento\ndiscreto da gordura mesocólica adjacente. Sem outros achados. Qual a melhor conduta para esse\npaciente?","options":{"A":"Tratar com antibióticos venosos e programar colectomia eletiva.","B":"Indicar colostomia proximal, antibióticos para aliviar essa crise.","C":"Realizar colectomia com colostomia à Hartman nesse internamento.","D":"Tratar com antibióticos orais e manter uma dieta líquida até alívio da obstipação."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-292799","number":"292799","sourceNumber":"292799","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente de 85 anos apresenta dor abdominal aguda há 48h. A dor é difusa, porém\nmais intensa em Fossa Ilíaca Direita (FID). HPP: DM e HAS compensadas com medicações. A\ntomografia sem contraste sugere apêndice espessado, líquido em FID e pelve compatível com\napendicite. Qual deve ser a conduta para esse paciente?","options":{"A":"Apendicectomia videolaparoscópica.","B":"Apendicectomia aberta infraumbilical.","C":"Drenagem percutânea e apendicectomia em 4 semanas.","D":"Colonoscopia, para avaliar neoplasia de base apendicular."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-259697","number":"259697","sourceNumber":"259697","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente de 48 anos está internada em UTI há 2 semanas por pancreatite aguda\npós-CPRE. O quadro clínico era estável, nas últimas 48 horas houve diminuição da diurese,\nfrequência cardíaca persistentemente elevada, febre recorrente e hipotensão com necessidade de\ndrogas vasoativas. A mudança terapêutica será estabelecida principalmente baseada em qual dos\nseguintes exames?","options":{"A":"Lactato sérico e gasometria.","B":"Hemograma e proteína C-reativa.","C":"Tomografia abdominal com contraste.","D":"Hemocultura e sensibilidade bacteriana."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-350857","number":"350857","sourceNumber":"350857","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente de 32 anos, usuária de drogas, é admitida com quadro de febre e dor em\nhipocôndrio esquerdo. A paciente apresenta marcas de punções venosas em fossas cubitais e\npunho. Exames Hemoglobina: 10 g/dL, leucócitos 18.500 células/mm³ ; neutrófilos 80%; bastões\n3%; eosinófilos 0%; linfócitos 14%; Proteína C Reativa 30mg/dL. Sorologia negativa para retrovírus.\nA tomografia mostra uma imagem no baço de cerca de 6cm, multisseptada, com conteúdo líquido\nespesso e realce periférico, sem captação de contraste em área central. Foi iniciado antibiótico\nempírico endovenoso. Qual conduta deve ser adotada para essa paciente?","options":{"A":"Esplenectomia, drenagem sub-frênica e antibiótico.","B":"Tratamento com antibióticos até regressão da área líquida do abscesso.","C":"Punção esplênica para pesquisa de células neoplásicas e cultura do líquido.","D":"Aposição de dreno por radiologia intervencionista e manutenção do antibiótico."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-350896","number":"350896","sourceNumber":"350896","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Mulher de 35 anos apresenta dor abdominal em andar superior, com irradiação para\ndorso, acompanhada de vômitos incoercíveis, há 2\ndias. Exame físico: PA 120x80mmHg FC 76bpm\nFR 18irpm SpO? 96% em ar ambiente Glasgow 15 ACP: RCR 2T BNF SS / MVU, sem sopros ABD:\ndefesa em região superior do abdome por dor. Sem edema de membros inferiores Exames\nlaboratoriais: Hb 12,5g/dL Leucócitos 8.700/mm³ com diferencial normal Plaquetas 428.000/mm³ ,\nCr 0,7mg/dL, Ureia 20mg/dL, Amilase 500UI/L, Lipase 600UI/L. Qual a conduta nesse caso?","options":{"A":"Indicar cirurgia de urgência.","B":"Iniciar nutrição parenteral precocemente.","C":"Administrar antibioticoterapia endovenosa.","D":"Prescrever hidratação venosa, dieta zero e analgesia."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-350878","number":"350878","sourceNumber":"350878","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Adolescente, sexo feminino, 14 anos, obesa, histórico de litíase biliar, é trazida à\nemergência com vômitos e dor abdominal forte que levam à posição com quadris e joelhos\nflexionados. O início foi súbito há 8 horas e a dor é constante. Exame físico: posição antálgica,\ndiscreta distensão abdominal e dor à palpação de todo o andar superior do abdômen. Foram\nrealizados exames laboratoriais. Considerando a hipótese diagnóstica mais provável, qual das\nseguintes alternativas representa o exame laboratorial mais importante para confirmação\ndiagnóstica?","options":{"A":"Lipase.","B":"Hemograma.","C":"Sumário de urina.","D":"Fosfatase alcalina."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-292828","number":"292828","sourceNumber":"292828","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Mulher de 42 anos teve alta hospitalar há 5 semanas, após internamento por\npancreatite aguda grave. Estava bem, clinicamente,\nquando voltou a apresentar dor abdominal,\nnáuseas e vômitos, além de elevação das enzimas pancreáticas. Qual a complicação mais\nprovável, nesse momento?","options":{"A":"Pseudocisto pancreático.","B":"Coleções necróticas agudas.","C":"Trombose de veia esplênica.","D":"Abcessos peripancreáticos agudos."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-259719","number":"259719","sourceNumber":"259719","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Mulher, 39 anos, com dor epigástrica aguda, intensa 9/10, acompanhada de náuseas e\nvômitos e com irradiação para o dorso é avaliado no pronto-atendimento. Ao exame, PA 90 x 60\nmmHg, T: 37oC, FR 22 irpm, pulso 105 bpm, taquipneica, hipoidratada, ansiosa, ictérica +2/4. IMC\n32 kg/m². Ausculta pulmonar: estertores em bases bilaterais. Abdome: rígido e doloroso a palpação,\nruídos hidroaéreos reduzidos, presença de equimoses periumbilicais. Pulsos finos e débeis. Tempo\nde enchimento capilar > 3 segundos. Exames laboratoriais: Hb 15 g/dL Ht 50% 17500\nleucocitos/mm³, Ur 83 mg/dL Cr: 1,5 mg/dL, TGO 55 U/L (VR < 50 U/L), TGP 62 U/L (VR < 68 U/L)\nGlicemia 350 mg/dL gasometria arterial pH 7,25 pCO? 30 mmHg pO? 90 mmHg HCO? 20 mmHg\nAnion Gap 18 mEq/L saturação O? 92%. LEGENDA: PA: pressão arterial; T: temperatura; FR:\nfrequência respiratória; irpm: incursões respiratórias por minuto; bpm: batimentos por minuto; IMC:\níndice de massa corporal; TEC: tempo de enchimento capilar; Hb: hemoglobina; Ht: hematócrito;\nUr: ureia; Cr: creatinina. Qual o diagnóstico mais provável e manejo inicial mais adequado?","options":{"A":"Apendicite aguda; hidratação, laparotomia e antibioticoterapia.","B":"Cetoacidose diabética; hidratação intravenosa e insulinoterapia.","C":"Ruptura de gravidez ectópica; hidratação intravenosa e laparotomia.","D":"Pancreatite aguda; hidratação intravenosa e suspensão da dieta oral."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-199768","number":"199768","sourceNumber":"199768","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente foi atendido na UPA e referido a uma emergência cirúrgica. Ele tem 62\nanos, e queixa de dor abdominal em Fossa\nIlíaca Esquerda (FIE) de intensidade crescente nos\núltimos 4 dias. Teve 3 episódios de febre (T = 38,7°C) nas últimas 48 horas, está taquicárdico (FC =\n102 bpm), nega anorexia ou vômitos ou parada da eliminação de flatos. Ao exame abdominal, tem\ndor à palpação superficial e profunda localizada em FIE com ausência de descompressão brusca\nou distensão abdominal ou outros sinais de irritação peritoneal. Foi realizada tomografia de abdome\nque revelou presença de espessamento da parede do sigmoide e de sinais sugestivos de\ninflamação do mesocólon correspondente, pequena coleção com conteúdo hidroaéreo pericólica de\n2 cm e ausência de pneumoperitônio. Qual deve ser a conduta proposta?","options":{"A":"Internar o paciente com prescrição de jejum e antibióticos parenterais.","B":"Contra referir o paciente à UPA para tratamento clínico conservador.","C":"Solicitar colonoscopia para confirmar o diagnóstico de diverticulite.","D":"Indicar e encaminhar para laparotomia de urgência."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-199688","number":"199688","sourceNumber":"199688","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um jovem de 19 anos retorna à UPA após 8 horas do primeiro atendimento, com\npersistência de dor abdominal, antes\ntratada com analgésico endovenoso. No momento, queixa-se\nde dor periumbilical com predominância à direita, náuseas e anorexia. Em sua avaliação,\nobservam-se os achados de leve sensibilidade à descompressão em fossa ilíaca direita,\ntemperatura = 37,8°C, sinais de Dunphy e do obturador positivos. Laboratório com Hb = 11,7 g/dl,\nleucócitos = 11.840/mm³ e 7% de bastões. O paciente realizou ultrassonografia abdominal que foi\nprejudicada pela presença gasosa e descreve pouco líquido livre em pelve. Qual a conduta a ser\ntomada?","options":{"A":"Iniciar protocolo de tratamento clínico de apendicite aguda.","B":"Indicar tratamento cirúrgico para realização da apendicectomia.","C":"Transferir para realização de tomografia abdominal sem contraste.","D":"Analgesia e antibiótico venoso, repetir o ultrassom com 8 a 12 horas."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-150848","number":"150848","sourceNumber":"150848","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Mulher, 32 anos, está internada na enfermaria há 12 dias com diagnóstico de\npancreatite aguda. A ultrassonografia\nabdominal mostrou a presença de cálculos na vesícula biliar,\nsem evidência de espessamento de paredes da vesícula e sem dilatação de vias biliares. A\ntomografia de abdome identificou necrose de extensão equivalente a 40% do tecido pancreático e\npresença de uma coleção líquida intrapancreática. Vem evoluindo estável, com leucocitose desde a\nadmissão. Encontra-se afebril, com Escala de Coma de Glasgow 15, sem drogas vasoativas e em\nventilação espontânea. Sobre a prescrição de antibiótico nesse caso, ela deve ser:","options":{"A":"profilática, baseada na extensão da necrose.","B":"empírica, baseada na presença de leucocitose.","C":"terapêutica, baseada na etiologia da pancreatite.","D":"direcionada, baseada na bacterioscopia da punção da necrose."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-126977","number":"126977","sourceNumber":"126977","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Homem de 68 anos, encaminhado da zona rural, com história de dor abdominal de\ninício súbito há 2 dias, com piora importante\nnas últimas 6 horas e o aparecimento de náuseas e\nvômitos. Exame físico: consciente, orientado, hipotenso, desidratado, taquicárdico com ritmo\nirregular, taquipneico, abdome bastante distendido porém flácido, apesar de referir dor intensa à\npalpação profunda, RHA ausente. Toque retal: ausência de fezes na ampola com raios de sangue\nna luva. Exames laboratoriais: leucócitos = 18.000/mm³; amilase = 300 UI; lipase = 100 UI; lactato =\n5 mmol/L; pH = 7,1. Qual o diagnóstico mais provável e sua conduta?","options":{"A":"Pancreatite aguda, solicitar TC de abdome para confirmar o diagnóstico e avaliar as\ncomplicações.","B":"Isquemia mesentérica, encaminhar para o centro cirúrgico para cirurgia de emergência devido à\ngravidade do quadro.","C":"Pancreatite aguda, estabilizar o paciente corrigindo a acidose e encaminhá-lo para o centro\ncirúrgico para cirurgia de urgência.","D":"Isquemia mesentérica, estabilizar o paciente corrigindo a acidose e encaminhá-lo para o centro\ncirúrgico para cirurgia de urgência."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-127004","number":"127004","sourceNumber":"127004","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente com 47 anos, masculino, foi diagnosticado clinicamente com diverticulite\naguda em uma emergência, há 10 dias, e\niniciou tratamento com restrição alimentar e antibióticos\norais, ambulatorialmente. Há uma semana, teve piora do quadro, apresentando 2 picos febris de\n38,7°C e intensificação da dor em fossa ilíaca esquerda, sendo hospitalizado e iniciada\nantibioticoterapia parenteral. Na admissão, fez Tomografia Computadorizada (TC) do abdome que\nevidenciou abscesso perimesocólico com 5 cm, na topografia do sigmoide, sem líquido livre na\ncavidade ou evidências de pneumoperitônio. Hoje é mantido em internação hospitalar, com 1 pico\nfebril diário, dificuldade de realimentação oral e dor profunda em FIE sem sinais de aumento da dor\nà descompressão brusca. Na TC de controle, há persistência de abscesso com diâmetro de 4 cm.\nCom base nas informações acima, qual das alternativas abaixo representa a conduta mais indicada\nno caso?","options":{"A":"Indicar drenagem laparoscópica do abscesso.","B":"Indicar drenagem percutânea guiada por TC.","C":"Manter a conduta atual e repetir a TC com 14 dias.","D":"Manter a conduta clínica e trocar o esquema antibiótico."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-81251","number":"81251","sourceNumber":"81251","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente masculino, 51 anos, internado em unidade de terapia intensiva há 25 dias por\npancreatite aguda severa alcoólica. Há 05 dias, evoluía afebril e com diminuição da PCR (Proteína\nC-Reativa), quando voltou a fazer pico febril de 39°C, com piora relevante da leucocitose e da PCR,\nalém do aumento do lactato sérico para 5,5 mmol/L (normal < 2,5 mmol/L). Foi, portanto, solicitada\nrealização de nova tomografia computadorizada de abdome. Não foi possível realização de punção\nguiada de tecido pancreático. De acordo com o resultado tomodensitométrico de Balthazar, a\nmelhor conduta para esse paciente é:","options":{"A":"Se Balthazar B: indicar antibioticoterapia como conduta isolada.","B":"Se Balthazar C: indicar antibioticoterapia com drenagem percutânea radiointervencionista.","C":"Se Balthazar D: indicar antibioticoterapia e desbridamento com lavagem contínua.","D":"Se Balthazar E: indicar antibioticoterapia com drenagem transpapilar endoscópica por CPRE\n(Colangiopancreatografia Retrógrada Endoscópica)."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-65761","number":"65761","sourceNumber":"65761","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Homem de 55 anos, portador de fibrilação atrial crônica em uso de varfarina (suspenso\nhá 30 dias), relata dor abdominal intensa,\ndistensão e náuseas, iniciadas há 24 horas. Ao exame:\nfáscies de dor, abdome bastante distendido, doloroso difusamente, sem defesa peritoneal, RHA (-).\nFC: pulso irregular, hipotenso. Exames: leucograma: 35.000 leuc./mm³ com desvio para\nmetamielócitos e ausência de eosinófilos na contagem. Granulações tóxicas estavam presentes em\n30% dos neutrófilos; acidose metabólica à gasometria. Qual a melhor conduta?","options":{"A":"Solicitação de parecer do cirurgião vascular.","B":"Encaminhamento para laparotomia exploradora.","C":"Monitorização e tratamento da arritmia cardíaca em UTI.","D":"Estabilização hemodinâmica e administração de antibióticos de largo espectro.","E":"Dosagem de enzimas pancreáticas, dieta zero, sondagem nasogástrica e nutrição parenteral\ntotal."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-51146","number":"51146","sourceNumber":"51146","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Mulher de 35 anos é admitida na emergência com dor abdominal em cólicas de forte\nintensidade na região periumbilical, náuseas, vômitos e diminuição da eliminação de flatos, com\nparada da eliminação de fezes há dois dias. Encontra-se grávida, na terceira gestação, e não se\nrecorda da data da última menstruação. Ao exame físico, apresenta leve taquicardia, distensão\nabdominal difusa e ruídos hidroaéreos diminuídos com timbre metálico. Quanto à propedêutica,\nutilizando-se exames de imagem para este caso, pode se afirmar que:","options":{"A":"O exame ultrassonográfico pode ser particularmente útil.","B":"A tomografia de abdome está indicada no diagnóstico precoce de sofrimento vascular.","C":"As radiografias de tórax e de abdome em decúbito dorsal têm contraindicação absoluta.","D":"A Tomografia Computadorizada de abdome é preferível ao raio X de abdome devido à incerteza\nna história ginecológica da paciente."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-51149","number":"51149","sourceNumber":"51149","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente de 82 anos procurou a emergência com queixa de dor abdominal em\ncólicas na região suprapúbica, eliminação\nde fezes sanguinolentas e febre baixa há um dia. O raio\nX simples de abdome evidenciou imagens do tipo ?thumbprinting? (impressões digitais). Uma\nretossigmoidoscopia flexível mostrou área de inflamação localizada na transição retossigmoidea,\ncom mucosa de aspecto friável e hemorrágica. O paciente foi internado e submetido a tratamento\ncom antibióticos de amplo espectro e a jejum para observar a evolução do quadro. Qual o\ndiagnóstico mais provável deste paciente?","options":{"A":"Retocolite ulcerativa inespecífica.","B":"Colite pseudomembranosa.","C":"Colite isquêmica.","D":"Colite colagenosa."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-51155","number":"51155","sourceNumber":"51155","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Homem apresenta episódio de forte dor abdominal epigástrica de caráter contínuo e\nirradiação para a região lombar. Apresenta vômitos copiosos e distensão abdominal. Refere ter tido\nalimentação copiosa na véspera e tomado bebidas alcoólicas. Ultrassonografia: Vesícula biliar\ndistendida, paredes finas, com lama biliar e colédoco com 0,9 cm de largura. Exames: Glicemia:\n270 mg/dL; LDH: 350 U/L; Lipase: 400 U/L; gama-GT: 160 U/L; Fosfatase alcalina: 330 U/L;\nLeucócitos: 15.000; Bilirrubina direta: 4 mg/dL; Bilirrubina indireta: 2 mg/dL. Qual o diagnóstico\nmais\nprovável?","options":{"A":"Colecistite aguda.","B":"Pancreatite aguda.","C":"Colecistite alitiásica.","D":"Colangite supurativa."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-51202","number":"51202","sourceNumber":"51202","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente de 35 anos, com Síndrome de Imunodeficiência Adquirida, em uso de\ndidanosina, previamente assintomático, queixa-se\nde dor epigástrica contínua e intensa, irradiada\npara o dorso, com vômitos, há 12 horas. Admissão: TGP 78 UI/L, TGO 82 UI/L e lipase sérica 1.580\nUI/L. Após 24h: apresentou dispneia, hipotensão, oligúria e os seguintes achados: temperatura\naxilar 38,5° C, frequência cardíaca 100/min, PaCO2 arterial 26 mmHg, leucócitos 25.000/mm³. Que\nfenômeno fisiopatológico agudo predomina neste cenário clínico dentre as opções abaixo?","options":{"A":"Inflamação.","B":"Apoptose.","C":"Imunossupressão.","D":"Infecção bacteriana."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-141589","number":"141589","sourceNumber":"141589","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Com relação a Apendicite Aguda, é correto afirmar:","options":{"A":"Trata-se da emergência cirúrgica abdominal mais comum, afetando principalmente\nindivíduos na segunda e terceira décadas de\nvida, sendo no entanto bastante comum em\nidosos, entre os quais tem menor mortalidade do que na população geral","B":"Quando o processo evolui rapidamente, os órgãos adjacentes como íleo terminal, ceco e\nomento podem bloquear a área apendicular, formando um abscesso localizado, enquanto a\nprogressão lenta da deterioração vascular, pode causar perfuração com acesso livre à cavidade\nperitoneal.","C":"A sequência clássica de sintomas com dor inicialmente periumbilical, que posteriormente\nmigra para o quadrante inferior direito do\nabdômen associados a anorexia, é encontrada em\nmenos da metade dos pacientes.","D":"Tratamento conservador com uso apenas de antibióticos em casos em que não há perfuração\nleva a resolução do quadro em menos de 50% dos\ncasos, associado a altas taxas de recidivas."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-141620","number":"141620","sourceNumber":"141620","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente masculino, 26 anos, queixa-se de dor abdominal e vômitos há 2 dias.\nRefere episódio único de diarreia, nega febre.\nProcura assistência médica, sendo admitido\ncom quadro de dor abdominal à palpação em andar superior do abdome, desidratação\ncutâneo-mucosa, taquidispnéia associada a dor pleurítica a esquerda e taquicardia. Sobre o\ndiagnóstico diferencial do abdome agudo, é correto afirmar:","options":{"A":"No diagnóstico diferencial, devem ser considerados os seguintes distúrbios: víscera perfurada,\ncolecistite aguda, obstrução intestinal aguda, oclusão vascular mesentérica, cólica renal\nassociada a pielonefrite, infarto do miocárdio, aneurisma dissecante de aorta, distúrbios do\ntecido conectivo e vasculite, pneumonia e cetoacidose diabética.","B":"Diante de quadro clínico altamente sugestivo e enzimas pancreáticas elevadas mais do que 3x,\na TC de abdome deve ser realizada o mais\nprecocemente possível para evidenciar necrose\npancreática associada, o que pode ser decisivo para decisão de abordagem cirúrgica, que também\ndeve ser precoce.","C":"A clínica de cetoacidose diabética pode ser confundida com pancreatite, especialmente\nporque existe concomitante elevação de lipase, mas\nnão de amilase associado ao quadro de\nceatoacidose diabética.","D":"Os critérios de gravidade APACHE II e Ranson são muito úteis na prática clinica, devido\nsimplicidade de aplicação e alto valor preditivo positivo e negativos para a pancreatite grave."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-37428","number":"37428","sourceNumber":"37428","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação ao melhor manejo de pacientes com pancreatite, assinale a alternativa\ncorreta:","options":{"A":"Dosagem sérica de amilase permanece elevada por mais tempo em relação à lipase e tem maior\nespecificidade para o diagnóstico.","B":"Idade acima de 40 anos, cálcio sérico > 10 mEq/L e ureia acima de 60 mg/dl são relacionados\nao pior prognóstico quando avaliado no momento\nda admissão dos pacientes acometidos.","C":"Imipenem é o antibiótico de escolha em pacientes com necrose infectada.","D":"Abcessos pancreáticos podem complicar pancreatites agudas surgindo geralmente nos\nprimeiros dias após início do quadro.","E":"Hipertrigliceridemia e consumo de álcool são as causas mais frequentes de pancreatites agudas."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-37375","number":"37375","sourceNumber":"37375","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"FCD, 54 anos, masculino foi admitido na emergência com quadro de dor abdominal de\ninício gradual e de padrão inespecífico nas regiões mesogástrica e fossa ilíaca esquerda há cerca\nde 24 horas com piora da intensidade nas últimas 6 horas. Achados de exame físico: Temp =\n37,7°C, FC = 108 bpm e com descompressão brusca positiva na fossa ilíaca esquerda. Com\nrelação à investigação complementar desse paciente, qual dos seguintes exames está mais\nindicado para elucidação diagnóstica desse paciente?","options":{"A":"Enema opaco.","B":"Colonoscopia.","C":"Retossigmoidoscopia flexível.","D":"Retossigmoidoscopia rígida.","E":"Tomografia computadorizada do abdome."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-37387","number":"37387","sourceNumber":"37387","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"MCAG, feminino, 43 anos, portadora de colelitíase sintomática, estava aguardando\ncirurgia quando apresentou episódio de dor de\nforte intensidade, em faixa, com náuseas e vômitos.\nFoi admitida em uma emergência e feita dosagem de amilase, se constatou um quadro de\npancreatite aguda biliar. Foi então internada e o tratamento clínico instituído. Após 1 semana de\ntratamento estava assintomática e com condições clínicas de alta para se programar uma\ncolecistectomia. Assinale a alternativa que melhor corresponde à época que idealmente deveria ser\nfeita a cirurgia.","options":{"A":"Na mesma internação.","B":"Oito semanas após a crise.","C":"Após normalização dos níveis de amilase e lipase.","D":"Após a realização de colangiopancreatografia retrógrada endoscópica.","E":"Após realização de tomografia abdominal confirmando resolução do processo de pancreatite."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-25286","number":"25286","sourceNumber":"25286","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Leia o texto abaixo e o complemente com a resposta correta. Embora a transição entre\no jejuno e o íleo , mudanças\ngraduais podem ser vistas nas características do\nintestino, na vascularização, e até mesmo na\n\nlocalização geral. O diâmetro do jejuno é maior porque o volume do quimo não se reduziu pela\nabsorção de líquidos. A parede jejunal também é mais espessa por serem as pregas circulares\nmais altas e mais numerosas. Agregados de tecido linfoide no íleo.","options":{"A":"não seja nítida, no suporte mesenterial, são mais numerosos.","B":"seja nítida, na drenagem linfática, não são mais numerosos.","C":"não seja nítida, no suporte pelo peritônio, não são mais numerosos.","D":"seja nítida, na drenagem venosa, são mais numerosos.","E":"não seja nítida, no suporte devido à prega mesenterial, são mais numerosos."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-25287","number":"25287","sourceNumber":"25287","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Leia o texto abaixo e o complemente com a resposta correta. O suprimento sanguíneo\npara o duodeno provém . O\njejuno e o íleo são irrigados\n\n. As artérias jejunais formam várias arcadas longas que emitem\nartérias terminais bastante longas (artérias retas); as artérias ileais formam numerosas arcadas\npequenas com artérias terminais pequenas.","options":{"A":"do tronco celíaco, pela artéria mesentérica superior.","B":"do tronco celíaco, pela artéria mesentérica superior e tronco celíaco.","C":"da artéria mesentérica superior, pelo tronco celíaco.","D":"do tronco celíaco e da artéria mesentérica superior, pela artéria mesentérica superior.","E":"da artéria mesentérica inferior, pelo tronco celíaco."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-25291","number":"25291","sourceNumber":"25291","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Leia o texto abaixo e o complemente com a resposta correta. O é\nretroperitoneal, em grande parte. As porções\njejunal e ileal do intestino delgado são sustentadas\npelo e são, portanto, móveis. Contudo, o jejuno tende a se colocar nas regiões umbilical\ne lateral, esquerda, enquanto o íleo tende a ocupar o (a) . O mesentério ileal\né mais espesso por que tem maior concentração de gordura entre os vasos do que o jejuno.","options":{"A":"duodeno, mesentério, hipogástrio inferior.","B":"jejuno, peritônio, pelve menor","C":"duodeno, peritônio, hipogástrio","D":"jejuno, mesentério, pelve superior.","E":"duodeno, mesentério, hipogástrio e a pelve menor."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-24325","number":"24325","sourceNumber":"24325","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"São medidas empregadas no tratamento clínico da pancreatite aguda leve, EXCETO:","options":{"A":"Antibioticoprofilaxia.","B":"Reposição de fluidos e eletrólitos.","C":"Analgesia.","D":"Dieta zero."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-22826","number":"22826","sourceNumber":"22826","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente de 43 anos chega à emergência com quadro de vômitos e dor em abdome\nsuperior há duas horas. A avaliação\nlaboratorial demonstra: amilase 2000 U/L (limite superior da\nnormalidade [LSN]: 150 U/L), TGO 48 (LSN: 40 U/L) e TGP 100U/L (LSN: 40 U/L). Negava ingestão\nalcoólica. Paciente evoluiu com piora do quadro clínico e foi realizada tomografia que evidenciou\nnecrose pancreática extensa. Diante desse caso clínico, assinale a opção correta.","options":{"A":"A tomografia computadorizada é útil no diagnóstico, no entanto não fornece dados prognósticos","B":"A grande elevação de amilase correlaciona-se com a gravidade do quadro","C":"Apesar da necrose pancreática extensa, a manipulação cirúrgica do pâncreas somente deverá\nser considerada em caso de evidência de infecção\nda lesão","D":"Apesar da negativa do etilismo, o padrão de enzimas hepáticas sugere ingestão alcoólica","E":"A tomografia computadorizada deveria ter sido realizada no início do quadro para avaliação de\nnecrose"},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-22961","number":"22961","sourceNumber":"22961","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Os divertículos são herniações da mucosa na parede muscular dos cólons, ocorrendo\nmais comumente no sigmoide. A diverticulite ou\nperidiverticulite é uma complicação infecciosa da\ndoença diverticular, podendo ser conduzida de uma forma conservadora com antibióticos. Em\nalgumas situações, entretanto, pode-se considerar a cirurgia como tratamento de eleição. São\ncandidatos à cirurgia na doença diverticular, EXCETO:","options":{"A":"idade < 45 anos","B":"boa resposta ao tratamento clínico na primeira crise","C":"perfuração intertinal","D":"fístula colônica","E":"abscesso periapendicular"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-27729","number":"27729","sourceNumber":"27729","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Qual dos fatores abaixo está mais comumente associado à pancreatite aguda?","options":{"A":"Trauma.","B":"Hiperlipidemia.","C":"Hipercalcemia.","D":"Fibrose cística.","E":"Cálculo biliar."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-9044","number":"9044","sourceNumber":"9044","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Cerca de 80 a 90 % das pancreatites agudas são autolimitadas. No entanto, 10%\nevoluem com extrema gravidade. Os critérios\nde Ranson são os mais empregados para avaliar\ngravidade e pacientes com escore igual ou maior que 3, apresentam maior mortalidade. São sinais\nde gravidade na pancreatite aguda, EXCETO:","options":{"A":"Sinal de Grey Turner","B":"Sinal de Cullen","C":"Hipocalcemia","D":"Amilase sérica acima de 2000 unidades"},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-9048","number":"9048","sourceNumber":"9048","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Com relação ao diagnóstico e tratamento da apendicite aguda, pode-se afirmar,\nEXCETO:","options":{"A":"A intensificação da dor abdominal e o aparecimento de febre alta (39° e 40°) sugerem\nperfuração do apêndice.","B":"O sinal do psoas está presente mais comumente nos casos de apendicite retrocecal","C":"A TC de abdômen é bem mais específica e sensível do que a ultrassonografia abdominal no\ndiagnóstico da apendicite aguda.","D":"O tratamento clínico é muito pouco eficaz e deve ser indicado somente na impossibilidade de\ntratamento cirúrgico."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-9016","number":"9016","sourceNumber":"9016","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação às doenças inflamatórias intestinais, é CORRETO afirmar:","options":{"A":"A colite ulcerativa é uma doença de acometimento transmural do intestino, cursando, portanto,\ncom manifestações de obstrução intestinal.","B":"O acometimento da mucosa na Doença de Crohn é contínuo, enquanto na colite ulcerativa há\náreas de mucosa doente intercaladas com mucosa normal.","C":"O achado de reto com mucosa normal à colonoscopia, praticamente, exclui do diagnóstico de\ncolite ulcerativa.","D":"A evolução para carcinoma colorretal é mais comum na Doença de Crohn que na colite\nulcerativa"},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-9067","number":"9067","sourceNumber":"9067","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Edson, 11 anos, chegou à emergência do IJF com suspeita de abdome agudo. Em uma\ndas opções, o hemograma pode fornecer\nevidências do quadro. Por favor, marque-a:","options":{"A":"Aumento do número de linfócitos atípicos.","B":"Presença de esferócitos","C":"Leucopenia","D":"Ausência de eosinófilos"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-8873","number":"8873","sourceNumber":"8873","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Assinale a opção INCORRETA sobre um paciente com dor abdominal mas com\nachados duvidosos para abdome agudo.","options":{"A":"Ultrassonografia apresenta boa sensibilidade em identificar um apêndice distendido ou\nespessado.","B":"Pode ser feito laparoscopia diagnóstica, especialmente em mulher e se for apendicite continuar o\nprocedimento.","C":"Tomografia computadorizada pode detectar muitas doenças incluídas no diagnóstico diferencial\ncomo trombose mesentérica, pancreatite.","D":"Exames radiográficos podem revelar pneumoperitônio ou sinais evidentes de perfuração\ngastrointestinal.","E":"Se paciente for obeso e a tomografia computadorizada for normal, mesmo assim deve ser\nsubmetido à laparoscopia ou laparotomia."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-17830","number":"17830","sourceNumber":"17830","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Com relação ao câncer gástrico, é correto afirmar.","options":{"A":"Nas áreas de alta incidência predominam os tumores do tipo intestinal ou bem diferenciados","B":"Os tumores do tipo intestinal têm relação genética e os do tipo difuso estão associados ao\nHelicobacter pylori","C":"A linite plástica é a disseminação submucosa do tumor e é classificada como Borrman III","D":"As úlceras gástricas são mais frequentemente neoplásicas quando localizadas na pequena\ncurvatura, sendo pépticas quando se desenvolvem na grande curvatura","E":"A classificação de Borrman é histológica, enquanto a classificação de Lauren refere-se a\nparâmetros macroscópicos do tumor."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-17838","number":"17838","sourceNumber":"17838","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Qual condição abaixo representa histologicamente uma metaplasia?","options":{"A":"Queloide","B":"Tecido de granulação","C":"Injúria térmica de segundo grau","D":"Esôfago de Barret","E":"Cicatriz hipertrófica"},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-17839","number":"17839","sourceNumber":"17839","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Sobre as hemorragias digestivas, é correto afirmar:","options":{"A":"A maioria é hemorragia digestiva alta","B":"A primeira abordagem é identificar o sítio do sangramento","C":"Hemorragia baixa é aquela após a válvula íleo-cecal","D":"Varizes de esôfago são as principais causas de sangramento alto","E":"Hemorroidas são a principal causa de sangramento baixo, abundante"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-322133","number":"322133","sourceNumber":"322133","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Levado por um vizinho, um paciente de 68 anos, previamente lúcido, foi admitido em\num hospital com rebaixamento do nível de\nconsciência. Durante a investigação, foi sugerido\nprovável diagnóstico de sepse grave de foco abdominal devido a uma diverticulite aguda perfurada.\nO paciente permaneceu torporoso e, após a equipe tentar entrar em contato com a família, sem\nsucesso, o paciente foi encaminhado à cirurgia. O médico cirurgião indicou uma\nretossigmoidectomia à Hartmann ? com colostomia terminal. Qual é a melhor conduta diante dessa\nsituação?","options":{"A":"Proceder com a cirurgia, já que se trata de cirurgia de urgência, com risco ao paciente,\nnecessitando que seja feita uma colostomia para\nmelhor tratamento dele, independentemente da\nopinião da família.","B":"Aguardar a chegada da família para iniciar a cirurgia, já que eles devem decidir sobre a\nconfecção ou não de um estoma.","C":"Proceder com a cirurgia sem a confecção de estoma, pelo risco de não haver aceite da família\nquanto a esse procedimento, mesmo que seja a melhor estratégia para o paciente.","D":"Orientar o acompanhante sobre o quadro e solicitar que ele decida sobre a confecção ou não do\nestoma para o paciente, já que está acompanhando o paciente.","E":"Proceder com a cirurgia e realizar a lavagem e drenagem da cavidade para realizar,\nposteriormente, uma nova abordagem cirúrgica, devido à ausência da família."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-365631","number":"365631","sourceNumber":"365631","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente de 7 anos de idade foi levado à unidade de pronto atendimento com\nqueixa de dor abdominal intermitente há 48\nhoras, localizada no quadrante inferior direito. Não\napresentou febre, porém estava mantendo a temperatura de cerca de 37,5°C nas últimas 24 horas.\nDurante a anamnese, a genitora informou que, há 10 dias, o enfermo havia apresentado quadro de\ngastroenterite aguda por 72 horas (doença autolimitada). Ao exame físico, o sinal de Blumberg era\nnegativo, mas observava-se expressão de dor abdominal à palpação profunda de todo o quadrante\ninferior à direita. Foram realizados exames laboratoriais e ultrassonografia de abdome, a qual\ndescartou a possibilidade de apendicite aguda e mostrava a presença de linfonodos aumentados\nde volume nessa topografia. Nesse caso clínico, a principal hipótese diagnóstica é","options":{"A":"diverticulo de Meckel.","B":"linfadenite mesentérica.","C":"pancolite.","D":"colecistite aguda."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-365630","number":"365630","sourceNumber":"365630","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente de 7 anos de idade foi levado à unidade de pronto atendimento com\nqueixa de dor abdominal intermitente há 48\nhoras, localizada no quadrante inferior direito. Não\napresentou febre, porém estava mantendo a temperatura de cerca de 37,5°C nas últimas 24 horas.\nDurante a anamnese, a genitora informou que, há 10 dias, o enfermo havia apresentado quadro de\ngastroenterite aguda por 72 horas (doença autolimitada). Ao exame físico, o sinal de Blumberg era\nnegativo, mas observava-se expressão de dor abdominal à palpação profunda de todo o quadrante\ninferior à direita. Foram realizados exames laboratoriais e ultrassonografia de abdome, a qual\ndescartou a possibilidade de apendicite aguda e mostrava a presença de linfonodos aumentados\nde volume nessa topografia. Considerando as informações do caso citado, assinale a alternativa\nque indica a melhor conduta para esse paciente.","options":{"A":"Internação + antibioticoterapia + analgesia.","B":"Internação + analgesia.","C":"Alta hospitalar com analgesia otimizada.","D":"Alta hospitalar com antibiótico + analgesia otimizada."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-365629","number":"365629","sourceNumber":"365629","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente de 64 anos de idade procurou unidade de pronto atendimento com\nqueixa de dor abdominal de forte\nintensidade, localizada na fossa ilíaca à esquerda, há quatro dias.\nInformou ter apresentado febre (38,5 °C) na manhã desse dia. Associa-se ao quadro náusea e\nhiporexia. A paciente recebeu as medidas iniciais, realizou exames laboratoriais e tomografia\ncomputadorizada (TC) de abdome com contraste. A TC mostrou quadro de diverticulite aguda\nlocalizada no cólon sigmoide com formação de abscesso de aproximadamente 2,5 cm\nperidiverticular. Não foram evidenciadas imagens sugestivas de pneumoperitônio. Tendo em vista\nas informações apresentadas, qual é a melhor conduta para essa paciente?","options":{"A":"Internação hospitalar + antibioticoterapia endovenosa + suporte clínico.","B":"Internação hospitalar + antibioticoterapia endovenosa + drenagem percutânea do abscesso +\nsuporte clínico.","C":"Alta hospitalar com antibioticoterapia via oral.","D":"Internação hospitalar + drenagem percutânea + suporte clínico."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-365628","number":"365628","sourceNumber":"365628","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente de 64 anos de idade procurou unidade de pronto atendimento com\nqueixa de dor abdominal de forte\nintensidade, localizada na fossa ilíaca à esquerda, há quatro dias.\nInformou ter apresentado febre (38,5 °C) na manhã desse dia. Associa-se ao quadro náusea e\nhiporexia. A paciente recebeu as medidas iniciais, realizou exames laboratoriais e tomografia\ncomputadorizada (TC) de abdome com contraste. A TC mostrou quadro de diverticulite aguda\nlocalizada no cólon sigmoide com formação de abscesso de aproximadamente 2,5 cm\nperidiverticular. Não foram evidenciadas imagens sugestivas de pneumoperitônio. Assinale a\nmelhor alternativa que indica o melhor esquema de tratamento com antibiótico endovenoso para a\npaciente do caso clínico mencionado.","options":{"A":"Ciprofloxacino.","B":"Cefepime + metronidazol.","C":"Ceftarolima + vancomicina.","D":"Ceftriaxona + metronidazol."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-365618","number":"365618","sourceNumber":"365618","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente de 58 anos de idade deu entrada no pronto-socorro com queixa de dor\nabdominal intensa, localizada no quadrante superior direito, com irradiação para o dorso. O\npaciente relatou o início súbito da dor há aproximadamente 12 horas, associada a náuseas e\nvômitos frequentes. O histórico médico do paciente revela recente colelitíase diagnosticada. Na\nadmissão, os sinais vitais apresentam PA = 130 mmHg x 80 mmHg, FC = 110 bpm, FR = 18 irpm,\ntemperatura = 38,5 °C. Ao exame físico, observaram-se abdome com sensibilidade à palpação\nprofunda no quadrante superior direito, sinal de Murphy positivo. Realizou exames laboratoriais com\nresultado de amilase sérica e lipase elevadas. Os exames de imagem demonstraram, na\nultrassonografia abdominal, evidência de colelitíase e dilatação da via biliar comum. Na tomografia\ncomputadorizada abdominal, houve a confirmação de pancreatite aguda biliar. Com base nesse\ncaso clínico, assinale a alternativa que indica o próximo passo no manejo desse paciente com\npancreatite aguda biliar confirmada.","options":{"A":"Administração de antibióticos de amplo espectro.","B":"Colangiopancreatografia retrógrada endoscópica (CPRE)","C":"Início imediato de dieta enteral.","D":"Cirurgia de colecistectomia laparoscópica emergencial."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-365614","number":"365614","sourceNumber":"365614","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente de 60 anos de idade procurou o pronto-socorro com dor abdominal\nintensa de início súbito, predominantemente\nno quadrante superior esquerdo. Ela relata náuseas,\nvômitos e ausência de evacuações. Ao exame físico, revela sensibilidade à palpação abdominal e\nsinais de peritonite localizada. Na admissão, os sinais vitais apresentavam PA = 90 mmHg x 60\nmmHg, FC = 120 bpm, FR = 28 irpm e temperatura = 37,8 °C. Ela realizou exames\ncomplementares que demonstraram: leucograma com leucocitose significativa, amilase sérica\ndentro da faixa de normalidade e lactato sérico elevado. Nesse caso clínico, o diagnóstico mais\nprovável é","options":{"A":"infarto mesentérico.","B":"diverticulite perfurada.","C":"apendicite aguda.","D":"pancreatite aguda grave."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-349751","number":"349751","sourceNumber":"349751","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente de 45 anos teve uma pancreatite aguda e, após 6 semanas, passou a\nnotar dor abdominal persistente, saciedade\nprecoce, náusea e perda de peso. Ao procurar o\nserviço médico, foram verificados níveis elevados das enzimas pancreáticas e uma lesão cística de\naproximadamente 8 cm em cauda do pâncreas, em contato com a parede gástrica. Qual é o\nprovável diagnóstico e a conduta mais adequada nesse caso?","options":{"A":"Trata-se provavelmente de necrose pancreática que deve ser tratada com antibióticos de amplo\nespectro como o meropenem.","B":"Trata-se provavelmente de um pseudocisto pancreático que deve ser tratado com antibióticos de\namplo espectro como o meropenem.","C":"Trata-se provavelmente de pseudocisto pancreático e pode-se tentar uma drenagem\nendoscópica transgástrica.","D":"Trata-se provavelmente de necrose pancreática que deve ser tratada de maneira expectante,\ncom indicação de intervenção cirúrgica se o paciente\napresentar febre.","E":"Trata-se provavelmente de pseudocisto pancreático que deve ser tratado com abordagem\ncirúrgica por laparotomia."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-349752","number":"349752","sourceNumber":"349752","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente gestante de 25 semanas apresenta dor em região de flanco direito há 1\ndia, associada a náuseas e vômitos. No hemograma, apresenta uma leucocitose de 11.500 (VR =\n10.000). Quanto a esse caso, é correto afirmar que","options":{"A":"se deve fazer uma ultrassonografia abdominal devido à suspeita de apendicite aguda e, caso\nnecessário, uma tomografia para melhor visualização do apêndice.","B":"há suspeita de apendicite aguda, devido à localização da dor (apêndice deslocado\ncefalicamente). Uma ultrassonografia de\nabdome pode visualizar o apêndice e ajudar a esclarecer o\ndiagnóstico.","C":"pode se tratar apenas de uma intercorrência da gestação, como dor do ligamento redondo. Para\nmelhor esclarecimento do caso, deve-se solicitar uma ressonância de abdome, já que a\nultrassonografia não é recomendada nessa idade gestacional.","D":"há grandes chances de ser uma apendicite aguda, já que a paciente tem dor em flanco direito\n(apêndice deslocado cefalicamente) e tem leucocitose, sinal de que há um processo inflamatório\nagudo vigente.","E":"se trata de uma provável colecistite, devido à topografia da dor associada à leucocitose, que\nfavorece processo inflamatório agudo."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-349767","number":"349767","sourceNumber":"349767","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Assinale a alternativa que apresenta 2 tipos de bactérias que estão entre as mais\nfrequentemente encontradas/isoladas na apendicite aguda perfurada.","options":{"A":"Acinetobacter baumannii e Klebsiella pneumoniae.","B":"Pseudomonas aeruginosa e Bacteroides coprosuis.","C":"Escherichia coli e Bacteroides fragilis.","D":"Campylobacter jejuni e Burkholderia cepacia.","E":"Acinetobacter baumannii e Escherichia coli."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-349761","number":"349761","sourceNumber":"349761","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente de 72 anos foi submetido a uma laparotomia exploradora por diverticulite\ncomplicada de cólon sigmoide, tendo sido realizada uma cirurgia com ressecção do sigmoide,\nfechamento do coto retal e confecção de colostomia terminal no cólon descendente. Esse tipo de\ncirurgia denomina-se","options":{"A":"cirurgia de Whipple.","B":"cirurgia de Hartmann.","C":"cirurgia de Murphy.","D":"cirurgia de Duhamel.","E":"cirurgia de Wilson."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-349696","number":"349696","sourceNumber":"349696","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma criança de dez anos de idade apresenta quadro de abdome agudo, após período\nde dois dias com febre, vômitos e importante\ndistensão do abdome. Assinale a alternativa que\napresenta uma das condutas corretas nesse caso.","options":{"A":"Devido à urgência, não comunicar a família e proceder à laparotomia exploradora.","B":"Explicar à criança a importância da tomografia abdominal e do raio x de tórax.","C":"Proceder à sondagem gástrica, explicando que não há risco de perfuração intestinal.","D":"Solicitar exames laboratoriais: hemograma, eletrólitos, glicemia, amilase, lipase, gasometria\narterial, explicando previamente à família sua\nconduta.","E":"Avisar à farmácia hospitalar a respeito da indicação de reposição volêmica com solução salina\nhipertônica, explicando para família sua indicação."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-322185","number":"322185","sourceNumber":"322185","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Na fase mais inicial da apendicite aguda, qual é a tríade sintomática mais característica\nentre as seguintes?","options":{"A":"Dor em fossa ilíaca direita, febre alta e prostração.","B":"Dor epigástrica intensa, febre moderada e vômitos.","C":"Dor abdominal difusa, febre alta e anorexia.","D":"Dor periumbilical, febre alta e vômitos.","E":"Dor periumbilical, febre moderada e anorexia."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-298842","number":"298842","sourceNumber":"298842","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente de 23 anos de idade foi encaminhado à emergência com história de dor\nabdominal que migrou para a fossa ilíaca direita há dois dias. Ele queixa-se de náuseas, vômitos e\ndificuldade para se alimentar, nega febre e 1 episódio de fezes amolecidas no período. Ao exame\nfísico, apresenta-se afebril, FC = 82 bpm, FR = 18 irpm e SatO2 = 98%. Ao exame abdominal,\napresenta dor à palpação de todo abdome e dor à descompressão brusca de fossa ilíaca direita. Os\nexames laboratoriais apresenta leucocitose, sem desvio. Acerca desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. A escala de Alvarado do paciente é de 8\npontos, o que traduz uma alta suspeição diagnóstica de apendicite aguda. Submeter o paciente à\napendicectomia sem a necessidade de exames de imagem seria uma condução correta do caso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-298843","number":"298843","sourceNumber":"298843","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente de 23 anos de idade foi encaminhado à emergência com história de dor\nabdominal que migrou para a fossa ilíaca direita há dois dias. Ele queixa-se de náuseas, vômitos e\ndificuldade para se alimentar, nega febre e 1 episódio de fezes amolecidas no período. Ao exame\nfísico, apresenta-se afebril, FC = 82 bpm, FR = 18 irpm e SatO2 = 98%. Ao exame abdominal,\napresenta dor à palpação de todo abdome e dor à descompressão brusca de fossa ilíaca direita. Os\nexames laboratoriais apresenta leucocitose, sem desvio. Acerca desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. O sinal que descreve a dor no quadrante\ninferior direito à palpação do quadrante inferior esquerdo é chamado sinal do obturador.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-298844","number":"298844","sourceNumber":"298844","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente de 23 anos de idade foi encaminhado à emergência com história de dor\nabdominal que migrou para a fossa ilíaca direita há dois dias. Ele queixa-se de náuseas, vômitos e\ndificuldade para se alimentar, nega febre e 1 episódio de fezes amolecidas no período. Ao exame\nfísico, apresenta-se afebril, FC = 82 bpm, FR = 18 irpm e SatO2 = 98%. Ao exame abdominal,\napresenta dor à palpação de todo abdome e dor à descompressão brusca de fossa ilíaca direita. Os\nexames laboratoriais apresenta leucocitose, sem desvio. Acerca desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. Em caso de apendicite de fase inicial\n(fase I ou II), indica-se apenas antibiótico para profilaxia, não havendo obrigatoriedade da\nantibioticoterapia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-298845","number":"298845","sourceNumber":"298845","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente de 23 anos de idade foi encaminhado à emergência com história de dor\nabdominal que migrou para a fossa ilíaca direita há dois dias. Ele queixa-se de náuseas, vômitos e\ndificuldade para se alimentar, nega febre e 1 episódio de fezes amolecidas no período. Ao exame\nfísico, apresenta-se afebril, FC = 82 bpm, FR = 18 irpm e SatO2 = 98%. Ao exame abdominal,\napresenta dor à palpação de todo abdome e dor à descompressão brusca de fossa ilíaca direita. Os\nexames laboratoriais apresenta leucocitose, sem desvio. Acerca desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. Em pacientes com apendicite não\nperfurada aguda, a coleta de cultura transoperatória é obrigatória, uma vez que é positiva na\nmaioria dos casos e permite guiar o uso de antibióticos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-298846","number":"298846","sourceNumber":"298846","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente de 23 anos de idade foi encaminhado à emergência com história de dor\nabdominal que migrou para a fossa ilíaca direita há dois dias. Ele queixa-se de náuseas, vômitos e\ndificuldade para se alimentar, nega febre e 1 episódio de fezes amolecidas no período. Ao exame\nfísico, apresenta-se afebril, FC = 82 bpm, FR = 18 irpm e SatO2 = 98%. Ao exame abdominal,\napresenta dor à palpação de todo abdome e dor à descompressão brusca de fossa ilíaca direita. Os\nexames laboratoriais apresenta leucocitose, sem desvio. Acerca desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. Tumores carcinoides e mucinosos são os\ntumores mais comuns do apêndice e devem ser tratados com apendicectomia ou colectomia direita,\na depender do caso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-305284","number":"305284","sourceNumber":"305284","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente com dor abdominal é admitido no pronto atendimento e é encaminhado\npara avaliação médica. Assinale a alternativa\ncorreta quanto ao exame desse paciente.","options":{"A":"Dor no ombro esquerdo quando em decúbito dorsal após pressão colocada no abdome superior\nesquerdo é denominada sinal de Camett.","B":"Pacientes com irritação peritoneal tipicamente mudam continuamente de posição no leito\nenquanto tentam achar uma posição que reduza seu desconforto.","C":"O médico deve se posicionar à esquerda do paciente e iniciar o exame físico pela palpação do\nabdome.","D":"O quadro de íleo paralítico caracteriza-se por ruídos abdominais \"\"metálicos\"\" em tom alto, que\ntendem a ocorrer em salvas e estão associados à dor e distensão.","E":"A percussão firme da crista ilíaca ou do flanco com uma perna estendida pode ajudar a\nidentificar casos de peritonite."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-274350","number":"274350","sourceNumber":"274350","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente jovem, com hiporexia, vômitos e dor súbita de grande intensidade em região\nde fossa ilíaca direita há 24 horas.\nApresenta, ao exame físico, dor em fossa ilíaca direita à\ncompressão do abdome inferior esquerdo. Assinale a alternativa que corresponde ao nome desse\nsinal no exame físico e ao provável diagnóstico do paciente.","options":{"A":"Sinal de Blumberg ? apendicite aguda.","B":"Sinal de Grey Turner ? pancreatite aguda.","C":"Sinal de Rovsing ? apendicite aguda.","D":"Sinal de Murphy ? colecistite aguda.","E":"Sinal de McBurney ? apendicite aguda."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-284325","number":"284325","sourceNumber":"284325","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente de 32 anos de idade, sem antecedentes mórbidos, procurou o\npronto-socorro com queixa de dor e desconforto abdominal iniciados há quatro dias,\nacompanhados de febre e parada de eliminação de fezes. Ao exame, encontra-se em regular\nestado geral, desidratada ++/4+, com pulso de 108 bpm, com PA de 120 x 70 mmHg e com\n\nabdome pouco distendido, doloroso em andar inferior de abdome, sem sinais de irritação peritoneal.\nCom base nesse caso hipotético, julgue o\nitem a seguir. Trata-se de abdome agudo, sendo\nnecessária uma intervenção clínica ou cirúrgica para sua resolução.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-284326","number":"284326","sourceNumber":"284326","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente de 32 anos de idade, sem antecedentes mórbidos, procurou o\npronto-socorro com queixa de dor e desconforto abdominal iniciados há quatro dias,\nacompanhados de febre e parada de eliminação de fezes. Ao exame, encontra-se em regular\nestado geral, desidratada ++/4+, com pulso de 108 bpm, com PA de 120 x 70 mmHg e com\n\nabdome pouco distendido, doloroso em andar inferior de abdome, sem sinais de irritação peritoneal.\nCom base nesse caso hipotético, julgue o\nitem a seguir. É possível descartar o diagnóstico de\napendicite aguda, devido à ausência de sinais de irritação peritoneal e de dor não localizada em\nfossa ilíaca direita.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-284329","number":"284329","sourceNumber":"284329","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente de 32 anos de idade, sem antecedentes mórbidos, procurou o\npronto-socorro com queixa de dor e desconforto abdominal iniciados há quatro dias,\nacompanhados de febre e parada de eliminação de fezes. Ao exame, encontra-se em regular\nestado geral, desidratada ++/4+, com pulso de 108 bpm, com PA de 120 x 70 mmHg e com\n\nabdome pouco distendido, doloroso em andar inferior de abdome, sem sinais de irritação peritoneal.\nCom base nesse caso hipotético, julgue o\nitem a seguir. Caso não se obtenha um diagnóstico com\nas medidas iniciais, a tomografia de abdome deverá ser usada para a definição.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-284330","number":"284330","sourceNumber":"284330","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente de 32 anos de idade, sem antecedentes mórbidos, procurou o\npronto-socorro com queixa de dor e desconforto abdominal iniciados há quatro dias,\nacompanhados de febre e parada de eliminação de fezes. Ao exame, encontra-se em regular\nestado geral, desidratada ++/4+, com pulso de 108 bpm, com PA de 120 x 70 mmHg e com\n\nabdome pouco distendido, doloroso em andar inferior de abdome, sem sinais de irritação peritoneal.\nCom base nesse caso hipotético, julgue o\nitem a seguir. A videolaparoscopia poderá ser\nempregada como diagnóstico e como tratamento no decorrer da investigação e do tratamento da\ndoente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-284331","number":"284331","sourceNumber":"284331","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente de 32 anos de idade, sem antecedentes mórbidos, procurou o\npronto-socorro com queixa de dor e desconforto abdominal iniciados há quatro dias,\nacompanhados de febre e parada de eliminação de fezes. Ao exame, encontra-se em regular\nestado geral, desidratada ++/4+, com pulso de 108 bpm, com PA de 120 x 70 mmHg e com\n\nabdome pouco distendido, doloroso em andar inferior de abdome, sem sinais de irritação peritoneal.\nCom base nesse caso hipotético, julgue o\nitem a seguir. A laparotomia, caso indicada, deverá ser\nfeita através de uma incisão longitudinal para que possam ser abordadas todas as possíveis\n\ncausas e complicações.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-262231","number":"262231","sourceNumber":"262231","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A pancreatite aguda foi definida, no Simpósio de Atlanta, em 1992, como um processo\ninflamatório agudo do pâncreas, com envolvimento variável de outros tecidos regionais ou de\nsistemas orgânicos remotos. A respeito dessa patologia e com base nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Dor abdominal característica e aumento de enzimas hepáticas\nmais que três vezes o limite superior da normalidade confirmam o diagnóstico de pancreatite\naguda.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-262232","number":"262232","sourceNumber":"262232","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A pancreatite aguda foi definida, no Simpósio de Atlanta, em 1992, como um processo\ninflamatório agudo do pâncreas, com envolvimento variável de outros tecidos regionais ou de\nsistemas orgânicos remotos. A respeito dessa patologia e com base nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Tomografia computadorizada ou ressonância magnética devem\nser solicitadas em caso de dúvida diagnóstica ou na ausência de melhora clínica após 48 a 72\nhoras da admissão hospitalar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-262234","number":"262234","sourceNumber":"262234","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A pancreatite aguda foi definida, no Simpósio de Atlanta, em 1992, como um processo\ninflamatório agudo do pâncreas, com envolvimento variável de outros tecidos regionais ou de\nsistemas orgânicos remotos. A respeito dessa patologia e com base nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. O uso de antibióticos apenas é indicado em casos de infecções e\npara prevenir infecções de necroses estéreis.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-239260","number":"239260","sourceNumber":"239260","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente de 14 anos de idade, sem comorbidades, dá entrada na sala de\nemergência com rebaixamento do nível de\nconsciência. A monitorização revelou FC = 120 bpm, PA\n\n= 78 mmHg x 50 mmHg, FR = 46 irpm, SpO2 = 93%, glicemia capilar = 102 mg/dL. A mãe do\npaciente conta que o adolescente apresentava\ndor abdominal há cinco dias, inicialmente ao redor\ndo umbigo, associada a vômitos, inapetência e picos febris não aferidos. Ao exame, está sonolento,\nmas responsivo aos chamados, com abdome tenso e descompressão brusca dolorosa. Relata ter\ncomido um hambúrguer com maionese um dia antes do início dos sintomas e os atribuiu a tal fato.\nCom base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. O\npaciente está em sepse e deve receber expansão volêmica e antibióticos o mais brevemente\npossível.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-239261","number":"239261","sourceNumber":"239261","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente de 14 anos de idade, sem comorbidades, dá entrada na sala de\nemergência com rebaixamento do nível de\nconsciência. A monitorização revelou FC = 120 bpm, PA\n\n= 78 mmHg x 50 mmHg, FR = 46 irpm, SpO2 = 93%, glicemia capilar = 102 mg/dL. A mãe do\npaciente conta que o adolescente apresentava\ndor abdominal há cinco dias, inicialmente ao redor\ndo umbigo, associada a vômitos, inapetência e picos febris não aferidos. Ao exame, está sonolento,\nmas responsivo aos chamados, com abdome tenso e descompressão brusca dolorosa. Relata ter\ncomido um hambúrguer com maionese um dia antes do início dos sintomas e os atribuiu a tal fato.\nCom base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir.\n\nDiverticulite aguda é uma hipótese a se considerar, por ser muito prevalente nessa faixa etária.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-239262","number":"239262","sourceNumber":"239262","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente de 14 anos de idade, sem comorbidades, dá entrada na sala de\nemergência com rebaixamento do nível de\nconsciência. A monitorização revelou FC = 120 bpm, PA\n\n= 78 mmHg x 50 mmHg, FR = 46 irpm, SpO2 = 93%, glicemia capilar = 102 mg/dL. A mãe do\npaciente conta que o adolescente apresentava\ndor abdominal há cinco dias, inicialmente ao redor\ndo umbigo, associada a vômitos, inapetência e picos febris não aferidos. Ao exame, está sonolento,\nmas responsivo aos chamados, com abdome tenso e descompressão brusca dolorosa. Relata ter\ncomido um hambúrguer com maionese um dia antes do início dos sintomas e os atribuiu a tal fato.\nCom base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A dor\nprovocada pela compressão e descompressão brusca do ponto de McBurney (fossa ilíaca\nesquerda) configura o sinal semiológico de Blumberg.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-196620","number":"196620","sourceNumber":"196620","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Certo paciente de 65 anos de idade, etilista pesado, vem apresentando intensa dor\nabdominal, associada a náuseas e vômitos há oito horas, após nova ingesta alcoólica. É o terceiro\nepisódio abdominal no mesmo mês. Em vista disso, são realizados exames laboratoriais que\nindicam transaminases hepáticas normais, bilirrubinas normais e lipase cinco vezes maior que o\nlimite superior da normalidade. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Trata-se de pancreatite aguda biliar.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-196625","number":"196625","sourceNumber":"196625","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Certo paciente de 65 anos de idade, etilista pesado, vem apresentando intensa dor\nabdominal, associada a náuseas e vômitos há oito horas, após nova ingesta alcoólica. É o terceiro\nepisódio abdominal no mesmo mês. Em vista disso, são realizados exames laboratoriais que\nindicam transaminases hepáticas normais, bilirrubinas normais e lipase cinco vezes maior que o\nlimite superior da normalidade. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. A técnica cirúrgica de Puestow pode ser usada para\ndescompressão do ducto pancreático.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-196627","number":"196627","sourceNumber":"196627","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Certo paciente de 65 anos de idade, etilista pesado, vem apresentando intensa dor\nabdominal, associada a náuseas e vômitos há oito horas, após nova ingesta alcoólica. É o terceiro\nepisódio abdominal no mesmo mês. Em vista disso, são realizados exames laboratoriais que\nindicam transaminases hepáticas normais, bilirrubinas normais e lipase cinco vezes maior que o\nlimite superior da normalidade. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. A cirurgia de Whipple pode ser empregada para o tratamento da\ndor, com bons resultados, e tem taxa de morbidade baixa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-196635","number":"196635","sourceNumber":"196635","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Certo paciente de 65 anos de idade, etilista pesado, vem apresentando intensa dor\nabdominal, associada a náuseas e vômitos há oito horas, após nova ingesta alcoólica. É o terceiro\nepisódio abdominal no mesmo mês. Em vista disso, são realizados exames laboratoriais que\nindicam transaminases hepáticas normais, bilirrubinas normais e lipase cinco vezes maior que o\nlimite superior da normalidade. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. O paciente deve ser orientado para a cessação do alcoolismo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-177673","number":"177673","sourceNumber":"177673","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo masculino, 72 anos de idade, apresenta dor recorrente em fossa\nilíaca esquerda e flanco esquerdo. Procura a\nemergência devido a dor abdominal no quadrante\ninferior esquerdo há 2 dias, temperatura axilar de 38 °C. História prévia de constipação crônica e\nsedentarismo. Nega cirurgias prévias e demais alterações. Traz colonoscopia realizada há 4 anos\ncom diagnóstico de diverticulose em cólon esquerdo. Com base no caso clínico apresentado, e nos\nconhecimentos médicos acerca da doença diverticular, julgue o item a seguir. A doença diverticular\né a causa mais comum de sangramento intestinal baixo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-135002","number":"135002","sourceNumber":"135002","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"No próximo item é apresentado um caso clínico seguido de uma assertiva a ser julgada.\nUma paciente assintomática foi submetida à avaliação abdominal de rotina por ultrassonografia\nabdominal. Foi identificada a presença de colelitíase, com vesícula de paredes finas e presença de\ncálculo único de 12 mm. Não havia sinal de dilatação das vias biliares. Nessa situação, a realização\nde colecistectomia não deve ser indicada, visto que a paciente é assintomática e não preenche os\ncritérios para realização de colecistectomia profilática.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-105555","number":"105555","sourceNumber":"105555","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um homem de 75 anos de idade foi atendido no posto de saúde com história de dor\nabdominal tipo cólica de leve a moderada intensidade há cerca de um mês. Referiu que\napresentava hematoquezia há cerca de três meses e que, há duas semanas, notou tumor na fossa\nilíaca esquerda de +/- 10 cm de diâmetro. Negou febre e referiu astenia e perda de cerca de 10%\nde seu peso habitual nos últimos dois meses. Negou antecedentes familiares de neoplasias,\ndiabetes e doenças cardiológicas. Com base nesse caso hipotético, no que se refere ao\ndiagnóstico, assinale a alternativa correta.","options":{"A":"A doença diverticular, com formação de plastrão, é o diagnóstico mais provável.","B":"Antes de qualquer exame de imagem, é fundamental a realização de pesquisa de sangue oculto\nnas fezes.","C":"A referência de hematoquezia reforça fortemente a hipótese de diverticulite.","D":"O clister opaco com duplo contraste será fundamental no caso de suspeita de diverticulite.","E":"Para descartar o diagnóstico diferencial com diverticulite, o exame de maior acuidade é a\ntomografia computadorizada."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-88713","number":"88713","sourceNumber":"88713","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Atualmente existem inúmeros pacientes em filas de espera para tratamentos definitivos.\nConsiderando que o tempo pode agravar as condições clínicas desses pacientes, julgue o item a\nseguir. Após o sucesso do tratamento clínico de apendicite aguda classificada como\npseudotumoral, o paciente pode esperar de seis a dez semanas pela apendicectomia eletiva, se for\nindicada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-79658","number":"79658","sourceNumber":"79658","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Com relação aos testes usados para avaliar função pancreática, assinale a alternativa\nque se refere aos testes com tubo:","options":{"A":"Testes fecais.","B":"Gordura nas fezes.","C":"Quimotripsina e tripsina.","D":"Teste pancreolauril.","E":"Teste de refeição (Lundh)."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-88712","number":"88712","sourceNumber":"88712","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"No que se refere às doenças infectocontagiosas e parasitárias, julgue o item\nsubsecutivo. Taenia solium, Taenia saginata e\nHymenolepis nana, cestoides de presença comum\nno organismo humano, necessitam, com exceção do H. nana, de um hospedeiro intermediário\nbovino ou suíno para sua reprodução. O homem pode tornar-se hospedeiro intermediário ao ingerir\novos de Taenia solium.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-64296","number":"64296","sourceNumber":"64296","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"<p>Um paciente de trinta e oito anos de idade foi atendido no pronto atendimento\nmédico, relatando que há dezesseis horas passara\na apresentar dor epigástrica, de forma súbita e\nintensa, irradiada para hipocôndrios (direito e esquerdo), &#34;em faixa&#34;, seguida de náuseas\ne vômitos. Informou, ainda, ingerir há mais de dez anos, grande quantidade de bebidas alcoólicas\ndestiladas. Ao exame clínico, o paciente apresentou-se ansioso, com fácies de dor aguda,\nsudorético, febril (temperatura axilar de 38,5ºC), 112 x 62 mmHg. Os resultados dos exames\nrespiratório e cardiovascular não apresentaram anormalidades. Foi identificado que o abdome do\npaciente estava difusamente doloroso à palpação profunda, mais intensamente na região\nepigástrica, pouco distendido, com ruídos hidroaéreos presentes e reduzidos, sem sinais de\nirritação peritoneal, evidenciando também a presença de mancha equimótica na região\nperiumbilical. Os exames complementares solicitados pelo médico assistente confirmaram o\ndiagnóstico de pancreatite aguda. Com base no caso clínico acima apresentado, julgue o item que\nse segue. A mancha equimótica constatada na região periumbilical desse paciente é um achado\nfrequente nessa doença, ela corresponde ao sinal de Grey-Turner, cuja base fisiopatogenética é a\ntrombocitopenia, não sendo, contudo, um indicador de prognóstico significativo.</p>","options":{"A":"Certo","B":"Errado"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-64667","number":"64667","sourceNumber":"64667","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"São exames a serem solicitados quando há dúvida diagnóstica sobre a DARF: I. fezes\ncomo parasitológico e pesquisa de sangue oculto;\nII. laparotomia exploradora profilática; III. urina\ncom urinocultura; IV. imagem como radiografia simples de abdômen e ultrassonografia de\nabdômen; V. sangue como hemograma e velocidade de hemossedimentação. É correto o que está\ncontido em:","options":{"A":"I, apenas.","B":"I, II e III, apenas.","C":"II, III e IV,apenas.","D":"I, III, IV e V, apenas.","E":"I, II, III, IV e V."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-64723","number":"64723","sourceNumber":"64723","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente, 53 anos de idade, se dirigiu ao serviço de emergência após início súbito\nde dor abdominal, em faixa, recebendo\ndiagnóstico de pancreatite aguda, com elevação de 4x os\nníveis normais de amilase sérica. Nas 48 horas que se seguiram à internação, passou a apresentar\nindícios de mau prognóstico. Baseando-se no sistema de pontuação prognóstica de Ranson,\nassinale a alternativa que apresenta esses indícios de mau prognóstico.","options":{"A":"Elevação de ureia, creatinina e hipoglicemia.","B":"Hipoalbuminemia.","C":"Hipoxemia e hipercalcemia.","D":"Base Excess (BE) positivo (maior que +4).","E":"Hipocalcemia e queda no hematócrito em mais de 10%."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-64734","number":"64734","sourceNumber":"64734","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma senhora sexagenária, com hábito intestinal cronicamente obstipado, iniciou quadro\nde dor abdominal, de caráter contínuo, em\nregião de hipogástrio e fossa ilíaca esquerda. Ao exame\nfísico, observa-se febre baixa (37,9 °C), distensão abdominal e palpação profunda dolorosa em\ntodo o andar inferior do abdome, principalmente em quadrante inferior esquerdo. Sendo assim,\nassinale a alternativa que indica o diagnóstico mais provável para este caso.","options":{"A":"Diverticulite aguda.","B":"Síndrome do intestino irritável.","C":"Apendicite.","D":"Retocolite ulcerativa.","E":"Neoplasia de Reto."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-45737","number":"45737","sourceNumber":"45737","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em um paciente com pancreatite aguda não biliar, o achado indicativo de mau\nprognóstico, segundo os critérios de Ranson, é:","options":{"A":"Idade < 55 anos.","B":"ALT > 250 UI/L na admissão.","C":"Cálcio sérico < 8 mg/dL na admissão.","D":"PaO2 < 60 mmHg nas primeiras 48 horas.","E":"DHL sérica > 350 UI/L nas primeiras 48 horas."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-49141","number":"49141","sourceNumber":"49141","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Julgue o próximo item, acerca do apêndice cecal, que é sede de diversas afecções\nbenignas e malignas. As infecções do sítio\nda ferida operatória são as complicações mais comuns\napós apendicectomias realizadas por laparotomia.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-45716","number":"45716","sourceNumber":"45716","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um homem, alcoólatra, foi admitido na emergência com uma história clínica de 48\nhoras de evolução de dor abdominal em\nregião epigástrica e com piora nas últimas 12 horas, com\nvômitos. O abdome estava distendido com dor difusa, porém sem irritação peritoneal. A contagem\nde células brancas foi de 13.000 Leu/mm³ (87% neutrófilos), e a amilase no soro foi de 750\nunidades Somogyi. Cinco semanas após a admissão no pronto-socorro, apresentou uma massa\nabdominal palpável na região epigástrica. Nessa situação, assinale a alternativa que apresenta a\ninvestigação recomendável para melhor avaliar a massa.","options":{"A":"Repetição da dosagem da amilase.","B":"Radiografia simples de abdome.","C":"Colecistograma oral.","D":"Colangioprancreatografia endoscópica retrógrada.","E":"Tomografia computadorizada de abdome."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-45750","number":"45750","sourceNumber":"45750","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um homem de setenta anos de idade procura a unidade de emergência com queixa de\ndor abdominal em fossa ilíaca esquerda e febre\nfaz cerca de oito horas. Ao exame físico, há grande\ndistensão abdominal e defesa voluntária da musculatura abdominal inferior, e palpa-se um plastrão\nnessa região. Caso a hipótese seja de diverticulite aguda, assinale a alternativa correta:","options":{"A":"A avaliação por exame de ressonância nuclear magnética é contraindicada pelo risco de\ndesbloqueio de um eventual tamponamento de perfuração.","B":"A retossigmoidoscopia flexível é mandatória para a avaliação do grau de comprometimento do\nsigmoide.","C":"A tomografia computadorizada de abdome é preferível em relação ao exame ultrassonográfico\ndo abdome para avaliação nesse momento,\nespecialmente por conta da distensão abdominal\nreferida.","D":"Há indicação de ressecção do segmento intestinal acometido, em caráter de urgência, caso seja\ndetectada qualquer coleção líquida localizada na região pélvica.","E":"O clister opaco, com contraste hidrossolúvel, é o exame inicial de escolha, pois fornecerá\ninformações precisas quanto à localização do segmento inflamado."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-45753","number":"45753","sourceNumber":"45753","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um homem de setenta anos de idade procura a unidade de emergência com queixa de\ndor abdominal em fossa ilíaca esquerda e febre\nfaz cerca de oito horas. Ao exame físico, há grande\ndistensão abdominal e defesa voluntária de musculatura abdominal inferior, e palpa-se um plastão\nnessa região. Acerca da doença diverticular e da diverticulose, assinale a alternativa correta:","options":{"A":"Evidências epidemiológicas demonstram que as características raciais, e não as dietéticas de\ningestão de baixa quantidade de fibras, são os principais responsáveis pela gênese dos\ndivertículos.","B":"Os divertículos localizam-se mais comumente entre as tênias antimesentéricas.","C":"Apesar de os divertículos serem mais frequentes no sigmoide, a maior parte dos casos de\ndiverticulite aguda acontece no cólon direito.","D":"Os divertículos são herniações da mucosa através do cólon nos locais de penetração da parede\nmuscular pelas arteríolas.","E":"O aspecto endoscópico dos divertículos mimetiza aquele encontrado nos casos de\nadenocarcinomas desse segmento intestinal."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-37946","number":"37946","sourceNumber":"37946","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Com referência ao caso de uma paciente de 22 anos de idade, que será submetida à\ncirurgia devido a quadro clínico de apendicite aguda diagnosticada há 12 horas, julgue o item: O\nsinal de Rovsing, evidenciado como dor no quadrante inferior direito do abdome, quando se aplica\npressão sobre o quadrante inferior esquerdo, deve ser pesquisado e pode ser constatado na\npaciente em tela.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-37947","number":"37947","sourceNumber":"37947","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Com referência ao caso de uma paciente de 22 anos de idade, que será submetida à\ncirurgia devido a quadro clínico de apendicite aguda diagnosticada há 12 horas, julgue o item: A\nartéria apendicular, que é ramo da artéria ileocólica, deverá ser ligada durante a operação.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-32169","number":"32169","sourceNumber":"32169","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Considere que uma paciente jovem, 31 anos de idade, tenha sido internada com\ndiagnóstico de pancreatite aguda. Nessa situação, os critérios de Ranson usados na admissão\nhospitalar para avaliação clínica e prognóstica são:","options":{"A":"AST, idade, leucometria, cálcio sérico, DHL.","B":"Glicemia, leucometria, cálcio sérico, DHL e hematócrito.","C":"Leucometria, hematócrito, cálcio sérico e DHL.","D":"Idade, glicemia, leucometria, DHL e AST.","E":"DHL, idade, glicemia, AST, e sequestro de líquido."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-29719","number":"29719","sourceNumber":"29719","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Quanto à síndrome de resposta inflamatória sistêmica (SIRS), julgue o item abaixo. A\npancreatite aguda pode desencadear o quadro de SIRS mesmo sem associação com infecções.","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-27546","number":"27546","sourceNumber":"27546","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A causa mais comum de isquemia intestinal aguda, dentre as citadas abaixo, é:","options":{"A":"lesão iatrogênica.","B":"doença inflamatória intestinal.","C":"vasculite mesentérica.","D":"embolia mesentérica.","E":"arteriopatia inflamatória."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-27543","number":"27543","sourceNumber":"27543","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"O sinal de Rovsing é sugestivo de apendicite aguda e resulta de uma manobra\nsemiológica que consiste em:","options":{"A":"aumento da dor à tosse provocada.","B":"dor à rotação interna do quadril direito","C":"indução de dores no quadrante inferior direito pela palpação do quadrante inferior esquerdo.","D":"dor à extensão do quadril direito.","E":"dor à punho percussão renal direita."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-27549","number":"27549","sourceNumber":"27549","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Assinale a alternativa que corresponde às principais causas de pancreatite aguda em\nnosso meio.","options":{"A":"Dislipidemia e trauma.","B":"Bypass cardiopulmonar e hipotensão.","C":"Neoplasia e cisto pancreático.","D":"Trauma e drogas.","E":"Litíase biliar e ingestão de álcool."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-334865","number":"334865","sourceNumber":"334865","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A apendicite aguda (AA) está entre as causas mais comuns de dor abdominal baixa,\nque levam os pacientes ao pronto-socorro, e o\ndiagnóstico mais comum feito em pacientes jovens\ninternados com abdome agudo. Com base nas diretrizes atuais acerca da AA, assinale a alternativa\ncorreta.","options":{"A":"A taxa de perfuração varia de 16% a 40%, ocorrendo com maior frequência nas faixas etárias\nmais jovens.","B":"A morbimortalidade é semelhante na AA perfurada e na não perfurada.","C":"Escores clínicos sozinhos são suficientemente sensíveis para confirmar o diagnóstico.","D":"O uso de escores clínicos não altera a indicação de exames de imagem em pacientes com\nsuspeita diagnóstica.","E":"O tratamento somente com antibióticos é uma alternativa segura para pacientes selecionados\ncom AA não complicada e com ausência de\napendicolito."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-334868","number":"334868","sourceNumber":"334868","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A pancreatite aguda é uma condição inflamatória do pâncreas, caracterizada por dor\nabdominal e níveis elevados de enzimas pancreáticas no sangue. A pancreatite aguda é uma\ncausa frequente de hospitalização, com mortalidade geral de aproximadamente 5%. Várias\ncondições estão associadas à pancreatite aguda, entre as quais é correto citar","options":{"A":"álcool, cálculo na via biliar e hipercolesterolemia.","B":"álcool, cálculo na via biliar e trauma pancreático.","C":"álcool, medicamentosa e hipercolesterolemia.","D":"cálculo na via biliar, medicamentosa e hipercalemia.","E":"cálculo na via biliar, trauma pancreático e hipercalemia."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-343430","number":"343430","sourceNumber":"343430","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"O sinal de Rovsing pode ser usado para o diagnóstico clínico de doenças que associam\ncom dores abdominais, sendo encontrado\nfrequentemente em casos de:","options":{"A":"Colelitíase.","B":"Apendicite aguda.","C":"Colecistite aguda.","D":"Pancreatite aguda."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-343436","number":"343436","sourceNumber":"343436","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Dados os critérios prognósticos na Pancreatite Aguda, está INCORRETO:","options":{"A":"Aumento do hematócrito, após 48h, pois irá avaliar o valor real, já que na admissão pode estar\n\n?mascarado?.","B":"Glicemia, que, se elevada, pode indicar um processo inicial de insuficiência pancreática.","C":"Idade, que, quanto mais avançada, mais o indivíduo se torna suscetível às complicações graves.","D":"AST (Aspartato Aminotransferase), que, se elevado, indica lesão orgânica, principalmente\nhepática."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-343437","number":"343437","sourceNumber":"343437","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"O Abdome Agudo se caracteriza por dor lenta, insidiosa e progressiva no início,\nnormalmente com intervalo longo entre o\ncomeço dos sintomas e a ida à Emergência. Na\npropedêutica abdominal, a palpação pode revelar defesa localizada ou generalizada, por meio da\ncontração voluntária da musculatura abdominal. É um mecanismo de defesa, tendo em vista o\ncomprometimento peritoneal. As causas mais comuns são apendicite, colecistite, pancreatite e\ndiverticulite agudas. É chamado de:","options":{"A":"Abdome Agudo Hemorrágico.","B":"Abdome Agudo Inflamatório.","C":"Abdome Agudo Perfurativo.","D":"Abdome Agudo Obstrutivo."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-301270","number":"301270","sourceNumber":"301270","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente de 37 anos de idade apresenta dor abdominal de forte intensidade em\nregião epigástrica, em hipocôndrio direito e dorso há um dia, acompanhada de náuseas e vômitos.\nNega episódios anteriores. Ao exame, encontrava-se desidratada ++/4+, com pulso de 112 bpm e\nPA = 130 mmHg X 80 mmHg. Verificaram-se abdome globoso, flácido, pouco doloroso à palpação\nem epigástrio e Murphy negativo, com descompressão brusca negativa. Os exames iniciais\nmostram Hb = 14,7 g/dL, leucócitos 14.760/mm³, e creatinina = 1,6 mg/dL, amilase = 870 UI e\nbilirrubinas totais = 2,3 mg/dL. Considerando esse caso clínico, julgue os itens de 26 a 30. A\nhidratação é a medida mais eficaz para essa paciente nas primeiras 48 horas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-301271","number":"301271","sourceNumber":"301271","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente de 37 anos de idade apresenta dor abdominal de forte intensidade em\nregião epigástrica, em hipocôndrio direito e dorso há um dia, acompanhada de náuseas e vômitos.\nNega episódios anteriores. Ao exame, encontrava-se desidratada ++/4+, com pulso de 112 bpm e\nPA = 130 mmHg X 80 mmHg. Verificaram-se abdome globoso, flácido, pouco doloroso à palpação\nem epigástrio e Murphy negativo, com descompressão brusca negativa. Os exames iniciais\nmostram Hb = 14,7 g/dL, leucócitos 14.760/mm³, e creatinina = 1,6 mg/dL, amilase = 870 UI e\nbilirrubinas totais = 2,3 mg/dL. Considerando esse caso clínico, julgue os itens de 26 a 30. O\nemprego de antibióticos de amplo espectro está bem indicado nesse caso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-301272","number":"301272","sourceNumber":"301272","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente de 37 anos de idade apresenta dor abdominal de forte intensidade em\nregião epigástrica, em hipocôndrio direito e dorso há um dia, acompanhada de náuseas e vômitos.\nNega episódios anteriores. Ao exame, encontrava-se desidratada ++/4+, com pulso de 112 bpm e\nPA = 130 mmHg X 80 mmHg. Verificaram-se abdome globoso, flácido, pouco doloroso à palpação\nem epigástrio e Murphy negativo, com descompressão brusca negativa. Os exames iniciais\nmostram Hb = 14,7 g/dL, leucócitos 14.760/mm³, e creatinina = 1,6 mg/dL, amilase = 870 UI e\nbilirrubinas totais = 2,3 mg/dL. Considerando esse caso clínico, julgue os itens de 26 a 30. Nesse\ncaso, a colangiografia retrógrada endoscópica é um exame fundamental para ser realizado nas\nprimeiras 24 horas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-301273","number":"301273","sourceNumber":"301273","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente de 37 anos de idade apresenta dor abdominal de forte intensidade em\nregião epigástrica, em hipocôndrio direito e dorso há um dia, acompanhada de náuseas e vômitos.\nNega episódios anteriores. Ao exame, encontrava-se desidratada ++/4+, com pulso de 112 bpm e\nPA = 130 mmHg X 80 mmHg. Verificaram-se abdome globoso, flácido, pouco doloroso à palpação\nem epigástrio e Murphy negativo, com descompressão brusca negativa. Os exames iniciais\nmostram Hb = 14,7 g/dL, leucócitos 14.760/mm³, e creatinina = 1,6 mg/dL, amilase = 870 UI e\nbilirrubinas totais = 2,3 mg/dL. Considerando esse caso clínico, julgue os itens de 26 a 30. O\nultrassom é um exame obrigatório para essa paciente e que trará informações importantes para a\ncondução do caso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-268887","number":"268887","sourceNumber":"268887","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente de 21 anos de idade queixa-se de dor em quadrante inferior direito há 24\nhoras, associada a febrícula, a náuseas sem vômitos e a inapetência. Nega comorbidades e está\nem uso de anticoncepcional combinado via oral corretamente. Ao exame físico, apresenta-se em\nbom estado geral, normocorada, anictérica e com mucosas úmidas e hidratadas. Quanto aos sinais\nvitais, constatam-se PA = 120 mmHg x 80 mmHg, FC = 98 bpm, FC = 17 irpm e SatO2 = 99%. No\nabdome, refere-se a dor abdominal em baixo ventre, que se encontra distendido e com sinal de\nBlumberg +. Ao exame ginecológico, a paciente nega dor à mobilização do colo uterino. Com\nrelação a esse caso clínico e à apendicite aguda no sexo feminino, assinale a alternativa correta.","options":{"A":"A dor inicia-se de maneira somática e converte-se em visceral.","B":"A hipótese diagnóstica de apendicite aguda é descartada se existir dor na mobilização do colo\ndo útero.","C":"O sinal de Blumberg + significa presença de dor no quadrante inferior direito à palpação do\nquadrante inferior esquerdo.","D":"A apendicectomia videolaparoscópica é a melhor opção em pacientes hemodinamicamente\nestáveis.","E":"A escolha da tomografia como primeiro exame de imagem é aceitável em pacientes femininas\nnão grávidas."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-268889","number":"268889","sourceNumber":"268889","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente tabagista e etilista procura atendimento em pronto-socorro em razão de\ndor abdominal súbita e com piora nas últimas 24\nhoras. Apresenta abdome em tábua,\ndesaparecimento da macicez hepática e os seguintes sinais vitais: PA = 100 mmHg x 60 mHg, FC =\n120 bpm, FR = 19 irpm e SatO2 = 99%. Considerando esse caso clínico, a respeito de abdome\nagudo, assinale a alternativa correta.","options":{"A":"O exame de escolha, indicado nesse momento, é a tomografia computadorizada com contraste.","B":"Devem ser receitados inibidores da bomba de prótons e deve-se observar a evolução do\ntratamento.","C":"O tratamento de Helicobacter pylori, no caso de úlceras gástricas, não é necessário.","D":"As úlceras gástricas do tipo I e IV não estão associadas a níveis elevados de ácidos e não\nnecessitam de vagotomia.","E":"Os raios X de abdome agudo não ajudariam no diagnóstico de pneumoperitônio."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-273332","number":"273332","sourceNumber":"273332","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação à Pancreatite Aguda (PA), é correto afirmar:","options":{"A":"O grau de elevação das enzimas pancreáticas relaciona-se com gravidade da doença.","B":"A amilase é superior à lipase para diagnóstico da PA por apresentar vida média mais longa.","C":"O sinal de Cullen é a coloração azulada periumbilical e está associado à gravidade da PA.","D":"Em 80% das vezes a doença tem curso grave e necrosante."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-291480","number":"291480","sourceNumber":"291480","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um homem com 42 anos de idade foi operado em hospital secundário com quadro de\napendicite aguda com necrose e abscesso em apêndice retrocecal (Fase III), sendo realizada\napendicectomia e drenagem do abscesso por incisão mediana infraumbilical. No terceiro dia de\npós-operatório começou a apresentar picos diários de aumento da temperatura axilar (38,5 ºC)\napesar dos antibióticos prescritos (ceftriaxona e metronidazol). A incisão encontrava-se com bom\naspecto, foram encontrados 15 200 leucócitos/mm³ (referência: 3 500 a 10 500) e alteração na\ncontagem diferencial dos leucócitos, com 5% de bastonetes no sangue periférico (referência: 0 a\n2%). A proteína C reativa era de 15 mg/L (referência: menor que 3). Relatava dor ao tentar fletir a\ncoxa direita e o examinador exercia discreta pressão contrária ao movimento, a ausculta pulmonar\nera normal e os ruídos hidroaéreos estavam presentes. Com base nos dados apresentados, qual é\na alternativa correta sobre a conduta?","options":{"A":"Solicitar radiografia do abdome em pé e deitado.","B":"Substituir os antibióticos prescritos.","C":"Manter os antibióticos prescritos e avaliar novos exames após 24 horas.","D":"Solicitar tomografia computadorizada do abdome."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-266443","number":"266443","sourceNumber":"266443","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente do sexo feminino, de 40 anos de idade, procurou a emergência médica\npor apresentar dor abdominal em andar superior\nde abdome, de forte intensidade, em barra,\ninédita, iniciada havia cerca de uma hora, associada a vômitos. Ela referiu ingesta prévia de comida\ngordurosa e negou etilismo e tabagismo. A paciente tem sobrepeso e dislipidemia não tratada. Os\nexames laboratoriais evidenciaram hiperamilasemia, e a ecografia de abdome superior indicou\ncolelitíase e coledocolitíase. No que se refere a esse caso clínico hipotético, julgue o próximo\nitem.\nA dislipidemia decorrente da hipercolesterolemia pode causar pancreatite.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-266444","number":"266444","sourceNumber":"266444","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente do sexo feminino, de 40 anos de idade, procurou a emergência médica\npor apresentar dor abdominal em andar superior\nde abdome, de forte intensidade, em barra,\ninédita, iniciada havia cerca de uma hora, associada a vômitos. Ela referiu ingesta prévia de comida\ngordurosa e negou etilismo e tabagismo. A paciente tem sobrepeso e dislipidemia não tratada. Os\nexames laboratoriais evidenciaram hiperamilasemia, e a ecografia de abdome superior indicou\ncolelitíase e coledocolitíase. No que se refere a esse caso clínico hipotético, julgue o próximo\nitem.\nNos casos de coledolitíase e pancreatite, indica-se colecistectomia imediata, sem necessidade de\nexploração de vias biliares.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-266445","number":"266445","sourceNumber":"266445","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente do sexo feminino, de 40 anos de idade, procurou a emergência médica\npor apresentar dor abdominal em andar superior\nde abdome, de forte intensidade, em barra,\ninédita, iniciada havia cerca de uma hora, associada a vômitos. Ela referiu ingesta prévia de comida\ngordurosa e negou etilismo e tabagismo. A paciente tem sobrepeso e dislipidemia não tratada. Os\nexames laboratoriais evidenciaram hiperamilasemia, e a ecografia de abdome superior indicou\ncolelitíase e coledocolitíase. No que se refere a esse caso clínico hipotético, julgue o próximo\nitem.\nAmilase sérica em níveis dez vezes maiores que o normal é critério de mau prognóstico nos casos\nde pancreatite aguda.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-266446","number":"266446","sourceNumber":"266446","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente do sexo feminino, de 40 anos de idade, procurou a emergência médica\npor apresentar dor abdominal em andar superior\nde abdome, de forte intensidade, em barra,\ninédita, iniciada havia cerca de uma hora, associada a vômitos. Ela referiu ingesta prévia de comida\ngordurosa e negou etilismo e tabagismo. A paciente tem sobrepeso e dislipidemia não tratada. Os\nexames laboratoriais evidenciaram hiperamilasemia, e a ecografia de abdome superior indicou\ncolelitíase e coledocolitíase. No que se refere a esse caso clínico hipotético, julgue o próximo\nitem.\nA ultrassonografia de abdome é um exame essencial nos casos de pancreatite, para elucidar causa\nbiliar.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-266447","number":"266447","sourceNumber":"266447","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente do sexo feminino, de 40 anos de idade, procurou a emergência médica\npor apresentar dor abdominal em andar superior\nde abdome, de forte intensidade, em barra,\ninédita, iniciada havia cerca de uma hora, associada a vômitos. Ela referiu ingesta prévia de comida\ngordurosa e negou etilismo e tabagismo. A paciente tem sobrepeso e dislipidemia não tratada. Os\nexames laboratoriais evidenciaram hiperamilasemia, e a ecografia de abdome superior indicou\ncolelitíase e coledocolitíase. No que se refere a esse caso clínico hipotético, julgue o próximo\nitem.\nO tratamento da pancreatite aguda envolve uso de antibióticos endovenosos, independentemente\nde achado radiológico ou do quadro clínico do paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-291500","number":"291500","sourceNumber":"291500","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo masculino, 65 anos, foi atendido no serviço de urgência de um\nhospital com queixa de dor em flanco e fossa\nilíaca esquerdos, com início há cerca de 48 horas e\npiora nas últimas 12 horas. Neste período, apresentou episódio febril de 38 ºC, aferido em seu\ndomicílio. Relatou apresentar divertículos do cólon há cerca de 12 anos, e que foi submetido a uma\ngastrectomia parcial há 1 ano por adenocarcinoma gástrico em antro, estágio IB. Apresentou\nrelatório médico relativo a esse procedimento, no qual constava endoscopia digestiva alta com\nbiópsia confirmando o diagnóstico histológico, tomografia computadorizada de abdome e tórax, que\nrevelava doença diverticular em sigmoide, e colonoscopia confirmando doença diverticular em\nsigmoide. Ao exame físico, o paciente estava em bom estado geral, frequência cardíaca de 95 bpm,\npressão arterial de 130x80 mmHg e temperatura axilar de 38,1 ºC. O abdome estava flácido, mas\ndoloroso à palpação profunda de flanco e fossa ilíaca esquerdos e hipogástrio. Hemograma revelou\nleucocitose de 16 000/mm³ (referência: 9 000-11 000/mm³) com 10% de bastões (referência: 0 ?\n\n5%). O paciente relatou estar preocupado pela possibilidade de ser um \"retorno do câncer\". O\nexame complementar e explicação para confirmação do diagnóstico nesse momento é","options":{"A":"Colonoscopia, que poderá diagnosticar diverticulite aguda ou neoplasia maligna do cólon.","B":"Tomografia por emissão de pósitrons acoplada à tomografia computadorizada (PET-TC), que\npoderá identificar recidiva da neoplasia maligna.","C":"Tomografia computadorizada de abdome com contraste venoso, que poderá identificar e\nmensurar complicações da diverticulite aguda do cólon.","D":"Radiografia de abdome em decúbito dorsal e posição ortostática e radiografia de tórax em\nincidência ântero-posterior, que poderão diagnosticar diverticulite aguda do cólon."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-274642","number":"274642","sourceNumber":"274642","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"O diagnóstico de apendicite aguda é eminentemente clínico. Considerando a correlação\nda fisiopatologia e das fases da apendicite aguda,\na alternativa que se refere à fase flegmonosa é:","options":{"A":"Edema, obstrução linfática, ulceração da mucosa.","B":"Obstrução venosa e arterial, perfuração.","C":"Estase, proliferação bacteriana.","D":"Secreção persistente, aumento de presença luminal."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-244462","number":"244462","sourceNumber":"244462","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A respeito de pancreatite, assinale a alternativa correta.","options":{"A":"Pancreatite aguda em paciente que se apresenta na admissão com idade abaixo de 70 anos,\nglicemia abaixo de 220 mg/dL e LDH sérico menos que 350 IU/L e leucograma abaixo de 18.000\nleucócitos totais é considerada leve, independentemente da etiologia.","B":"O tratamento inicial de pancreatite aguda grave é reposição volêmica, estabilização do quadro\nclínico e colangiopancreatografia retrógrada endoscópica com papilostomia.","C":"A presença de coleção peripancreática identificada em tomografia sempre indica drenagem\ncirúrgica.","D":"Nunca é indicado o uso de nutrição parenteral para paciente com pancreatite em razão do risco\nde hiperlipidemia.","E":"Alcoolismo, hiperparatireoidismo e hiperlipidemia são fatores de risco para pancreatite crônica."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-244469","number":"244469","sourceNumber":"244469","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Professora de 40 anos de idade apresenta-se no hospital com início súbito de dor\nabdominal intensa tipo pontada, com irradiação para o dorso esquerdo, associada a náuseas e\nvômitos iniciados há 24 horas, com fatores de alívio em se sentar e inclinar-se para a frente, e\nfatores de agravo em decúbito dorsal. Ela nega o uso de álcool e não fuma. Possui diabetes tipo 2\nem metformina e obesidade centrípeta. Ela é G2P2A0. Ao exame físico, encontra-se anictérica,\nacianótica, com palidez e sudorese fria, IMC = 40; PA = 80 mmHg x 40 mmHg, FC = 110/minuto,\nFR = 25 irpm, Tax = 38,5 ºC, SatO2 = 88%. Ao exame abdominal, constatam-se presença de\nequimoses em flanco esquerdo associado a região periumbilical, sensibilidade difusa em todo o\nabdome no exame abdominal, Blumberg negativo. RHA estão ausentes. Acerca desse caso clínico\ne tendo em vista os conhecimentos médicos relativos à pancreatite aguda (PA), assinale a\nalternativa correta.","options":{"A":"Pacientes com pancreatite grave podem apresentar febre, taquipneia, hipoxemia e hipotensão.\n\nEm 3% dos pacientes com PA, pode-se observar descoloração equimótica na região periumbilical\n(sinal de Cullen) ou ao longo do flanco (sinal\nde Gray Turner).","B":"Muitos medicamentos têm sido associados à PA, sendo comum a associação do uso de\nmetformina e PA, que é provável etiologia do paciente.","C":"A paciente apresenta o diagnóstico de PA, conforme critérios de Ransom para o qual dois\ncritérios maiores estejam presentes: dor\nabdominal sugestiva de pancreatite; uma elevação da\namilase sérica ou lipase sérica três vezes acima do normal; e evidência de TC ou RM consistente\ncom pancreatite.","D":"De acordo com a classificação de Atlanta, a paciente apresenta um quadro de PA edematosa\nintersticial, caracterizada por inflamação aguda do parênquima pancreático e dos tecidos\nperipancreáticos, com necrose tecidual reconhecível.","E":"O sistema de pontuação para prever a gravidade da PA com base em parâmetros clínicos,\nlaboratoriais, radiológicos e marcadores séricos,\nmais utilizado em PA é o escore de APACHE II;\ndevem ser usados na admissão e após 48 horas do diagnóstico."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-212036","number":"212036","sourceNumber":"212036","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, 27 anos de idade, foi atendida no pronto-socorro da clínica\nmédica com cólica na região epigástrica, iniciada havia 4 horas, com a presença de hiporexia e\nnáuseas. Posteriormente, a dor tornou-se contínua e mais forte, migrou para a fossa ilíaca direita,\nquando a paciente apresentou dois episódios de vômitos. Considerando o caso clínico descrito\nanteriormente e os múltiplos aspectos a ele relacionados, julgue o item a seguir. O diagnóstico\ninicial de prenhez ectópica não deve ser descartado.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-212041","number":"212041","sourceNumber":"212041","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, 27 anos de idade, foi atendida no pronto-socorro da clínica\nmédica com cólica na região epigástrica, iniciada havia 4 horas, com a presença de hiporexia e\nnáuseas. Posteriormente, a dor tornou-se contínua e mais forte, migrou para a fossa ilíaca direita,\nquando a paciente apresentou dois episódios de vômitos. Considerando o caso clínico descrito\nanteriormente e os múltiplos aspectos a ele relacionados, julgue o item a seguir. Um exame de\nleucograma com resultado de leucocitose acentuada e desvio à esquerda é patognomônico de\napendicite aguda.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-203034","number":"203034","sourceNumber":"203034","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente de 21 anos de idade apresenta histórico de dor em fossa ilíaca direita e\nhipogástrio há 24 horas, febre não aferida e hiporexia. Ao exame físico, apresenta dor à palpação\nprofunda em fossa ilíaca direita e hipogástrio, sem dor à descompressão. Sem queixas\nginecológicas, possui vida sexual ativa. Com relação a esse caso clínico, assinale a alternativa\ncorreta.","options":{"A":"Não é necessária avaliação da ginecologia.","B":"A paciente pode ser mantida em observação domiciliar, com retorno caso haja piora dos\nsintomas.","C":"Não são necessários exames de imagem para esse caso.","D":"O tratamento dessa paciente será cirúrgico.","E":"A videolaparoscopia pode ser usada tanto para diagnóstico quanto para eventual tratamento."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-212045","number":"212045","sourceNumber":"212045","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, 27 anos de idade, foi atendida no pronto-socorro da clínica\nmédica com cólica na região epigástrica, iniciada havia 4 horas, com a presença de hiporexia e\nnáuseas. Posteriormente, a dor tornou-se contínua e mais forte, migrou para a fossa ilíaca direita,\nquando a paciente apresentou dois episódios de vômitos. Considerando o caso clínico descrito\nanteriormente e os múltiplos aspectos a ele relacionados, julgue o item a seguir. A paciente deve\nser submetida a um exame ginecológico para o esclarecimento do diagnóstico.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-212052","number":"212052","sourceNumber":"212052","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, 27 anos de idade, foi atendida no pronto-socorro da clínica\nmédica com cólica na região epigástrica, iniciada havia 4 horas, com a presença de hiporexia e\nnáuseas. Posteriormente, a dor tornou-se contínua e mais forte, migrou para a fossa ilíaca direita,\nquando a paciente apresentou dois episódios de vômitos. Considerando o caso clínico descrito\nanteriormente e os múltiplos aspectos a ele relacionados, julgue o item a seguir. A presença de\napendicolito e o borramento da gordura periapendicular são sinais tomográficos significativos para\numa indicação cirúrgica em casos como o da paciente em questão.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-212023","number":"212023","sourceNumber":"212023","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, 27 anos de idade, foi atendida no pronto-socorro da clínica\nmédica com cólica na região epigástrica, iniciada havia 4 horas, com a presença de hiporexia e\nnáuseas. Posteriormente, a dor tornou-se contínua e mais forte, migrou para a fossa ilíaca direita,\nquando a paciente apresentou dois episódios de vômitos. Considerando o caso clínico descrito\nanteriormente e os múltiplos aspectos a ele relacionados, julgue o item a seguir. A ausência dos\nsinais do psoas, do obturador e de Rovsing no exame físico afasta o diagnóstico de prenhez\nectópica rota.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-212029","number":"212029","sourceNumber":"212029","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, 27 anos de idade, foi atendida no pronto-socorro da clínica\nmédica com cólica na região epigástrica, iniciada havia 4 horas, com a presença de hiporexia e\nnáuseas. Posteriormente, a dor tornou-se contínua e mais forte, migrou para a fossa ilíaca direita,\nquando a paciente apresentou dois episódios de vômitos. Considerando o caso clínico descrito\nanteriormente e os múltiplos aspectos a ele relacionados, julgue o item a seguir. Neoplasia de\napêndice cecal é o diagnóstico mais provável para essa paciente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-206107","number":"206107","sourceNumber":"206107","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação aos pseudocistos pancreáticos:","options":{"A":"Ocorrem em 5-15% dos pacientes que tem retenção de secreções peripancreáticas após um\nepisódio de pancreatite aguda.","B":"A observação está indicada para os pacientes assintomáticos, isso porque tem sido assinalada a\nregressão espontânea em até 70% dos casos, principalmente naqueles menores que 4 cm de\ndiâmetro, localizados na cabeça e sem evidência de obstrução ou comunicação com ducto\npancreático principal.","C":"A cápsula de um pseudocisto é composta por colágeno e tecido de granulação e não é revestida\npor epitélio.","D":"A reação fibrótica exige pelo menos de quatro a oito semanas para se desenvolver."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-177232","number":"177232","sourceNumber":"177232","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, com 15 anos de idade, acompanhada dos pais, procurou a\nemergência em função de dor abdominal com início há 12 horas. Relata que náuseas e dor\nperiumbilical se iniciaram antes da dor em fossa ilíaca direita. O abdome está doloroso, apresenta\nruído hidroaéreo diminuído e sinal de Blumberg e sinal de Rovsing positivos. Nega história de\ndiarreia, cirurgias prévias e menarca. Considerando o mencionado caso clínico e os conhecimentos\nmédicos referentes a ele, assinale a alternativa correta.","options":{"A":"Choque séptico, peritonite e abscessos intraperitoneais não fazem parte das complicações da\napendicite.","B":"Doença de Crohn, pielonefrite, pancreatite, pneumonia, cetoacidose diabética e linfadenite\nmesentérica não fazem parte dos diagnósticos diferenciais de apendicite.","C":"Os pacientes idosos têm maior benefício com a apendicectomia videolaparoscópica do que os\npacientes jovens. A intervenção cirúrgica precoce melhora os resultados.","D":"A apendicite é uma doença cirúrgica não obstétrica incomum durante a gravidez.","E":"Na ecografia de abdome, são evidências de apendicite aguda: fluxo sanguíneo inalterado no\napêndice, parede do apêndice fina e gordura apendicular adjacente hipoecogênica."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-177238","number":"177238","sourceNumber":"177238","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo masculino, de 25 anos de idade, procura um pronto-socorro com\nqueixa de dor abdominal periumbilical há 2\ndias, associada a náuseas e inapetência. Refere ter tido\num episódio de febre. Nega disúria. Relata que realizou eliminações fisiológicas presentes e\nnormais. Ao exame físico, apresenta dor abdominal em fossa ilíaca direita e defesa abdominal.\n\nConsiderando o caso clínico apresentado e os conhecimentos médicos relacionados a ele, é\ncorreto afirmar que a principal hipótese diagnóstica para o referido paciente é","options":{"A":"apendicite aguda.","B":"gastrite.","C":"pancreatite aguda.","D":"colecistite aguda.","E":"hérnia umbilical encarcerada."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-177243","number":"177243","sourceNumber":"177243","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A diverticulite é a complicação mais frequente nos pacientes que possuem\ndiverticulose. Geralmente, é uma enfermidade que está\nacompanhada de febre, leucocitose e,\nalgumas vezes, de massa palpável no abdome. A respeito da diverticulite, assinale a alternativa\nCORRETA.","options":{"A":"A ultrassonografia não é recomendada para realizar drenagem guiada de grandes abscessos\nintra-abdominais.","B":"A topografia mais comum da citada patologia é o cólon ascendente, associado ao espessamento\nmuscular da parede intestinal,\ncaracterístico da doença.","C":"As fístulas vaginal, vesical e de intestino delgado não são complicações comuns da\ndiverticulite.","D":"Pela classificação de Hinchey estágio I, os pacientes não apresentam boa resposta ao uso de\nantibióticos e necessitam de intervenção cirúrgica imediata.","E":"A doença diverticular é a causa mais comum de sangramento intestinal baixo."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-175125","number":"175125","sourceNumber":"175125","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"De acordo com o guideline do Colégio Americano de Gastroenterologia, assinale a\nalternativa INCORRETA sobre pancreatite aguda:","options":{"A":"Pseudocistos sempre requerem abordagem cirúrgica tardia.","B":"O uso de antibióticos profilático na pancreatite aguda grave não é recomendado.","C":"Nas pancreatites leves, dieta oral deve ser iniciada precocemente.","D":"A eficácia da dieta enteral via gástrica é semelhante à via jejunal."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-175138","number":"175138","sourceNumber":"175138","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A variação de posição mais comum do Apêndice Vermiforme é:","options":{"A":"Descendente na pelve menor.","B":"Retrocecal.","C":"Pré-ileal.","D":"Retroileal."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-168469","number":"168469","sourceNumber":"168469","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma mulher com 72 anos de idade foi atendida na sala de emergência de um hospital\npor apresentar quadro de dor abdominal com 24\nhoras de evolução. Ao exame físico, a paciente\nestava em bom estado geral, afebril com frequência cardíaca = 88 bpm e pressão arterial = 150 x\n95 mmHg, e seu abdome apresentava-se doloroso à palpação em fossa ilíaca esquerda, sem sinais\nde irritação peritoneal. Foi realizada uma tomografia de abdome, que evidenciou quadro de\ndiverticulite aguda com imagem sugestiva de abscesso de 1,5 cm de diâmetro junto à parede do\nsigmoide e ausência de pneumoperitônio. Diante desse quadro, a conduta adequada é:","options":{"A":"Exploração cirúrgica e antibioticoterapia.","B":"Jejum, hidratação e antibioticoterapia.","C":"Drenagem percutânea do abscesso.","D":"Jejum, colonoscopia e biópsia."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-168510","number":"168510","sourceNumber":"168510","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um homem com 28 anos de idade deu entrada em um pronto-socorro hospitalar,\nqueixando-se de dor no quadrante inferior\ndireito do abdome, com irradiação para região lombar\nipsilateral, tempo de evolução de 2 dias, acompanhada de febre (38,2 °C), disúria e diarreia. Ao\nexame físico, apresentava sinais de Blumberg e de Rovsing positivos. Foram solicitados alguns\nexames complementares, cujos resultados são: leucócitos = 15.000/mm³ (valor de referência: 4.000\na 11.000/mm³), com 22% de bastonetes (valor de referência: 0 a 4%); radiografia de abdome sem\nalterações significativas; ultrassonografia abdominal cujo laudo indicou apêndice cecal de 8 mm de\ndiâmetro e observação para considerar a hipótese de apendicite, de acordo com critérios clínicos. O\ncirurgião de plantão, suspeitando de apendicite aguda, indicou cirurgia com incisão em quadrante\ninferior direito. Durante o inventário cirúrgico, identificou-se um apêndice cecal de aspecto\nnormal,\nsem alterações macroscópicas e sem exsudações periapendiculares. Considerando essa situação,\na conduta cirúrgica adequada no período intraoperatório é","options":{"A":"realizar a inspeção da cavidade, esperar o paciente acordar e discutir com a família a realização\nda apendicectomia.","B":"não realizar apendicectomia, pois não há evidência de inflamação e os riscos não justificam a\nremoção do apêndice.","C":"realizar apendicectomia, caso a inspeção da cavidade seja negativa para outras patologias\nintra-abdominais.","D":"realizar apendicectomia, mesmo que seja encontrada outra patologia intra-abdominal."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-158015","number":"158015","sourceNumber":"158015","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Na avaliação prognóstica da pancreatite aguda, faz parte dos critérios de Ranson.","options":{"A":"Frequência respiratória > 25 irpm.","B":"Leucócitos > 16.000 /ml.","C":"TGP > 250 U/dL.","D":"Frequência cardíaca > 100 bpm.","E":"Pressão sistólica > 120 mmHg."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-168497","number":"168497","sourceNumber":"168497","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma mulher com 26 anos de idade, obesa e multípara, com passado de dores biliares\nrecorrentes, é atendida no Pronto-Socorro, queixando-se de dor abdominal de início abrupto, de\nforte intensidade, iniciada há aproximadamente 2 horas. Refere que a dor se localiza no andar\nsuperior do abdome, irradiando-se para o dorso, tendo ainda apresentado náuseas e vômitos. Ao\nexame físico, a paciente mostra-se hipo-hidratada (+/4+) e sente dor à palpação do abdome, que\nse encontra levemente distendido e com peristalse diminuída e sinal de Murphy ausente. Os\nexames laboratoriais mostram: aumento de lipase (370 UI/L; valor de referência: 0 a 160 UI/L);\nleucócitos = 18.700/mm³ (valor de referência 6.000 a 10.000/mm³); glicose sérica = 230 mg/dL\n(valor de referência 60 a 110 mg/dL); ALT = 260 UI/L (valor de referência 0 a 35 UI/L). AST = 360\nUI/L (valor de referência 0 a 35 UI/L) e desidrogenase tática = 425 UI/L (valor de referência: 88 a\n230 UI/L). A paciente é internada na Unidade de Tratamento Intensivo, mas a despeito de ser\ntratada de forma adequada (pausa alimentar, hidratação venosa, reposição eletrolítica e analgesia\nparenteral), evolui de forma grave. Após 48 horas, a paciente apresenta piora da dor abdominal,\ntaquipneia, icterícia (2+/4+), febre elevada (39 ºC) e calafrios. Os exames complementares\nrealizados nesse dia revelam piora do leucograma, com desvio à esquerda (17% de bastões; valor\nde referência: 0 a 5 %), queda de 11% do hematócrito e aumento das escórias nitrogenadas, com\nelevação da ureia sérica de 15 mg/dL em relação ao exame feito na admissão. Uma tomografia\ncomputadorizada dinâmica de abdome revela a presença de necrose pancreática que ocupa cerca\nde 35% do parênquima e dilatação significativa das vias biliares extra-hepáticas, com presença de\ncálculo impactado no colédoco terminal. Nesse caso, o tratamento adequado e imediato para a\npaciente e instituir","options":{"A":"hidratação parenteral vigorosa, nutrição parenteral total e antibioticoterapia com\nciproflixacina e\nampicilina","B":"hidratação parenteral vigorosa, antibioticoterapia de amplo espectro e realizar colecistectomia\nde\nurgência","C":"antibioticoterapia de amplo espectro e realizar colangiopancreatografia retrógrada endoscópica\n\ncom esfincterotomia.","D":"nutrição enteral com cateter posicionado distalmente ao duodeno, antibioticoterapia e proceder a\nnecrosectomia extensa."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-157980","number":"157980","sourceNumber":"157980","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Determinada paciente de 65 anos de idade, sexo feminino, procura a emergência com\nquadro de febre iniciada há dois dias,\nassociada a dor de caráter progressivo em fossa ilíaca\nesquerda, sem fatores de alívio ou piora. Já havia passado por episódios semelhantes, mas, dessa\nvez, procura atendimento em razão da persistência da dor. A tomografia de tórax mostra\nespessamento do cólon descendente, associado a infiltração dos planos adiposos adjacentes\n(Hinchey I). Nesse caso clínico, a principal hipótese diagnóstica e a conduta são, respectivamente,\ndiverticulite:","options":{"A":"Complicada e laparotomia exploradora de urgência.","B":"Complicada e videolaparoscopia de urgência.","C":"Complicada e drenagem percutânea guiada por tomografia computadorizada.","D":"Não complicada e tratamento conservador com antibioticoterapia.","E":"Não complicada e laparotomia exploradora."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-129009","number":"129009","sourceNumber":"129009","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Assinale a alternativa que apresenta a melhor definição para o sinal de Blumberg.","options":{"A":"Sensibilidade dolorosa transitória em rebote na parede abdominal.","B":"Dor no ombro à inspiração.","C":"Dor provocada por elevação e extensão da perna contra resistência.","D":"Dor à inspiração enquanto se aplica pressão no abdome superior direito.","E":"Dor no ponto de McBurney quando se comprime o abdome inferior esquerdo."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-133975","number":"133975","sourceNumber":"133975","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Quanto aos critérios de Ranson na pancreatite aguda não biliar na admissão do\npaciente, não se inclui neles a (o)","options":{"A":"Idade.","B":"Número de leucócitos.","C":"Glicemia.","D":"DHL.","E":"PO2."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-111287","number":"111287","sourceNumber":"111287","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Mulher de 43 anos, três filhos, Índice de Massa Corpórea (IMC) de 32,5 kg/m²,\napresenta-se ao pronto-socorro com quadro de\ndor abdominal de forte intensidade, acompanhada\nde vômitos e icterícia. Os exames iniciais mostram amilase sérica de 327 Us, TGO de 122, TGP de\n120, GGT de 278, bilirrubinas totais de 4,5 mg à custa de bilirrubina direta. O U.S. mostra\ncolelitíase com pequena dilatação intra-hepática e do hepatocolédoco. Avaliação do colédoco distal\ne pâncreas prejudicada. A conduta deve incluir:","options":{"A":"Jejum, hidratação, analgésicos, antiemético, observação e reavaliação clínica permanente.","B":"A avaliação do caso como pancreatite aguda biliar, tratar clinicamente, inclusive com antibiótico\nde largo espectro e estabelecer os critérios de\nRanson para classificação com novos exames\nsorológicos em 24 horas.","C":"A tomografia computadorizada abdominal, pois existe dúvida diagnóstica e U.S., embora muito\nbom para fígado e vesícula, não o é para colédoco distal e pâncreas.","D":"A colangiopancreatografia endoscópica retrógrada que seria diagnóstica e terapêutica, mas\ndevido à possibilidade de colangite, a congiografia por ressonância magnética tem preferência\ndiagnóstica.","E":"A colecistectomia laparoscópica ou convencional com colangiografia por se tratar de abdome\nagudo inflamatório."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-104783","number":"104783","sourceNumber":"104783","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação às pancreatites, agudas ou crônicas, assinale a alternativa correta.","options":{"A":"Nos países ocidentais, a pancreatite crônica está, na maioria dos casos, associada à ingestão\nde drogas, como diuréticos e antibióticos.","B":"A doença biliar está mais associada à pancreatite aguda que à pancreatite crônica.","C":"A ingestão crônica de etanol leva principalmente à formação de pseudocistos pancreáticos.","D":"A colangiopancreatografia retrógrada endoscópica, se realiza com contraste hidrossolúvel, não\nleva ao aparecimento de pancreatite aguda.","E":"As picadas de abelha podem levar ao aparecimento de pancreatite aguda."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-111326","number":"111326","sourceNumber":"111326","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"O tronco celíaco, tipicamente, dá origem a três artérias. Assinale-as.","options":{"A":"Hepática direita, hepática esquerda e gástrica direita.","B":"Gastroduodenal, hepática comum e gástrica esquerda.","C":"Esplênica, hepática comum e gástrica esquerda.","D":"Hepática comum, gástrica direita e gastroduodenal.","E":"Hepática direita gástrica direita e esplênica."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-111333","number":"111333","sourceNumber":"111333","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação à litíase biliar, qual alternativa não está relacionada à formação de\ncolelitíase?","options":{"A":"Gravidez.","B":"Dieta parenteral.","C":"Doença de Crohn.","D":"Ingestão prolongada de Aspirina.","E":"Ingestão de uma refeição ao dia."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-111356","number":"111356","sourceNumber":"111356","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Homem de 40 anos com quadro agudo de dor súbita no epigástrio e irradiação para\ntodo o abdome há seis horas, vômitos\nclaros no início e parada da eliminação de gases. No exame\nfísico, com contratura abdominal e com sinais de irritação peritoneal em todo o abdome. O exame\ncomplementar inicial a ser realizado será:","options":{"A":"RX de tórax e abdome.","B":"Hemograma completo.","C":"Urina.","D":"Ultrassonografia de abdome total.","E":"Tomografia computadorizada de abdome total."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-97769","number":"97769","sourceNumber":"97769","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma paciente com 56 anos de idade vem para consulta na Unidade de Pronto\nAtendimento com queixa de dor abdominal em\nandar inferior do abdome há cerca de seis dias.\nRelata hiporexia e febre baixa há três dias. Nega diarreia e vômitos. Refere constipação intestinal\nque se acentuou nos últimos meses; nega hematoquesia. Ao exame físico do abdome apresenta\nruídos hidroaéreos normais, abdome globoso, normotenso, doloroso à palpação superficial e\nprofundo em fossa ilíaca esquerda, onde evidencia-se massa palpável. Não há visceromegalias ou\nhérnia inguinal. Qual o diagnóstico e conduta corretos?","options":{"A":"Diverticulite aguda; antibioticoterapia.","B":"Diverticulite aguda; videolaparoscopia.","C":"Câncer de cólon; rádio e quimioterapia.","D":"Câncer de cólon; laparotomia exploradora."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-97855","number":"97855","sourceNumber":"97855","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma mulher, com 76 anos de idade, apresenta antecedentes de hipertensão arterial,\ndislipidemia e obesidade, e faz uso de\nenalapril -20 mg/dia e sinvastatina -20 mg/dia. A paciente\ndeu entrada no Pronto-Socorro com quadro de dor abdominal de início súbito há cerca de sete\nhoras, de forte intensidade, em região epigástrica, com irradiação para o dorso, sem relação com a\nalimentação e acompanhada por náuseas e vômitos. Refere haver leve melhora da dor com\ninclinação do corpo para frente. Na admissão hospitalar estava consciente, orientada, anictérica,\ncom palidez cutâneo-mucosa. Temperatura axilar = 36 °C, pressão arterial = 100 x 60 mmHg,\nfrequência cardíaca = 105 bpm, frequência respiratória = 18 irpm, índice de massa corporal = 34,2\nkg/m² (valor de referência = até 30 kg/m²). As auscultas cardíacas e pulmonar não demonstram\nalterações. Abdome obeso, muito doloroso à palpação superficial e profunda em epigástrio, sem\nmassas ou organomegalias palpáveis. Ruídos hidroaéreos ausentes . Não havia edema de\nmembros inferiores. Os exames laboratoriais iniciais revelaram: Leucócitos = 14.500/mm³ (Valor de\nreferência: 4.500 a 11.000/mm³), com 84% de segmentados, 0% de eosinófilos, 10% de linfócitos);\nhemoglobina = 13,0 g/dl ( Valor de referência 12-16 g/dl); hematócritos = 39% (Valor de referência:\n36% - 46%); plaquetas = 231.000/mm³ (Valor de referência: 150.000 - 350.000/mm³); glicemia =\n106 mg/dl (Valor de referência: 80 - 100/mg/dl); ureia = 70 mg/dl(Valor de referência: 20 -\n35/mg/dl);\nCreatinina = 1,2 mg/dl (Valor de referência: 0,8 - 1,2 mg/dl); amilase = 2560 U/L (Valor de\nreferência: 4 - 400 U/L); AST = 26 U/L (Valor de referência: < 35 U/L); ALT = 31 U/L (Valor de\nreferência: < 35 U/L); bilirrubina total = 1,5 mg/dl (Valor de referência: 0,3 - 1,2 mg/dl);\nbilirrubina\ndireta = 0,4 mg/dl (Valor de referência: < 0,2 mg/dl); bilirrubina indireta = 0,8 mg/dl (Valor de\nreferência: < 1,0 mg/dl); LDH = 200 U/L (Valor de referência: 135-214 U/L). Considerando o\ndiagnóstico da paciente, assinale a alternativa que contém critérios clínicos e/ou laboratoriais de\nmaior gravidade e pior prognóstico que sugerem a necessidade de internação em Unidade de\nTratamento Intensivo.","options":{"A":"Obesidade e elevação da ureia.","B":"Taquicardia e elevação da amilase.","C":"Sexo feminino e elevação das bilirrubinas.","D":"Dor abdominal intensa e elevação da glicemia."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-64432","number":"64432","sourceNumber":"64432","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A causa mais frequente de pancreatite crônica é:","options":{"A":"Cálculo biliar","B":"Desnutrição","C":"Trauma","D":"Álcool","E":"Idiopática"},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-64444","number":"64444","sourceNumber":"64444","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente com história prévia de libação alcoólica evoluindo com dor epigástrica e\nvômitos. Foram detectados altos níveis séricos de triglicerídeos. O diagnóstico mais provável é:","options":{"A":"Colecistite aguda","B":"Gastrite","C":"Hepatite","D":"Pancreatite","E":"Diverticulite"},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-75549","number":"75549","sourceNumber":"75549","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Mulher com 25 anos de idade deu entrada no Serviço de Emergência, prostrada, com\nvômitos. Ao exame físico, observou-se hipotensão arterial, febre de 39°C, defesa na fossa ilíaca\ndireita, distensão e irritação peritonial difusas. O exame ginecológico e o toque retal\nevidenciaram a\npresença de dor no fundo de saco posterior à mobilização do colo uterino. A punho percussão\nlombar era negativa, bilateralmente. A melhor abordagem para o caso é:","options":{"A":"reposição volêmica; realização de hemograma; solicitação de tomografia computadorizada do\nabdome para excluir o diagnóstico de\npelviperitonite.","B":"reposição volêmica; realização de hemograma; iniciar antibioticoterapia após coleta de sangue\npara hemocultura e indicar o tratamento\ncirúrgico.","C":"reposição volêmica; solicitação de exame de urina, de exames de rotina para abdome agudo;\nrepetir a ultrassonografia e reavaliar periodicamente.","D":"solicitação de hemograma; realização de exame de urina e ultrassom para fazer o diagnóstico\ndiferencial com ruptura de cisto ovariano.","E":"reposição volêmica; solicitação de radiografia do abdome inferior e reavaliar."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-75460","number":"75460","sourceNumber":"75460","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Mulher com 38 anos de idade procurou o Serviço de Urgência referindo há 1 dia a\nocorrência de dor abdominal intensa em andar superior do abdome, acompanhada de vômitos\n\npós-alimentares. Ao exame físico encontrava-se com hálito etílico, dor difusa à palpação abdominal,\ncom descompressão brusca positiva. Sobre a\ninvestigação diagnóstica dessa paciente, é correto\nafirmar que:","options":{"A":"a dosagem de amilase sérica normal afasta o diagnóstico de pancreatite.","B":"a radiografia de tórax auxilia na investigação de\ndoença ulcerosa péptica complicada.","C":"a ultrassonografia abdominal é o exame de escolha para a investigação de pancreatite.","D":"o diagnóstico de hepatite alcoólica pode ser afastado devido à presença de descompressão\nbrusca positiva.","E":"deve ser realizada laparotomia exploratória com\nurgência, pois a paciente está com sinais de abdome agudo."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-137544","number":"137544","sourceNumber":"137544","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma mulher de 40 anos de idade, branca, casada, procura o Serviço de Emergência\nqueixando-se de dor abdominal epigástrica em todo o hemi-abdome superior, intensa, contínua,\ncom irradiação para o dorso e acompanhada de náuseas e vômitos há 24 horas. Não refere história\nde doença pregressa, etilismo, tabagismo e uso de medicamentos. Informa ter 4 filhos. Ao exame\nfísico apresenta-se desconfortável no leito. Encontra-se afebril, com FC = 110 bpm,\n\nPA = 100 x 60 mmHg, pele com discreta sudorese, mucosas coradas e escleróticas ictéricas 1+/4+.\nAo exame do abdome observam-se ruídos\nhidroaéreos presentes; abdome flácido,\n\ncom dor à palpação no hemi-abdome superior e ausência de visceromegalias. Os exames\nlaboratoriais mostram: hemograma com 15 400 leucócitos/mm³ (valores de referência\n\n3 = 3 800 a 10 600/mm ) com neutrofilia; glicose = 130 mg/dL (valor de referência = 99 mg/dL);\namilase = 1 240 U/L (valor de referência =\n30 a 225 U/L); lipase = 600 U/L (valor de referência = 3 a\n43 U/L), bilirrubinas totais = 5,2 mg/dL (valor de referência < 1,3 mg/dL), com fração direta de 2,0\nmg/dL (valor de referência < 0,4 mg/dL); alanino-amino-transferase = 162 UI/L (valor de referência\n\n= < 35 UI/L); aspartato-aminotransferase = 87 UI/L (valor de referência < 30 UI/L). A\n\nradiografia simples de abdome mostra padrão inespecífico de distribuição de gases, sem vidência\nde pneumoperitônio. Diante do quadro apresentado, a\nprincipal hipótese diagnóstica é","options":{"A":"cólica biliar.","B":"pancreatite biliar.","C":"obstrução intestinal.","D":"isquemia mesentérica.","E":"úlcera gástrica perfurada"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-137565","number":"137565","sourceNumber":"137565","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma mulher de 60 anos de idade é admitida na Emergência de um Pronto-Socorro de\nreferência com quadro de dor em fossa ilíaca esquerda há trinta horas, associada a febre, três\nepisódios\n\nde evacuação diarreica, náuseas e dois episódios de vômitos ocorridos há seis horas. Ao exame\nfísico, foi palpada massa de limites imprecisos em fossa ilíaca esquerda. O diagnóstico\n\nsugerido pela tomografia abdominal e pélvica foi diverticulite aguda. Qual a conduta inicial para\nessa paciente?","options":{"A":"Antibióticos endovenosos, suspensão da dieta oral e analgesia com dipirona.","B":"Dieta constipante, administração de antieméticos endovenosos e analgesia com morfina.","C":"Hidratação endovenosa, analgesia e encaminhamento para cirurgia de urgência.","D":"Antibióticos por via oral, dieta rica em fibras e analgesia com morfina.","E":"Drenagem percutânea de emergência."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-137527","number":"137527","sourceNumber":"137527","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Uma mulher com 31 anos de idade procurou atendimento de urgência relatando um\nquadro de dor abdominal de início abrupto,\ndifusa, contínua, intensa, com duração de cerca\nde seis horas, acompanhada de vômitos. Referiu também que tem utilizado diclofenaco de\nsódio, 50 mg de 8/8 horas, há aproximadamente um mês, para tratamento de lombalgia. Ao\nexame físico: frequência cardíaca = 120 bpm, pressão arterial = 90 x 60 mmHg, temperatura\naxilar = 38,2°C. Ao exame do abdome, verifica-se a presença de aumento da tensão da\nparede abdominal, com dor intensa e difusa à percussão e à palpação superficial, dificultando\na palpação profunda. Ruídos hidroaéreos diminuídos.\n\nO exame complementar mais indicado para a investigação diagnóstica inicial da paciente é\na","options":{"A":"tomografia computadorizada do abdome.","B":"radiografia de tórax e de abdome em ortostase.","C":"ultrassonografia abdominal total.","D":"endoscopia digestiva alta.","E":"ressonância magnética do abdome."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-138411","number":"138411","sourceNumber":"138411","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Homem, com 26 anos de idade, foi internado há dois dias com o diagnóstico de doença\ninflamatória intestinal na forma fulminante com megacólon tóxico. Há cerca de uma hora\napresentou piora súbita da dor abdominal, vômitos e desconforto respiratório. O exame físico revela\npaciente taquicárdico, taquidispneico e com abdome muito doloroso difusamente. A complicação é\nfrequente e o principal recurso diagnóstico para demonstrá-la são","options":{"A":"perfuração intestinal; radiografia de tórax e de\nabdome em ortostatismo e decúbito dorsal.","B":"pneumatose intestinal; enema opaco com contraste iodado.","C":"abscesso perirretal; tomografia computadorizada de abdome.","D":"vôlvulo de sigmóide; colonoscopia.","E":"hematoma intraluminal; colonoscopia."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-30987","number":"30987","sourceNumber":"30987","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um homem com 62 anos de idade procurou assistência médica com relato de que, há\nvários meses, vem sentindo desconforto epigástrico, com irradiação para o dorso, que piorava em\ntorno de 30 minutos após a alimentação. Informou, também, diarreia e importante perda de peso\nnos últimos seis meses. No exame clínico, apresentava-se emagrecido, com índice de massa\ncorporal de 15 kg/m², com leve dor à palpação profunda da região epigástrica, sem outras\nanormalidades. Os exames laboratoriais mostraram: glicemia de jejum = 200 mg/dl (valores de\nreferência de 74 mg/dl a 106 mg/dl); hemograma sem alterações, bilirrubina total = 0,8 mg/dl\n(valores de referência de 0,3 mg/dl a 1,2 mg/dl), TGO = 28 U/L (valores de referência de 10 U/L a\n30 U/L) e TGP = 38 U/L (valores de referência de 10 U/L a 40 U/L), amilase sérica = 130 U/L\n(valores de referência de 27 U/L a 131 U/L), lipase sérica = 180 U/L (valores de referência 31 U/L a\n186 U/L). Os exames de imagem confirmaram o diagnóstico de pancreatite crônica. Com relação a\nesse caso clínico, julgue o item que se segue: No caso clínico em tela, a constatação de\ncalcificação pancreática difusa, - decorrente de pancreatolitíase - por meio de radiografia simples\ndo abdome possibilita confirmar o diagnóstico de pancreatite crônica.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-138585","number":"138585","sourceNumber":"138585","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Mulher, com 35 anos de idade, procura atendimento médico por apresentar quadro de\ndor de início súbito, com localização\ninicial na região epigástrica, inicialmente acompanhada de\nvômitos, com rápida expansão para o flanco e a fossa ilíaca direita e, posteriormente, para todo o\nabdome. A paciente apresenta extremidades frias e respiração superficial; busca manter-se imóvel\ne adota posição antálgica, com pernas fletidas sobre o tronco. O abdome é difusamente doloroso,\nsendo evidentes a contratura abdominal e a rigidez da musculatura abdominal à palpação e à\nrespiração. A radiografia de tórax e a radiografia simples de abdome, ambas realizadas em\nortostatismo, mostram pneumoperitôneo. Com relação à complicação apresentada pela paciente, é\ncorreto afirmar que","options":{"A":"figura entre as causas mais frequentes de abdome agudo não traumático e metade dos casos\nocorre em pacientes com idade entre 20 e 40\nanos.","B":"nas úlceras duodenais as perfurações ocorrem, de um modo geral, na parede posterior e na\ncurvatura do duodeno.","C":"nas úlceras gástricas as perfurações ocorrem,\n\nusualmente, na parede posterior do antro e da região pré-pilórica.","D":"a área mais acometida por perfurações de úlceras\n\npépticas é o estômago, na proporção de 14:1 em relação ao duodeno.","E":"a mortalidade é proporcionalmente maior nas\nperfurações duodenais, em torno de 20%, talvez\nporque acometam pacientes mais idosos."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-138594","number":"138594","sourceNumber":"138594","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Mulher, com 44 anos de idade, apresenta quadro de dor epigástrica, com irradiação em\nfaixa para hipocôndrio direito e esquerdo, com vômitos e distensão abdominal, de início súbito sem\nrelação com esforço, ocorrendo há seis horas. Relata dois episódios semelhantes anteriores, de\nmenor intensidade, nos últimos três anos, dos quais se recuperou apenas com restrição de dieta.\n\nRelata ainda trombose de retina à esquerda após um desses episódios. Durante o exame físico,\nforam visualizadas mucosas descoradas, anictérica, pele com turgor e elasticidade reduzidos.\n\nPressão arterial = 40x90 mmHg. Pulso radial = 120 bpm, rítmico e fino. Ausculta respiratória -\nexpansibilidade reduzida em base de hemitórax esquerdo, com submacicez local. Ausculta\ncardíaca - bulhas taquicárdicas em dois tempos. Abdome distendido, com equimoses nos flancos.\nRuídos hidroaéreos diminuídos e dor difusa à palpação. Extremidades: pulsos periféricos palpáveis\ne simétricos. Exame laboratoriais mostram Ht = 52%, Hb = 14 g/L. Amilase = 104 U/L (Valor normal\n\n= 27 a 131U/L). Glicemia na admissão = 230 mg/dL. Creatinina = 1,5 mg/ dL (Valor normal = 0,7 a\n1,3 mg/dL). Troponina Sérica = 0,5 ng/mL (Valor normal < 0,1 ng/mL). ECG sem alterações. O\nlaboratório informa que o soro apresenta aspecto francamente leitoso na centrifugação.\n\nUltrassonografia de abdome mostra vias biliares não dilatadas e vesícula biliar de paredes finas,\nsem cálculos. O retroperitôneo não foi visualizado. Qual o diagnóstico compatível com o quadro\ndescrito?","options":{"A":"Pancreatite aguda.","B":"Dissecção de aorta.","C":"Infarto do miocárdio.","D":"Colecistite aguda.","E":"Infarto mesentérico."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-19205","number":"19205","sourceNumber":"19205","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Considerando o caso de uma paciente de 28 anos de idade, com megaesôfago\nchagásico e desnutrição calórico-proteica, julgue\no próximo item. Para que o diagnóstico de\nmegaesôfago possa ser feito corretamente, é necessário, além da existência de sintomas, que\nsejam realizados os seguintes exames: esofagograma, endoscopia, manometria e ph-metria\nesofágica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-334724","number":"334724","sourceNumber":"334724","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente masculino, 74 anos, diabético, hipertenso e com by-pass coronariano prévio,\ndeu entrada no hospital com diagnóstico de pé\ndiabético, sem sinais de sepse, sendo internado\npara antibioticoterapia endovenosa. No segundo dia de internação, iniciou quadro de dor abdominal\ndifusa, intensa, encontrado gemente no quarto. Ao exame, paciente acordado, comunicativo,\ngemente, afebril, eupneico, taquicárdico (frequência cardíaca de 101 bpm), ritmo cardíaco irregular,\npulso amplo, abdome discretamente distendido, ruídos hidroaéreos diminuídos, timpânico,\ndepressível, levemente doloroso, sem sinais de irritação peritoneal. Apresentou hábito intestinal\nnormal até o início da dor. Diante do quadro, qual dos itens abaixo combina o tipo mais provável de\nabdome agudo e sua respectiva propedêutica de exame de imagem mais indicada?","options":{"A":"Abdome agudo inflamatório, ultrassonografia de abdome total.","B":"Abdome agudo obstrutivo, radiografia de abdome agudo (em pé, deitado e cúpulas\ndiafragmáticas).","C":"Abdome agudo hemorrágico, radiografia de abdome agudo (em pé, deitado e cúpulas\ndiafragmáticas).","D":"Abdome agudo vascular, angiotomografia de abdome com contraste endovenoso."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-334725","number":"334725","sourceNumber":"334725","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Sobre a apendicite aguda é CORRETO afirmar que:","options":{"A":"No escore diagnóstico de Alvarado estão incluídos exames laboratoriais, tais como proteína C\nreativa.","B":"Antibioticoterapia pós-operatória está indicada para pacientes com apendicite aguda não\ncomplicada.","C":"A apendicectomia videolaparoscópica está associada a maior incidência de abscesso\nintra-abdominal em casos de apendicites agudas com perfuração e necrose.","D":"O tratamento não operatório pode ser indicado com bons resultados para aqueles pacientes que\nse apresentam com apendicolito nos exames de\nimagem."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-359173","number":"359173","sourceNumber":"359173","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A evolução da dor abdominal, sua duração, caráter e intensidade ajudam a definir um\nperfil para cada situação clínica específica. Assinale a alternativa CORRETA que contém o perfil de\ndor e a sua possível causa.","options":{"A":"Dor lancinante, aguda, de início súbito e de forte intensidade sugere quadros inflamatórios ou\nobstrutivos.","B":"Dor que se inicia de forma mais leve e, ao longo do tempo, evolui com piora súbita sugere\nobstrução de intestino delgado.","C":"Dor periumbilical e/ou difusa, constante, pode sugerir isquemia intestinal.","D":"Dor em cólica e de forte intensidade sugere perfuração de víscera oca e aneurisma roto de\naorta."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-359206","number":"359206","sourceNumber":"359206","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A pancreatite aguda é um processo inflamatório agudo do pâncreas, de etiologia\ndiversa, caracterizada por:","options":{"A":"Resposta inflamatória sistêmica, que requer antibioticoterapia intravenosa, sob regime de\ninternação.","B":"Início súbito dos sintomas, que tendem a se resolver espontaneamente após alguns dias do\ninício do quadro.","C":"Dor crônica e sintomas diversos, cujo diagnóstico requer exames por imagem para confirmação\nda inflamação.","D":"Deterioração clínica, em geral, de 7 dias a 10 dias do início da internação."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-368191","number":"368191","sourceNumber":"368191","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"As principais complicações com indicação de cirurgia da pancreatite crônica são","options":{"A":"formação de pseudocisto, sangramento e associação com adenocarcinoma de pâncreas.","B":"icterícia por obstrução do colédoco intrapancreático, pseudocistos e derrames cavitários e\nperfuração de alças intestinais, principalmente o cólon.","C":"sangramento, icterícia por obstrução do colédoco intrapancreático e diabete melito.","D":"icterícia por obstrução do colédoco intrapancreático, pseudocistos e derrames cavitários e\nobstrução da luz duodenal."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-351594","number":"351594","sourceNumber":"351594","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Sobre os exames subsidiários de abdome agudo, considere as afirmativas a seguir: I- A\ntomografia computadorizada de abdome e pelve detecta com alta sensibilidade e especificidade\nlesões inflamatórias, coleções, obstruções intestinais, isquemia e necrose esplâncnica, obstruções\narteriais, tromboses venosas, hemorragias intracavitárias e neoplasias. II- Cada padrão de abdome\nagudo tem seus exames preferenciais, sendo que alguns exames são sempre solicitados,\nindependentemente do padrão clínico. São eles: hemograma, amilase/lipase e coagulograma. III-\nSão exames indispensáveis para o diagnóstico de abdome agudo: hemograma, eletrocardiograma,\nradiografia, tomografia computadorizada e ultrassonografia. IV- A ultrassonografia, por sua\nfacilidade de acesso, por não necessitar contraste e nem expor o paciente à radiação, é geralmente\no exame de primeira escolha. Estão CORRETAS apenas as afirmativas:","options":{"A":"I e II.","B":"II e III.","C":"I e IV.","D":"I, III e IV."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-368164","number":"368164","sourceNumber":"368164","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente de 48 anos de idade, tabagista, uso habitual de bebidas alcoólicas, queixa-se\nde náuseas e dor abdominal tipo cólica em faixa\nsuperior, que irradia para o dorso. Ao exame físico,\napresenta icterícia leve. São solicitados estes exames de sangue: I. Amilase; II. Lipase; III.\nBilirrubina indireta; IV. Bilirrubina direta; V. Albumina. Os resultados laboratoriais esperados\nnesse\ncaso são elevação nos índices de","options":{"A":"I, II, III, apenas.","B":"III, IV e V, apenas.","C":"I, II e IV, apenas.","D":"I, II, III, IV e V."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-354094","number":"354094","sourceNumber":"354094","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente masculino de 65 anos, sem antecedentes prévios, chega ao pronto-socorro\ncom dor abdominal progressiva em quadrante\ninferior esquerdo 48 horas, associado a parada de\neliminação de gases e fezes com distensão abdominal. Submetido a tomografia de abdome total\nque diagnosticou diverticulite aguda Hinchey 2. Como pode ser descrita a tomografia desse\npaciente e qual o tratamento indicado?","options":{"A":"Borramento da gordura pericolônica, sem coleção, e antibioticoterapia.","B":"Abscesso pericolônico confinado, laparotomia e antibioticoterapia.","C":"Abscesso paracolônico, laparotomia e antibioticoterapia","D":"Abscesso pericolônico com extensão para pelve, drenagem percutânea e antibioticoterapia.","E":"Ruptura de abscesso pélvico, laparotomia e antibioticoterapia."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-373561","number":"373561","sourceNumber":"373561","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Mulher, 33 anos, branca, comerciante, está em tratamento de doença de Pott com\nacometimento de vértebras torácicas e lombares. Estava com a doença em remissão, quando\nqueixou-se de piora da dor local agora com irradiação para membros inferiores. Retornou a\napresentar febre e perdeu 6 quilos em 30 dias. Ao exame físico: emagrecida com abaulamento ao\nnível da transição toracolombar, dor a palpação e ausência de sinais flogísticos. Sem déficits\nneurológicos em membros inferiores. Presença de vários gânglios axilares, inguinais e cervicais,\npequenos, móveis, fibroelásticos e indolores. Abdome com dor à palpação difusa, mais localizada\nem planos profundos, à esquerda, e sem sinais de irritação peritoneal. Realizou a tomografia abaixo\npara elucidação diagnóstica. Assinale a principal hipótese diagnóstica.","options":{"A":"Pielonefrite xantogranulomatosa.","B":"Tuberculose renal.","C":"Abscesso de m. psoas.","D":"Infiltração entérica (tuberculose miliar)."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-335076","number":"335076","sourceNumber":"335076","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Um paciente com pancreatite aguda deteriora clinicamente e é submetido à aquisição\nde novas imagens. O exame de tomografia\ncomputadorizada revela achados de uma coleção\nlíquida consistente, com uma necrose pancreática infectada, que está aderida à parede gástrica\nposterior e próxima da cabeça pancreática. Nesse caso, o melhor tratamento é","options":{"A":"drenagem endoscópica.","B":"cistogastrostomia.","C":"cistojejunostomia Y de Roux.","D":"drenagem percutânea."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-346862","number":"346862","sourceNumber":"346862","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo feminino, 54 anos relata dor em cólica em quadrante superior direito\ndo abdome, há trinta dias. Segundo a paciente,\nhá doze horas houve piora da dor localizada,\nassociada à febre e a calafrios. Refere ainda anorexia e que não evacua há quatro dias. Assinale a\nalternativa que apresenta o PROVÁVEL diagnóstico dessa paciente.","options":{"A":"Abdome agudo vascular.","B":"Abdome agudo obstrutivo.","C":"Abdome agudo inflamatório.","D":"Abdome agudo hemorrágico."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-320448","number":"320448","sourceNumber":"320448","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Homem diabético em uso irregular das medicações, obeso, 45 anos, se apresenta ao\nhospital com dor mesogástrica crescente com irradiação para o dorso, associada a náuseas. Nega\nuso de álcool. Ao exame físico FC: 110 BPM, restante dos sinais vitais normais; abdome\ndiscretamente distendido e doloroso a palpação em região mesogástrica, sem irritação peritoneal,\nruídos hidroaéreos reduzidos. Laboratorio: amilase 420 U/I (VR < 132 U/L); lipase 1.800 (VR < 52\nU/L). USG de abdome: infiltração gordurosa do fígado, vesícula biliar normal, vias biliares sem\ndilatação, pâncreas discretamente aumentado de tamanho com presença de pequena quantidade\nde líquido peripancreatico. Qual das opções abaixo é a etologia mais provável para a pancreatite\ndesse paciente?","options":{"A":"Medicamentoso.","B":"Pancreas divisium.","C":"Auto-imune.","D":"Biliar.","E":"Hipertrigliceridemia."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-321186","number":"321186","sourceNumber":"321186","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo masculino, 25 anos, em acompanhamento de uma leucemia\nrecentemente tratada, relata dor abdominal há\ncerca de 48 horas, inicialmente difusa que se\nlocalizou na Fossa Ilíaca Direita (FID) e posteriormente difusa novamente. Exames laboratoriais da\nadmissão mostram: leucócitos totais: 15.500; Hemoglobina: 13,5gr/dl; urina rotina normal. Ao\nexame clínico apresenta FC: 98bpm, FR: 17irpm, abdome levemente distendido, com\ndescompressão dolorosa na FID. A radiografia de tórax em ortostatismo não mostra\npneumoperitônio e radiografia de abdome mostra alça sentinela na FID. Em relação ao caso clínico\ndescrito, é CORRETO afirmar que:","options":{"A":"A antibioticoterapia para gram positivos deve ser iniciada apenas após a laparotomia\nexploradora comprovar o diagnóstico de apendicite aguda,\npara evitar resistência bacteriana.","B":"Pacientes com imunodeficiências, como esse devem sempre passar por tentativa de tratamento\nclínico da possível apendicite aguda,\ndevido os maiores riscos do procedimento cirúrgico nesses\npacientes.","C":"Diante dos sinais e sintomas típicos para o diagnóstico de apendicite aguda, o tratamento mais\nadequado será encaminhamento imediato ao bloco cirúrgico, para realização da cirurgia, além de\niniciar antibioticoterapia.","D":"Para esse caso clínico se torna obrigatória a realização de tomografia computadorizada de\nabdome, antes da abordagem cirúrgica."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-314025","number":"314025","sourceNumber":"314025","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Sobre o diagnóstico de apendicite aguda em crianças, analisar os itens abaixo: I. Ao\nexame físico, o que mais chama a atenção, no\ninício, são fácies de sofrimento e postura do\npaciente - quieto, sem muita mobilidade, já que a movimentação desencadeia dor pela irritação\nperitoneal. II. Na fase inicial, o paciente apresenta tríade sintomática, caracterizada por dor\nperiumbilical, febre moderada e anorexia. III. As manobras palpatórias devem, idealmente, ser\niniciadas exatamente no ponto apendicular. Está(ão) CORRETOS(S):","options":{"A":"Somente os itens I e III.","B":"Somente o item III.","C":"Somente os itens I e II.","D":"Somente o item II.","E":"Somente o item I."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-313292","number":"313292","sourceNumber":"313292","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente de 42 anos, sexo masculino, assistente administrativo há 20 anos, casado,\ncaucasiano, diabético tipo II, sem alterações da pressão arterial e frequência respiratória,\ntaquicárdico (112bpm), provavelmente, por conta de dor abdominal intensa, Temperatura axilar\n38,8oC. Foi encaminhado pela Clínica Médica para Cirurgia Geral, chegando ao consultório, após\nexame físico, o Cirurgião considera Psoas Positivo. Qual manobra propedêutica realizada?","options":{"A":"Dor no quadrante inferior direito induzida pela palpação do quadrante inferior esquerdo.","B":"Dor provocada quando o examinador estende passivamente o quadril direito do paciente.","C":"Dor a descompressão, pesquisada na palpação profunda.","D":"Dor à descompressão brusca do ponto cístico.","E":"Aumento da sensibilidade quando os músculos da parede abdominal são contraídos."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-313293","number":"313293","sourceNumber":"313293","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Diante do caso, da questão anterior, o Cirurgião entende que Sinal de Psoas positivo é\num forte indicativo de:","options":{"A":"Colecistite aguda.","B":"Pancreatite aguda.","C":"Apendicite aguda.","D":"Pancreatite necro-hemorrágica.","E":"Ruptura esplênica."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-313294","number":"313294","sourceNumber":"313294","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Sobre os sinais semiológicos de abdome agudo inflamatório, o sinal de Dunphy é\ndescrito como:","options":{"A":"Diminuição global dos RHA.","B":"Dor abdominal ao tossir.","C":"Timpanismo em região hepática.","D":"Posição antálgica (flexão do joelho contra o quadril).","E":"Compressão retrógrada em flanco esquerdo com dor em FID."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-305010","number":"305010","sourceNumber":"305010","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Considere que um paciente de 69 anos de idade apresenta-se com quadro de dor\nabdominal inespecífica há duas semanas,\nacompanhado de febre quase diariamente. O hábito\nintestinal está normal. Ao exame físico, encontra-se hemodinamicamente estável, vígil e orientado.\nÉ realizada tomografia computadorizada que demonstra abscesso de, aproximadamente, 10 cm na\nfossa ilíaca direita, em topografia de íleo terminal, sendo sugestiva de abscesso apendicular. Nesse\ncaso, é correto afirmar:","options":{"A":"A drenagem percutânea e a antibioticoterapia são mais indicadas que a cirurgia.","B":"A técnica de apendicectomia aberta é indicada por ter menos complicações que a cirurgia\nlaparoscópica.","C":"A tomografia computadorizada não tem boa acurácia para esse diagnóstico.","D":"A apresentação clínica não é compatível com o diagnóstico de apendicite."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-291949","number":"291949","sourceNumber":"291949","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente J.M.S. mulher 27 anos admitida no Pronto Socorro com quadro de abdômen\nagudo. Início da dor há cerca de 8 horas em\nandar inferior do abdômen principalmente a direita.\nNega vômitos, mas está um pouco nauseada. Relata também leve corrimento claro vaginal, há uns\ndias. Na história pregressa, faz uso de anticoncepcional de forma irregular e está casada há dois\nanos. No exame físico está com sudorese leve, corada no limiar, eupneica e tax. de 37,4Cº, PA:\n100X50mmHg e FC: 108bpm, abdômen está um pouco distendido com dor em andar inferior e\nBlumberg positivo a direita. Sinal de Chandelier negativo. Foi ao banheiro para colher o exame de\nurina solicitado e apresentou uma síncope quando se levantou. Exame laboratorial mostrou\nleucocitose de 12.500 leucócitos ainda sem resultado do diferencial e HB de 11,2gr/dl com HT de\n\n31. PCR está aumentado. Ultrassom mostrou líquido na cavidade. Considerando o caso descrito é\nCORRETO afirmar que o diagnóstico mais provável e a conduta para essa paciente deve ser:","options":{"A":"Gravidez ectópica rota indicar cirurgia.","B":"Doença inflamatória pélvica iniciar antibioticoterapia.","C":"Apendicite aguda confirmar com tomografia.","D":"Infecção do trato urinário e solicitar exame de urina rotina e gram de gota."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-306734","number":"306734","sourceNumber":"306734","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"J.L.A, 56 anos, tabagista e etilista de longa data, dá entrada no hospital com dor\nintensa em andar superior do abdome e\nvômitos. Foram identificados níveis elevados de amilase e\nlipase. Os demais exames laboratoriais demonstraram glicemia = 230mg/dL, desidrogenase lática =\n300UI/L, TGO = 300UI/L, TGP = 320UI/L, hemoglobina = 12g/dL, leucócitos = 17.500 cels/mm³ e\nplaquetas = 180.000/mm3. Assinale a alternativa correta com relação ao caso apresentado.","options":{"A":"O paciente apresenta quadro de pancreatite aguda grave e deverá receber tratamento\nnutricional com preferência para a nutrição enteral em relação à nutrição parenteral.","B":"Por se tratar de um caso grave de pancreatite aguda, o paciente deverá ser tratado com dieta\nzero por pelo menos 7 dias, hidratação vigorosa com solução balanceada e antibioticoterapia.","C":"Neste momento ainda não é possível definir a gravidade do quadro, mas o paciente apresenta\npancreatite aguda e deverá receber tratamento com hidratação, analgesia e dieta zero.","D":"Após 48 horas da admissão, deverão ser avaliados os critérios de RANSON para definição da\ngravidade do quadro, caso apresente sinais de gravidade, deverá então ser internado em UTI."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-314086","number":"314086","sourceNumber":"314086","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação à apendicite em pediatria, assinalar a alternativa CORRETA:","options":{"A":"É a causa mais comum de abdome agudo em crianças em idade pré-escolar e escolar.","B":"O sinal de Rovsing é caracterizado por dor à descompressão brusca do ponto de McBurney.","C":"O sinal de Blumberg é caracterizado por dor em fossa ilíaca direita por compressão em fossa\nilíaca esquerda.","D":"Sinal de Giordano e Jobert positivos confirmam apendicite aguda.","E":"Sinal de Cullen positivo confirma apendicite aguda."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-287847","number":"287847","sourceNumber":"287847","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação à Diverticulite Aguda, analisar os itens abaixo: I. O estágio II da\nClassificação de Hinchey corresponde a grande\nabcesso que se estende para pelve. II. Devido a\nsua localização típica, faz diagnóstico diferencial com a colite isquêmica: a colite\npseudomembranosa e a retocolite ulcerativa. III. No estágio IV da Classificação de Hinchey, a taxa\nde mortalidade chega a 95%. Está(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e II.","D":"Somente os itens I e III.","E":"Todos os itens."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-287850","number":"287850","sourceNumber":"287850","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação à Isquemia Mesentérica Aguda, analisar os itens abaixo: I. Geralmente,\napresenta-se como dor mesogástrica ou\nperiumbilical. II. Arritmias, insuficiência cardíaca,\naterosclerose, vasculites e infarto do miocárdio recente são os principais fatores de risco e tem,\ncomo principal prevalência, o início da idade adulta. III. A mortalidade é superior a 60%. Está(ão)\nCORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e III.","D":"Somente os itens II e III.","E":"Todos os itens."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-287851","number":"287851","sourceNumber":"287851","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação à dor e sua caracterização, assinalar a alternativa CORRETA:","options":{"A":"Inflamação, distensão e isquemia do peritônio visceral ou do mesentério causam um tipo de dor\nprofunda, vaga e pouco localizada, conhecida como dor referida.","B":"A dor visceral é mediada pelo sistema nervoso autônomo.","C":"A dor visceral é aquela sentida em um local distante de onde se originou.","D":"A dor visceral é bem localizada, intensa e aguda, pois é transmitida por inervação somática.","E":"A dor parietal é profunda, vaga e pouco caracterizada."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-287852","number":"287852","sourceNumber":"287852","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação à apendicite, assinalar a alternativa CORRETA:","options":{"A":"Os principais agentes encontrados nos quadros de apendicite são Escherichia coli e Bacteroides\nfragili.","B":"A dor abdominal oriunda da apendicite melhora com a eliminação de flatos ou com evacuação.","C":"Se associado à dor abdominal ocorrer anorexia, está afastado o quadro de apendicite.","D":"A dor abdominal oriunda da apendicite guarda relação com atividade física ou posição.","E":"A ocorrência de diarreia é muito comum na fase inicial do quadro."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-287853","number":"287853","sourceNumber":"287853","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Assinalar a alternativa cujas patologias mais se relacionam à dor em hipocôndrio\ndireito:","options":{"A":"Cólica biliar, colecistite, colangite e hepatite.","B":"Cólica biliar, apendicite, colangite e hepatite.","C":"Diverticulite, apendicite, colangite e hepatite.","D":"Diverticulite, apendicite, isquemia mesentérica e hepatite.","E":"Diverticulite, apendicite, colecistite e colangite."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-283905","number":"283905","sourceNumber":"283905","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Durante o exame abdominal, você observa um sinal de hematoma periumbilical. Na\nsemiologia, qual nome desse sinal?","options":{"A":"Sinal de Aaron.","B":"Sinal de Charcot.","C":"Sinal de Cullen.","D":"Sinal de Grey-Turner.","E":"Sinal de Danforth."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-283931","number":"283931","sourceNumber":"283931","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Homem, 62 anos, hipertenso e dislipidêmico desde 55 anos, etilista desde os 50 anos.\nIniciou ingesta alcóolica após demissão de seu trabalho. No último ano, está ingerindo 1 garrafa de\ncachaça a cada 2 dias, segundo o relato da esposa. É trazido à consulta devido quadro de dor\nabdominal, sensação de estufamento abdominal, náuseas e vômitos, dor em membros inferiores.\nAcompanhante relata hábito intestinal regular. A revisão rápida de exames solicitados em consulta\nanterior revela hipertrigliceridemia com valores de triglicerídeos de 958 mg/dL. Qual a hipótese\ndiagnóstica mais provável?","options":{"A":"Síndrome de Wernicke-Korsakoff.","B":"Volvo intestinal.","C":"Pancreatite aguda.","D":"Síndrome de Aldoff.","E":"Parasitose intestinal."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-255628","number":"255628","sourceNumber":"255628","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação à apendicite aguda, MARQUE A CORRETA:","options":{"A":"A tríade sintomática é caracterizada por dor periumbilical, febre moderada e anorexia aparecem\nem somente 50% dos casos.","B":"Os resultados normais de hemograma não auxiliam na exclusão do diagnóstico.","C":"É a segunda causa mais frequente de abdome agudo cirúrgico da criança.","D":"A adenite mesentérica, por ser infrequente, não é um diagnóstico diferencial possível."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-255630","number":"255630","sourceNumber":"255630","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Tadeu, 55 anos, apresenta-se no serviço de urgência com dor em quadrante inferior\nesquerdo do abdome. Sobre os achados que\naumentam a suspeição para diverticulite, MARQUE A\nCORRETA:","options":{"A":"Hipotermia","B":"Diarréia","C":"Sangramento retal","D":"Distensão abdominal"},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-246372","number":"246372","sourceNumber":"246372","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Homem de 60 anos, com dor abdominal de início no flanco esquerdo há 3 dias, chegou\nao pronto-socorro com quadro de dor abdominal\ndifusa. Ao exame físico: palidez, FC: 110 bpm, PA:\n100x70 mmHg, dor e defesa voluntária da musculatura abdominal na parte inferior esquerda do\nabdome. Exames laboratoriais: Hematócrito 35% / Hemoglobina 11,6 mg/dl / Leuco 19380\n(mielócitos 0%/ metamielócitos 0%/ bastões 14%/ segmentados 57%/ eosinófilos 0% / linfócitos\n22%/ monócitos 7%) PLQ 255.000 mm³ PCR 23,9. Tomografia computadorizada de abdome com\nespessamento parietal intestinal e identificação do divertículo inflamado em sigmoide com abscesso\npericolônico medindo 8 x 10 cm. Sobre o caso apresentado, a classificação conforme Hinchey e a\nmelhor conduta são, respectivamente:","options":{"A":"Hinchey 1; tratamento cirúrgico","B":"Hinchey 2; drenagem percutânea","C":"Hinchey 3; sigmoidectomia","D":"Hinchey 4; drenagem aberta"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-234438","number":"234438","sourceNumber":"234438","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Sobre a apendicite aguda, assinale a alternativa CORRETA:","options":{"A":"A diminuição de ingestão de fibras é fator de risco para desenvolver apendicite aguda.","B":"O fecalito é causa da obstrução em mais de 80% dos casos.","C":"A dor inicial, mal localizada, se deve a distensão do orgão e dura cerca de 1 hora.","D":"O sinal do obturador, dor a rotação interna da coxa, ocorre em pacientes com apendicite\nretrocecal."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-234439","number":"234439","sourceNumber":"234439","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente de 35 anos, masculino, retorna no seu consultório para controle pós\ninternação de um quadro de pancreatite aguda\nalcóolica há cerca de 6 semanas. Paciente se\nencontra estável e no momento assintomático. Relata estar se alimentando melhor, sem ingerir\nbebida alcóolica e em acompanhamento psiquiátrico. Ele traz junto uma tomografia que foi\nsolicitada na consulta anterior, de controle do quadro apresentado e que mostra uma lesão cística\nde 6 cm no andar superior do abdômen. Considerando o caso descrito, assinale a alternativa que\napresenta a conduta MAIS ADEQUADA a ser tomada.","options":{"A":"Como se trata de uma coleção líquida deve ser puncionada e esvaziada para evitar\ncomplicações.","B":"Como já tem 6 semanas a conduta é cirúrgica e indica a necessidade de uma cistogastrostomia.","C":"Como o paciente está assintomático a lesão pode ser observada e acompanhada clinicamente.","D":"O melhor tratamento nesse caso deve ser a drenagem endoscópica."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-234440","number":"234440","sourceNumber":"234440","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Sr. Carlos Alberto 65 anos é admitido no pronto-socorro com dor abdominal há cerca de\n36 horas e piora progressiva. Relata\nlocalização em fossa ilíaca esquerda onde apresenta sinal de\nBlumberg. Não tem febre e tem bom estado geral. Paciente hipertenso e utiliza diuréticos. Sobre o\ncaso descrito, assinale a alternativa CORRETA:","options":{"A":"O diagnóstico é de diverticulite aguda Hinchey 1.","B":"O paciente deve ser encaminhado para internação e cirurgia e no mesmo dia para colectomia\nesquerda.","C":"O clister glicerinado pode auxiliar na melhora da dor desse paciente.","D":"O tratamento clínico está indicado com antibioticoterapia para gram negativos e anaeróbios e\nobservação clínica."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-232151","number":"232151","sourceNumber":"232151","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em pacientes com pancreatite aguda, o aumento da amilasemia é um fator importante\npara o diagnóstico, porém existem outras\ncausas que podem cursar com essa condição e\nassociar-se com dor abdominal, muitas vezes dificultando o diagnóstico correto. Assinale a\nassertiva que contenha causas de hiperamilasemia:","options":{"A":"Carcinoma pancreático, cetoacidose diabética, angiodisplasia colônica.","B":"Apendicite aguda, carcinoma pancreático, tireoidite.","C":"Cirrose hepática, úlcera péptica perfurada, prenhez tubária.","D":"Pênfigo bolhoso, insuficiência renal, parotidite.","E":"Coledocotlitíase, pneumonia, obstrução intestinal."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-243060","number":"243060","sourceNumber":"243060","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Qual dos itens seguintes mostrou diminuir a incidência de abscesso pancreático em\npacientes com pancreatite necrotizante grave?","options":{"A":"antibióticos profiláticos.","B":"exame frequente de imagens com amostragem percutâneas de novas coleções e fluidos.","C":"nutrição parenteral.","D":"nutrição enteral.","E":"abordagem cirúrgica precoce."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-196809","number":"196809","sourceNumber":"196809","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Segundo o sistema de pontuação de Alvarado Modificado para a Apendicite Aguda, a\npresença de sensibilidade na fossa ilíaca direita e a leucocitose >10.000, corresponde a pontuação\ntipo:","options":{"A":"1","B":"2","C":"3","D":"4"},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-199608","number":"199608","sourceNumber":"199608","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação à pancreatite aguda assinale a alternativa CORRETA.","options":{"A":"O diagnóstico de pancreatite aguda é estabelecido na presença de dor abdominal característica\ne níveis séricos de amilase e/ou lipase acima\nde duas vezes o limite superior da normalidade.","B":"A tomografia computadorizada do abdome utilizando contraste endovenoso permite avaliar com\nprecisão a presença e a extensão da necrose pancreática quando realizada precocemente, antes\ndo 3° dia do início do quadro.","C":"De acordo com os critérios de Atlanta, revisados em 2013, a presença de falência orgânica que\npersiste por mais de 48 horas caracteriza a presença de pancreatite aguda grave.","D":"Pacientes com pancreatite aguda grave que apresentam necrose pancreática devem receber\nantibioticoprofilaxia com objetivo de prevenir complicações infeciosas."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-212977","number":"212977","sourceNumber":"212977","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente de 36 anos, sexo feminino, procura o hospital com quadro de dor em andar\nsuperior do abdome, de forte intensidade,\ncom irradiação para dorso e vômitos com início há 1 dia.\nOs exames mais importantes para elucidar o DIAGNÓSTICO e a ETIOLOGIA MAIS PROVÁVEL,\nsão respectivamente:","options":{"A":"Hemograma e tomografia computadorizada do abdome.","B":"PCR e ultrassonografia do abdome.","C":"Amilasemia e ultrassonografia do abdome.","D":"Amilasemia e tomografia computadorizada do abdome.","E":"Hemograma e ultrassonografia do abdome."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-212953","number":"212953","sourceNumber":"212953","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente com 42 anos, feminino, com dor abdominal há 24hs em abdome superior e\nirradiação para dorso. Na admissão, apresenta fácies de dor, taquicárdica, taquipneica, agitada,\ncom dor forte à palpação do abdome superior. PA 110 x 70 mmHg, FC 108 bpm, SATO2 88% em\nar ambiente, sendo então administrado O2 sob máscara de Venturi 6 L/min (com FiO2 de 40%).\nLeucócitos de 13.500, PCR 228, glicose 118, amilase 2.281, TGO 118, TGP 90, FA 138, GGT 152,\nbilirrubina total 1,1. Gasometria arterial (após O2 suplementar): pH: 7,34 / pCO2: 33 / pO2: 80 /\nSatO2: 95% / HCO3- : 18 / BE: -2. Assinale o critério clínico/laboratorial que corrobora a\nclassificação de gravidade previamente indicada:","options":{"A":"Leucocitose.","B":"PCR elevado.","C":"Amilase.","D":"Taquicardia.","E":"Relação PaO2/FiO2."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-215111","number":"215111","sourceNumber":"215111","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em relação a dor abdominal de tratamento cirúrgico em idosos, podemos dizer que são\nfrequentes as patologias abaixo, EXCETO:","options":{"A":"Torção de ovário.","B":"Isquemia Mesentérica.","C":"Ruptura de Aneurisma de Aorta.","D":"Vólvulo Intestinal.","E":"Colecistite Aguda."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-212964","number":"212964","sourceNumber":"212964","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Homem, 65 anos, com história de colelitíase assintomática, apresenta dor em barra e\nvômitos de início há 5 dias. Após dar entrada no hospital, exames laboratoriais evidenciaram\nleucocitose com 14.000 leucócitos por mm³ sem desvio, amilase 900 U/L, lipase 1900 U/L e lactato\n1,8 mg/dl. TC de abdome solicitada pelo clínico do plantão evidenciou pâncreas aumentado, com\nborramento da gordura e pequenas coleções peripancreáticas e imagem sugestiva de pequena\nárea de necrose em cauda de pâncreas. Com esse resultado, é então solicitado um parecer para\ncirurgia geral para avaliar o paciente. Em relação ao tratamento inicial do paciente, assinale a\nalternativa mais adequada.","options":{"A":"Dieta oral zero, hidratação venosa, analgesia e demais sintomáticos, ceftriaxona 2 g EV dose\ndiária.","B":"Dieta oral zero, hidratação venosa, analgesia e demais sintomáticos.","C":"Dieta oral zero, hidratação venosa, laparotomia com necrosectomia e drenagem dos abscessos.","D":"Punção venosa profunda para nutrição parenteral total, hidratação venosa, analgesia e demais\nsintomáticos.","E":"Passagem de sonda nasoentérica por endoscopia digestiva, nutrição enteral, hidratação venosa,\nanalgesia e demais sintomáticos."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-199496","number":"199496","sourceNumber":"199496","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A paciente R.F.T., 47 anos, apresentou quadro de pancreatite aguda e foi internada\ncom 2 critérios de Ranson médicos após 48\nhoras. Depois de uma semana, recebeu alta. Duas\nsemanas após sua alta, retornou ao hospital com quadro de dor leve e vômitos. Realizada\ntomografia de abdome que apresentou sinais de aumento na área pancreática, borramento da\ngordura peripancreática, associada à coleção líquida adjacente. Considerando o caso descrito,\nassinale a alternativa que apresenta a conduta CORRETA a ser adotada para essa paciente.","options":{"A":"Tratamento conservador.","B":"Punção percutânea com agulha fina da coleção líquida.","C":"Punção e drenagem percutânea da coleção líquida.","D":"Laparotomia para drenagem ampla da coleção."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-212897","number":"212897","sourceNumber":"212897","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Mulher 74 anos, hipertensa, diabética, com história de constipação crônica, foi levada\nao PS por familiares devido distensão\nabdominal com parada de eliminação de flatos e fezes há 3\ndias. Durante a avaliação inicial, exames laboratoriais apresentando apenas discreta anemia (Hb 10\ng/dl) e leucocitose (13.000/mm³) com desvio (10% de bastões). TC de abdome evidencia distensão\ncolônica até o cólon descendente, diversos divertículos em todo o cólon esquerdo, borramento de\ngordura em torno de todo o sigmoide, com duas coleções justa parede do sigmoide, uma medindo\n1,1 x 0,7 cm e outra 1,8 x 2,1 cm. Qual a classificação tomográfica (Hinchey) e o tratamento\ninicial?","options":{"A":"Hinchey I. Antibioticoterapia.","B":"Hinchey II. Antibioticoterapia.","C":"Hinchey III. Laparotomia com retossigmoidectomia à Hartmann.","D":"Hinchey I. Laparotomia com retossigmoidectomia com reconstrução primária.","E":"Hinchey II. Laparotomia com retossigmoidectomia com reconstrução primária."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-212908","number":"212908","sourceNumber":"212908","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Com relação aos divertículos cólicos, assinale a alternativa correta:","options":{"A":"Os divertículos respondem por mais de 65% das hemorragias baixas volumosas.","B":"Entre os pacientes com divertículos, cerca de 50% irão experimentar um episódio de\nsangramento em suas vidas.","C":"Dos pacientes que sangram por divertículos, 2/3 apresentam sangramento volumoso.","D":"O Cólon direito é fonte do sangramento em 50% a 90% dos pacientes.","E":"O Cólon sigmoide é principal fonte de sangramento."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-202749","number":"202749","sourceNumber":"202749","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A dosagem de amilase no sangue tem se mostrado um marcador significativo para o\ndiagnóstico de pancreatite aguda. Sobre a amilasemia, é correto afirmar:","options":{"A":"Seus valores têm correlação direta com o grau de necrose pancreática na pancreatite aguda.","B":"Hiperamilasemia permanece presente com frequência até o 12° dia após o início dos sintomas\nde pancreatite aguda.","C":"Macroamilasemia é um achado comumemente presente na pancreatite aguda medicamentosa.","D":"10% dos pacientes com pancreatite aguda fatal podem apresentar níveis de amilase normais ou\nquase normais.","E":"Sua presença associada ao quadro de pneumoperitônio é patognomônica de úlcera péptica\nperfurada."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-199559","number":"199559","sourceNumber":"199559","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Escolar, masculino, 7 anos de idade, hígido previamente, iniciou dor abdominal,\nlocalizada em região epigástrica, de forte\nintensidade, associada à posição antálgica (flexão de\nquadril e joelhos), há 2 dias. Evoluiu com vômitos (3 episódios), distensão abdominal e febre, nas\núltimas 24 horas. Refere queda no banheiro da casa da avó com trauma de abdome em pia do\nbanheiro há 3 dias. Ao exame apresenta-se com palidez cutaneomucosa, levemente desidratado,\neupneico, eucardico, com dor intensa à palpação de andar superior do abdome. Mediante este\nquadro, qual seria sua principal hipótese e qual seria o exame de escolha para confirmação\ndiagnóstica?","options":{"A":"Pancreatite aguda. Amilase, lipase séricas.","B":"Cisto de colédoco. Aminotransferases e ultrassonografia abdominal.","C":"Hepatite aguda. Aminotranferases, bilirrubinas e ultrassonografia abdominal.","D":"Rotura de baço. Ressonância nuclear magnética de abdome para avaliar intervenção cirúrgica."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-202757","number":"202757","sourceNumber":"202757","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Diverticulose colônica está presente em uma parcela significativa da população. Sobre\no sangramento digestivo decorrente dessa entidade\npatológica, podemos afirmar que:","options":{"A":"50% dos pacientes com diverticulose colônica apresentarão sangramento em algum momento\nde suas vidas.","B":"O melhor método de diagnóstico e tratamento é a arteriografia com embolização.","C":"50% é a taxa de mortalidade dos pacientes submetidos à colectomia subtotal de urgência.","D":"50% dos pacientes apresentarão ressangramento em um período de 10 anos.","E":"A localização do sítio de sangramento não é essencial."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-199577","number":"199577","sourceNumber":"199577","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente masculino, 20 anos, sem comorbidades, deu entrada no pronto-socorro com\ndor abdominal em andar inferior, na fossa\nilíaca direita, que vem piorando há dois dias, associado a\nhiporexia e parada de eliminação de flatos. Ao exame físico apresenta frequência cardíaca de 88\nbpm, frequência respiratória de 16 irpm, estável hemodinamicamente, com descompressão brusca\npositiva (blumberg positivo).O quadro se manteve apesar da analgesia e hidratação. Leucograma,\namilase, creatinina e íons normais. Radiografia de abdome normal. Qual a conduta mais adequada,\npensando no diagnóstico mais provável:","options":{"A":"Laparoscopia diagnóstica.","B":"Ressonância nuclear magnética de abdome.","C":"Internação, antibiótico e observação clínica.","D":"Alta com sintomáticos e retorno para reavaliação em 24 horas."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-174391","number":"174391","sourceNumber":"174391","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Sobre o abdome agudo inflamatório em gestantes, assinale a alternativa correta:","options":{"A":"Diverticulite aguda deve sempre ser tratada com realização de sigmoidectomia à Hartmann em\ngrávidas.","B":"Distúrbios do trato biliar são as causas mais comuns de indicação cirúrgica na gravidez.","C":"Volvo de sigmóide é a causa mais comum de obstrução intestinal em pacientes grávidas.","D":"A apendicectomia videolaparoscópica está contra-indicada na gravidez.","E":"O risco global de aborto ou trabalho de parto pré-termo, após uma apendicectomia na gravidez,\nencontra-se em torno de 4 a 6%."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-155350","number":"155350","sourceNumber":"155350","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente de 57 anos, sexo feminino, é admitida pela manhã com dor abdominal intensa\nque durou por toda a noite. A dor teve\ninício na véspera, após ela ter chegado de uma festa.\n\nComeçou gradual, mas tornou-se constante e intensa, de localização epigástrica, irradiando para a\nregião lombar esquerda. Posteriormente, surgiram vômitos esverdeados e náuseas. No exame\nfísico, a temperatura axilar era de 37,7°C; PA = 90 x 60 mmHg; FC = 119 bpm; FR = 25 irpm. Há\ndistensão abdominal, dor à palpação profunda do epigástrio e peristalse de difícil detecção. O toque\nretal foi normal. Assinale a opção que indica os exames bioquímicos que serão mais úteis para\nestabelecer o diagnóstico desse caso:","options":{"A":"Glicose, ureia e creatinina séricas.","B":"Aminotransferases séricas (AST e ALT).","C":"Sódio e potássio urinário.","D":"Amilase e lipase séricas.","E":"Pesquisa de cristais no sedimento urinário e sódio sérico"},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-162596","number":"162596","sourceNumber":"162596","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Com relação à pancreatite aguda, assinale a alternativa CORRETA:","options":{"A":"A colangiopacreatografia endoscópica retrógrada está indicada em todos os casos de\npancreatite.","B":"Abuso de álcool, trauma, hipertrigliceridemia, hipocalcemia, hipercalcemia e cálculos biliares\nsão\npossíveis causas de pancreatite.","C":"A cirurgia está indicada para todos os casos de pancreatite necrosante.","D":"Antibioticoterapia precoce está indicada em todos os casos de pancreatite.","E":"Níveis de amilase não se correlacionam com gravidade e prognóstico na pancreatite aguda."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-148595","number":"148595","sourceNumber":"148595","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente do sexo masculino, 53 anos, etilista crônico, foi internado na enfermaria de\ngastroenterologia de um Hospital Universitário apresentando dor em andar superior de abdome,\niniciada há cerca de três anos, mas que se tornaram mais intensas nos últimos seis meses, com\npiora pós alimentação. Refere emagrecimento não quantificado. Realizou tomografia de abdome\nque evidenciou calcificações no parênquima pancreático e dilatação do ducto de Wirsung. Qual a\nmelhor conduta para esse paciente?","options":{"A":"Complementar investigação com a realização de colangiopancreatografia retrógrada\nendoscópica.","B":"Complementar investigação com a realização de ultrassonografia endoscópica.","C":"Complementar investigação com a realização de colangioressonância.","D":"Iniciar reposição de enzimas pancreáticas.","E":"Prescrever dieta zero e hidratação endovenosa."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-162528","number":"162528","sourceNumber":"162528","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente, 70 anos, portadora de doença diverticular de cólon sigmoide, iniciou há 05\ndias dor em baixo ventre com parada de evacuação e pouca eliminação de flatos. Há 24 horas\napresentou disúria, distensão abdominal, parada de eliminação de gases e fezes, dor difusa à\npalpação abdominal, sendo mais intensa em baixo ventre. Foi submetida à tomografia de abdome\nque evidenciou Diverticulite Aguda Hinchey II. Qual a conduta imediata mais adequada?","options":{"A":"Antibioticoterapia endovenosa e internação.","B":"Antibioticoterapia e colonoscopia.","C":"Antibioticoterapia e Retossigmoidectomia.","D":"Retossigmoidectomia à Hartmann.","E":"Colonoscopia descompressiva."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-162532","number":"162532","sourceNumber":"162532","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente P.M., 38 anos, feminina, peso: 85 kg, altura: 1,54 m, deu entrada pelo\npronto-socorro de hospital terciário com\nquadro de dor abdominal em epigástrio e hipocôndrio\ndireito, náuseas, de início há 12 horas, sem melhora com analgésicos de uso habitual. Nega\nlibação alcoólica ou alimentação copiosa. À admissão no P.S. paciente corada, hidratada, afebril,\n\nanictérica, F.C.: 86bpm, eupneica em ar ambiente, abdome globoso, ruídos hidroaéreos presentes\ne normoativos, timpânico, dor abdominal à palpação\nprofunda em epigástrio e hipocôndrio direito,\ndor à descompressão em epigástrio e hipocôndrio direito. Exames laboratoriais: hemoglobina\n12,3g/dl; leucócitos 10.200 sem desvio, amilase 105, lipase 68, bilirrubina total 0,68, TGO 35, TGP\n58, fosfatase alcalina 120, Gama GT 54; DHL 240. Diante do quadro, qual principal suspeita\ndiagnóstica e melhor exame de imagem a ser solicitado?","options":{"A":"Doença ulcerosa péptica perfurada; RX de abdome agudo.","B":"Pancreatite aguda; tomografia de abdome.","C":"Colecistite aguda; ultrassonografia de abdome.","D":"Doença ulcerosa péptica; endoscopia.","E":"Colecistite aguda; RX de abdome agudo."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-162537","number":"162537","sourceNumber":"162537","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Qual dos sinais abaixo não diz respeito ao quadro de apendicite aguda?","options":{"A":"Lennander.","B":"Rovsing.","C":"Blumberg.","D":"Homans.","E":"Sinal do Ileopsoas."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-162583","number":"162583","sourceNumber":"162583","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente T.M.T., 29 anos, masculino, deu entrada no pronto-socorro com quadro de dor\nepigástrica importante, com irradiação para flancos, de início há cerca de 8 horas, após\nalimentação copiosa em churrasco no final de semana e ingestão de bebidas alcoólicas. Na\navaliação inicial foram feitos os seguintes exames: hemoglobina 13,5g/dl; leucócitos 17.000;\nplaquetas 348.000; amilase 2357; lipase 1369; TGO 264; TGP 105; fosfatase alcalina 102; gama\n\nGT 93; bilirrubina total 1,7; bilirrubina direta 0,9; glicemia 218; cálcio 9,0 LDH 415, ureia 52,\ncreatinina 1,06, PCR 316. Diante do diagnóstico\nde pancreatite aguda de provável etiologia\nalcoólica, qual a classificação de gravidade segundo os critérios de Ranson e quais critérios foram\npositivos?","options":{"A":"Leve ? 2 pontos, LDH e Glicemia.","B":"Grave ? 2 pontos, amilase e PO2.","C":"Grave ? 4 pontos, Leucócitos, glicemia, PCR e Cálcio.","D":"Grave ? 4 pontos, Leucócitos, TGO, glicemia e LDH.","E":"Grave ? 3 pontos, LDH, TGO e Cálcio."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-162587","number":"162587","sourceNumber":"162587","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente encontra-se com amilase elevada após passados 4 semanas de resolução de\npancreatite aguda por causa biliar. Qual provável diagnóstico?","options":{"A":"Pseudocisto pancreático.","B":"Tumor de paratireoide.","C":"Neoplasia de papila duodenal.","D":"Cálculo residual.","E":"Fístula pancreática."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-155395","number":"155395","sourceNumber":"155395","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente feminina, 50 anos, portadora de litíase biliar, sem outras comorbidades, é\ninternada de urgência em UTI devido quadro de pancreatite aguda grave (clássico quadro de\nSIRS), mantida em dieta zero, aguardando avaliação do cirurgião. Baseando-se nisso, qual dos\nachados abaixo se espera encontrar:","options":{"A":"Diminuição sérica da glicose.","B":"Diminuição sérica da pró-calcitonina.","C":"Diminuição sérica da albumina.","D":"Diminuição sérica ferritina.","E":"Diminuição sérica de glucagon."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-148604","number":"148604","sourceNumber":"148604","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente jovem, 23 anos, masculino, atendido em Unidade Básica pelo médico\ngeneralista, com relato de hiporexia, náusea\ne dor em região de fossa ilíaca direita. Ao exame\nencontra-se levemente desidratado, frequência cardíaca e respiratória normal, com descompressão\nbrusca dolorosa a palpação de fossa ilíaca direita, fortemente sugestiva de irritação peritoneal e\nalta probabilidade de apendicite aguda. Qual o próximo passo?","options":{"A":"Dieta oral zero, analgesia, hidratação e raio X de abdômen em AP.","B":"Dieta oral zero, analgesia, hidratação e ultrassonografia abdominal.","C":"Dieta oral zero, analgesia, hidratação e tomografia computadorizada de abdômen.","D":"Dieta oral zero, analgesia, hidratação e transferência para tratamento cirúrgico.","E":"Analgesia e alta hospitalar."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-148535","number":"148535","sourceNumber":"148535","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Pacientes com quadro clínico de pancreatite aguda biliar, sem pontuação de gravidade\npelos critérios de Ranson, devem ser\nsubmetidos à colecistectomia preferencialmente:","options":{"A":"Três meses após o processo inflamatório cessar.","B":"Entre 15 e 30 dias após o processo inflamatório cessar.","C":"Nas primeiras 24 horas da admissão hospitalar.","D":"Na mesma internação, logo após a melhora da pancreatite.","E":"Na mesma internação, imediatamente após a realização de papilotomia endoscópica."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-126886","number":"126886","sourceNumber":"126886","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"L.M.O.L., 35 anos, submetida a tratamento cirúrgico devido à pancreatite aguda\nnecro-hemorrágica, evolui no 10° dia de pós-operatório, com febre e calafrios associado à\ntaquicardia. Ao exame físico, apresentou dor intensa do epigástrio e massa palpável em mesma\nlocalização. Realizados exames laboratoriais, evidenciou-se leucocitose e elevação moderada de\n\namilase. Considerando-se o caso descrito, assinale a alternativa que apresenta o diagnóstico MAIS\nprovável:","options":{"A":"Pseudocisto pancreático.","B":"Abscesso pancreático.","C":"Reincidência do quadro da pancreatite.","D":"Abscesso subfrênico."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-137805","number":"137805","sourceNumber":"137805","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Paciente sexo feminino, 35 anos, natural de Marilândia, queixando-se de dor\nepigastralgia de forte intensidade\nirradiando para região retroesternal, com início há 4 horas. Refere\noutros sintomas associados como náuseas e vômitos. Relata grande ingesta de alimentos na noite\nanterior. A paciente é obesa mórbida, tabagista, hipertensa e diabética. Faz uso regular de\natenolol,\nhidroclorotiazida, glibenclamida e metformina. Nega etilismo. Ao exame paciente em regular estado\ngeral, corada, hidratada, lúcida e orientada ACV: RCR2T BNF sem sopros, PA: 170 x 100 mmHg;\nFC: 110 bpm; Abdome globoso em avental, doloroso a palpação superficial e profunda em região\nepigástrica. Exames laboratoriais: hemoglobina:17,1 / leucócitos:23000 / plaquetas:290000 /\nglicemia:155 TGO: 20 / DHL: 200 / creatinina:0,9 / ureia: 20 / amilase:1430 / lipase 430 / CK: 230 /\nCK-MB:17 / troponina < 0,1. RX de tórax apresentando derrame pleural em base esquerda ECG:\nbloqueio de ramo direito TC de Abdome; Fígado e vias biliares sem alterações, rins tópicos de\ntamanho normal e com preservação da relação cortiço medular, edema em pâncreas de moderada\nintensidade, baço de tamanho e topografia habituais, presença de pequena quantidade de líquido\nlivre em cavidade abdominal. Qual o diagnóstico do paciente acima?","options":{"A":"Infarto agudo do miocárdio.","B":"Pneumonia comunitária.","C":"Pancreatite aguda leve.","D":"Septicemia grave.","E":"Tromboembolismo pulmonar."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-137807","number":"137807","sourceNumber":"137807","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"A pancreatite aguda tem como principais características:","options":{"A":"A origem mais frequente é traumática, nessa forma tem baixa morbidade e mortalidade e deve\nser\n\noperada sempre tardiamente.","B":"Tem como causa frequente o uso de anti-inflamatórios não hormonais, geralmente evolui com\nnecrose pancreática e deve ser sempre tratada com cefalosporina de segunda geração.","C":"É uma doença frequente em jovens do sexo masculino, geralmente associado a doença\nendócrina e exócrina.","D":"A causa mais frequente é a litíase biliar, em cerca de 90% dos casos, de evolução favorável, na\nmaioria dos casos, com cura sem sequelas.","E":"É doença secundária a distúrbios metabólicos, tem na forma necro-hemorrágica sua maior\nincidência. O tratamento é sempre cirúrgico."},"answer":"D","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-127206","number":"127206","sourceNumber":"127206","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"São fatores de risco para cálculos de colesterol na vesícula biliar, EXCETO:","options":{"A":"Multiparidade.","B":"Obesidade.","C":"Perda rápida de peso.","D":"Nutrição parenteral total.","E":"Anemia falciforme."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-106416","number":"106416","sourceNumber":"106416","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Em qual dos seguintes pacientes está mais indicado o tratamento cirúrgico da\ndiverticulite aguda?","options":{"A":"Mulher jovem, 40 anos, com artrite reumatoide e em uso de infliximabe e prednisona.","B":"Mulher de 63 anos com diverticulite no cólon descendente e estenose distal.","C":"Mulher de 70 anos com doença renal terminal e espessura da parede do cólon de 8 mm na TC\nde\n\nabdome.","D":"Homem de 77 anos com 2 episódios de diverticulite nos últimos 2 anos.","E":"Nenhum dos pacientes acima necessita de tratamento cirúrgico para diverticulite."},"answer":"B","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-106446","number":"106446","sourceNumber":"106446","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Qual é a causa mais comum para se indicar tratamento cirúrgico em um paciente com\npancreatite crônica?","options":{"A":"Obstrução duodenal.","B":"Obstrução do colédoco.","C":"Dor incessante.","D":"Formação de pseudocisto.","E":"Hemorragia."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-106449","number":"106449","sourceNumber":"106449","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"G.A.P.B., 30 anos, masculino, deu entrada em hospital terciário com dor abdominal em\nepigástrio, com irradiação para hipocôndrios e dorso, associado a náuseas e vômitos, com piora à\nalimentação, de início há cerca de 1 dia. Exames de entrada: Hb: 16,1g/dL, Ht: 48,2 %, Leucócitos:\n\n15.000 (sem desvio à esquerda), LDH: 350 U/L, Glicose: 108mg/dl, Ur: 49, Cr: 1,1 , TGO: 56 ,TGP:\n45, FA: 140, GAMA-GT: 56, Bilirrubina\ntotal: 0,82, PCR: 45, Ca: 9,1, PaO2: 120, amilase: 1734,\nlipase: 2230, ultrassonografia prévia (há 03 meses) com colelitíase. Qual a melhor conduta neste\nmomento?","options":{"A":"Solicitar nova Ultrassonografia de abdome.","B":"Solicitar Tomografia Computadorizada de abdome.","C":"Dieta zero, analgesia, antieméticos, colecistectomia laparoscópica.","D":"Dieta zero, analgesia, antieméticos, hidratação venosa.","E":"Colangiopancreatografia endoscópica retrógrada (CPRE)."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-106455","number":"106455","sourceNumber":"106455","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Sobre laparoscopia, assinale a alternativa correta:","options":{"A":"Está contraindicada no trauma abdominal.","B":"O melhor tratamento para crise de colecistite aguda litiásica é a colecistectomia\nvideolaparoscópica, com exceção em casos\ngraves de necrose de vesícula biliar com perfuração de\nsua parede e coleperitônio.","C":"O melhor tratamento operatório para apendicite aguda é o videolaparoscópico, independente do\ntempo de evolução da doença.","D":"O paciente portador de pancreatite aguda biliar deverá ser submetido à colecistectomia nas\nprimeiras 48 horas do início do quadro.","E":"A colecistectomia por via laparoscópica é contraindicada em pacientes previamente operados no\nandar supramesocólico."},"answer":"C","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-100954","number":"100954","sourceNumber":"100954","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"RMP, 58 anos, homem, com quadro de diverticulite aguda, perfurada, com peritonite\ndifusa e sepse. A melhor conduta é:","options":{"A":"Tratamento clínico isolado.","B":"Drenagem das coleções guiada por tomografia computadorizada.","C":"Laparoscopia + lavagem e drenagem da cavidade abdominal.","D":"Colostomia derivativa.","E":"Operação de Hartmann (ressecção sigmoideana + colostomia proximal e sepultamento do coto\nretal distal)."},"answer":"E","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-04-87416","number":"87416","sourceNumber":"87416","collectionBlock":"med:med-cirurgia-med-cir-04","collectionLabel":"MED · MED CIR 04","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 04","subtopic":"","stem":"Rapaz de 18 anos vem ao consultório apresentando dor em fossa ilíaca direita, vômitos\ne prostração. Qual o sinal/sintoma fundamental\npara o diagnóstico de apendicite aguda?","options":{"A":"Sinal de Blumberg.","B":"Sinal de Rovsing.","C":"Diarreia.","D":"Anorexia.","E":"Sinal do Psoas."},"answer":"A","source":"Cirurgia/MED CIR 04/MED CIR 04.txt","sourceLabel":"MED · MED CIR 04","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 04","MED"],"answerSource":"inferred","commentDeferred":true}]};
